INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('01ee62ad-0a1c-5f20-a6e6-298a07dbad16', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 16, 16, '"''But if he struck him with an instrument of iron, so that he died, he is a murderer: the murderer shall surely be put to death.'),
  ('c03a9cae-f592-54f6-a69e-0fc1b7ce13d4', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 17, 17, 'If he struck him with a stone in the hand, by which a man may die, and he died, he is a murderer: the murderer shall surely be put to death.'),
  ('e87535e1-f39a-59f7-ad05-7ab7f8dd54e5', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 18, 18, 'Or if he struck him with a weapon of wood in the hand, by which a man may die, and he died, he is a murderer: the murderer shall surely be put to death.'),
  ('9ab5472d-4efa-53d3-ac1d-253acb014fe5', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 19, 19, 'The avenger of blood shall himself put the murderer to death: when he meets him, he shall put him to death.'),
  ('fb805c74-4810-5df2-a22b-9b07a605e2bb', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 20, 20, 'If he thrust him of hatred, or hurled at him, lying in wait, so that he died,'),
  ('e4e3d195-6d0e-5b8f-aece-e6a18c9f365f', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 21, 21, 'or in enmity struck him with his hand, so that he died; he who struck him shall surely be put to death; he is a murderer: the avenger of blood shall put the murderer to death, when he meets him.'),
  ('2f232ac0-b270-55c5-a81a-361a43cee6a9', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 22, 22, '"''But if he thrust him suddenly without enmity, or hurled on him anything without lying in wait,'),
  ('f544f6b6-810f-5aaa-adfa-54521c844bdc', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 23, 23, 'or with any stone, by which a man may die, not seeing him, and cast it on him, so that he died, and he was not his enemy, neither sought his harm;'),
  ('ba255c20-52fb-5ee7-a7df-2e1ee0c4a4f0', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 24, 24, 'then the congregation shall judge between the striker and the avenger of blood according to these ordinances;'),
  ('d50cb0e3-21b9-59e2-aab6-3acb209886f9', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 25, 25, 'and the congregation shall deliver the manslayer out of the hand of the avenger of blood, and the congregation shall restore him to his city of refuge, where he was fled: and he shall dwell therein until the death of the high priest, who was anointed with the holy oil.'),
  ('e5dd1a7b-c2be-58ba-a9a7-2a6fdde3dbbe', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 26, 26, '"''But if the manslayer shall at any time go beyond the border of his city of refuge, where he flees,'),
  ('b8b07c11-8c1d-59b2-a077-1e1be869eb39', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 27, 27, 'and the avenger of blood find him outside of the border of his city of refuge, and the avenger of blood kill the manslayer; he shall not be guilty of blood,'),
  ('e75f8ebc-7dd5-5d91-a4f3-f4f0728913f3', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 28, 28, 'because he should have remained in his city of refuge until the death of the high priest: but after the death of the high priest the manslayer shall return into the land of his possession.'),
  ('a822663d-5ae6-5b2e-a9cf-7378c8207dda', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 29, 29, '"''These things shall be for a statute [and] ordinance to you throughout your generations in all your dwellings.'),
  ('1fb24fe9-c8a0-5e55-a46d-8808f64492fb', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 30, 30, '"''Whoever kills any person, the murderer shall be slain at the mouth of witnesses: but one witness shall not testify against any person that he die.'),
  ('89ae9daf-8206-5525-a32a-6c5332950705', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 31, 31, '"''Moreover you shall take no ransom for the life of a murderer who is guilty of death; but he shall surely be put to death.'),
  ('18a48d0c-f25d-543b-a7b8-2bca0b2fed81', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 32, 32, '"''You shall take no ransom for him who is fled to his city of refuge, that he may come again to dwell in the land, until the death of the priest.'),
  ('d81e070e-6adf-51d2-acb0-1bb8ec9ebaea', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 33, 33, '"''So you shall not pollute the land in which you are: for blood, it pollutes the land; and no expiation can be made for the land for the blood that is shed therein, but by the blood of him who shed it.'),
  ('0702e2de-9099-5a55-a21a-e21b309f853f', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 34, 34, 'You shall not defile the land which you inhabit, in the midst of which I dwell: for I, Yahweh, dwell in the midst of the children of Israel.''"'),
  ('66ea284c-6c5f-5a10-a588-f4c51955449c', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 1, 1, 'The heads of the fathers'' [houses] of the family of the children of Gilead, the son of Machir, the son of Manasseh, of the families of the sons of Joseph, came near, and spoke before Moses, and before the princes, the heads of the fathers'' [houses] of the children of Israel:'),
  ('679ca4c4-f8ab-5245-a349-cd89f87b6bdd', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 2, 2, 'and they said, "Yahweh commanded my lord to give the land for inheritance by lot to the children of Israel: and my lord was commanded by Yahweh to give the inheritance of Zelophehad our brother to his daughters.'),
  ('23dbfd64-8e33-5487-a31f-bc218c7d5835', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 3, 3, 'If they are married to any of the sons of the [other] tribes of the children of Israel, then will their inheritance be taken away from the inheritance of our fathers, and will be added to the inheritance of the tribe whereunto they shall belong: so will it be taken away from the lot of our inheritance.'),
  ('7c33465d-dbd8-5982-a258-3ea26676bfa7', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 4, 4, 'When the jubilee of the children of Israel shall be, then will their inheritance be added to the inheritance of the tribe whereunto they shall belong: so will their inheritance be taken away from the inheritance of the tribe of our fathers."'),
  ('d802f649-e864-59ff-aac0-d4351637d408', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 5, 5, 'Moses commanded the children of Israel according to the word of Yahweh, saying, "The tribe of the sons of Joseph speaks right.'),
  ('fe4cc1c0-18fc-53ad-a999-ef781b501283', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 6, 6, 'This is the thing which Yahweh does command concerning the daughters of Zelophehad, saying, Let them be married to whom they think best; only into the family of the tribe of their father shall they be married.'),
  ('ab61d682-068e-5778-a8a2-2a4baf765e41', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 7, 7, 'So shall no inheritance of the children of Israel remove from tribe to tribe; for the children of Israel shall all keep the inheritance of the tribe of his fathers.'),
  ('c653481a-eda3-5186-a16f-9dba1e48fb98', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 8, 8, 'Every daughter who possesses an inheritance in any tribe of the children of Israel shall be wife to one of the family of the tribe of her father, that the children of Israel may possess every man the inheritance of his fathers.'),
  ('dba3e152-a34b-5e30-a6ca-901759248906', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 9, 9, 'So shall no inheritance remove from one tribe to another tribe; for the tribes of the children of Israel shall each keep his own inheritance."'),
  ('9b535022-6b2e-5383-ad39-4f29e2ed725c', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 10, 10, 'The daughters of Zelophehad did as Yahweh commanded Moses:'),
  ('10136378-e69c-58df-a662-5765675034c8', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 11, 11, 'for Mahlah, Tirzah, and Hoglah, and Milcah, and Noah, the daughters of Zelophehad, were married to their father''s brothers'' sons.'),
  ('7fc00101-cd6a-5df4-af56-67a3a44fcc32', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 12, 12, 'They were married into the families of the sons of Manasseh the son of Joseph; and their inheritance remained in the tribe of the family of their father.'),
  ('ae6fe0ef-22cf-5920-abb6-d24f90140fb9', '3a655b9d-1d2c-5f47-a821-f1bf7e6184f4', NULL, 13, 13, 'These are the commandments and the ordinances which Yahweh commanded by Moses to the children of Israel in the plains of Moab by the Jordan at Jericho.'),
  ('b3988e53-51c2-58a4-a0d9-37dcedeff56f', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 1, 1, 'These are the words which Moses spoke to all Israel beyond the Jordan in the wilderness, in the Arabah over against Suph, between Paran, and Tophel, and Laban, and Hazeroth, and Dizahab.'),
  ('6b5c3799-e92d-5e8d-a191-c1c76667042a', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 2, 2, 'It is eleven days'' [journey] from Horeb by the way of Mount Seir to Kadesh Barnea.'),
  ('2c4e7605-6720-5478-acfd-8c01d1085fa7', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 3, 3, 'It happened in the fortieth year, in the eleventh month, on the first day of the month, that Moses spoke to the children of Israel, according to all that Yahweh had given him in commandment to them;'),
  ('b9bf3e08-2647-5f5d-ad5e-c1b7532c53c8', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 4, 4, 'after he had struck Sihon the king of the Amorites, who lived in Heshbon, and Og the king of Bashan, who lived in Ashtaroth, at Edrei.'),
  ('265f2dc6-3604-5489-a6ba-d7a79ad6d716', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 5, 5, 'Beyond the Jordan, in the land of Moab, began Moses to declare this law, saying,'),
  ('6e9752ea-6142-5ed3-a7e2-9f8e477496fa', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 6, 6, '"Yahweh our God spoke to us in Horeb, saying, You have lived long enough in this mountain:'),
  ('4eeab50e-3486-558a-a9a3-e4d0acde0ac2', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 7, 7, 'turn, and take your journey, and go to the hill country of the Amorites, and to all [the places] near there, in the Arabah, in the hill country, and in the lowland, and in the South, and by the seashore, the land of the Canaanites, and Lebanon, as far as the great river, the river Euphrates.'),
  ('69225b7d-c326-51e9-ac90-48ccf1f6c376', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 8, 8, 'Behold, I have set the land before you: go in and possess the land which Yahweh swore to your fathers, to Abraham, to Isaac, and to Jacob, to give to them and to their seed after them."'),
  ('7f0d2a9a-c0c4-5cd1-a3aa-f962c8b0f369', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 9, 9, 'I spoke to you at that time, saying, "I am not able to bear you myself alone:'),
  ('9bc8a342-835a-5f03-a365-254862169797', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 10, 10, 'Yahweh your God has multiplied you, and behold, you are this day as the stars of the sky for multitude.'),
  ('f747c982-2774-5d96-a234-1948c712eb5b', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 11, 11, 'Yahweh, the God of your fathers, make you a thousand times as many as you are, and bless you, as he has promised you!'),
  ('a070501c-ccce-51fc-aaa2-98f57e2e66a3', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 12, 12, 'How can I myself alone bear your encumbrance, and your burden, and your strife?'),
  ('a4ad1179-0d6a-5050-af09-839d80646898', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 13, 13, 'Take wise men of understanding and well known according to your tribes, and I will make them heads over you."'),
  ('3a0a9d50-bf0d-5710-a4ef-cd6a7298ac31', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 14, 14, 'You answered me, and said, "The thing which you have spoken is good [for us] to do."'),
  ('a5c934c7-c25d-5bf9-af6b-8f50b20dc01e', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 15, 15, 'So I took the heads of your tribes, wise men, and known, and made them heads over you, captains of thousands, and captains of hundreds, and captains of fifties, and captains of tens, and officers, according to your tribes.'),
  ('f624d25c-26d8-5c2e-a858-3e5b99eafc3e', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 16, 16, 'I commanded your judges at that time, saying, Hear [the causes] between your brothers, and judge righteously between a man and his brother, and the foreigner who is living with him.'),
  ('baa3417d-bc2e-567a-abc4-35c126aaa24b', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 17, 17, 'You shall not show partiality in judgment; you shall hear the small and the great alike; you shall not be afraid of the face of man; for the judgment is God''s: and the cause that is too hard for you, you shall bring to me, and I will hear it.'),
  ('fcfb3a34-80d0-5ced-ae47-681b3ca53089', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 18, 18, 'I commanded you at that time all the things which you should do.'),
  ('767de826-f38b-5976-afbc-79388317dfe7', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 19, 19, 'We traveled from Horeb, and went through all that great and terrible wilderness which you saw, by the way to the hill country of the Amorites, as Yahweh our God commanded us; and we came to Kadesh Barnea.'),
  ('45f32879-fccb-5a90-a49c-746e4a9f199b', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 20, 20, 'I said to you, "You have come to the hill country of the Amorites, which Yahweh our God gives to us.'),
  ('d1af8f63-9388-542b-a0b8-1d2d873074c2', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 21, 21, 'Behold, Yahweh your God has set the land before you: go up, take possession, as Yahweh, the God of your fathers, has spoken to you; don''t be afraid, neither be dismayed."'),
  ('6351930a-b8fe-509f-ab32-cf22d6249dbf', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 22, 22, 'You came near to me everyone of you, and said, "Let us send men before us, that they may search the land for us, and bring us word again of the way by which we must go up, and the cities to which we shall come."'),
  ('815d83cd-01c8-5331-aea0-390d2df327cc', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 23, 23, 'The thing pleased me well; and I took twelve men of you, one man for every tribe:'),
  ('10a06fbb-09ab-53e7-a236-13e2d54edf93', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 24, 24, 'and they turned and went up into the hill country, and came to the valley of Eshcol, and spied it out.'),
  ('cc609b62-5c81-580d-a3f0-544ac0dc8335', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 25, 25, 'They took of the fruit of the land in their hands, and brought it down to us, and brought us word again, and said, "It is a good land which Yahweh our God gives to us."'),
  ('eba05df5-5c55-5317-a939-5b611aeaa73d', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 26, 26, 'Yet you wouldn''t go up, but rebelled against the commandment of Yahweh your God:'),
  ('75535310-7856-52a0-a07f-26ba2e5f1542', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 27, 27, 'and you murmured in your tents, and said, "Because Yahweh hated us, he has brought us forth out of the land of Egypt, to deliver us into the hand of the Amorites, to destroy us.'),
  ('a509d012-1c5c-534d-a456-ec0a5f65ce41', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 28, 28, 'Where are we going up? our brothers have made our heart to melt, saying, ''The people are greater and taller than we; the cities are great and fortified up to the sky; and moreover we have seen the sons of the Anakim there.''"'),
  ('c044fed1-29f8-5a0c-aa23-b4487e4a01a1', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 29, 29, 'Then I said to you, "Don''t dread, neither be afraid of them.'),
  ('73d48ea1-b554-5204-a5d7-4394e4dcc76d', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 30, 30, 'Yahweh your God who goes before you, he will fight for you, according to all that he did for you in Egypt before your eyes,'),
  ('d63f4e96-678c-5d1c-a950-912a980a5305', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 31, 31, 'and in the wilderness, where you have seen how that Yahweh your God bore you, as a man does bear his son, in all the way that you went, until you came to this place."'),
  ('7dfdb041-fc04-5ca8-a136-3f0013e34aa7', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 32, 32, 'Yet in this thing you didn''t believe Yahweh your God,'),
  ('986b0dfc-7bd5-5591-ae98-6b3129ccde2e', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 33, 33, 'who went before you in the way, to seek you out a place to pitch your tents in, in fire by night, to show you by what way you should go, and in the cloud by day.'),
  ('9f2606c2-b423-5f0c-a83f-d18e772e2cd2', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 34, 34, 'Yahweh heard the voice of your words, and was angry, and swore, saying,'),
  ('37056bbc-b056-5970-a4f7-253c34eee7e1', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 35, 35, '"Surely not one of these men of this evil generation shall see the good land, which I swore to give to your fathers,'),
  ('95b0cc40-6d46-5e3c-a798-838e5b443e86', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 36, 36, 'except Caleb the son of Jephunneh: he shall see it; and to him will I give the land that he has trodden on, and to his children, because he has wholly followed Yahweh."'),
  ('e10ac503-11e9-5bc9-a452-cdf3a98e84e9', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 37, 37, 'Also Yahweh was angry with me for your sakes, saying, "You also shall not go in there:'),
  ('81f6596f-02d0-56b3-aa8d-1cfbd9f1f119', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 38, 38, 'Joshua the son of Nun, who stands before you, he shall go in there: encourage you him; for he shall cause Israel to inherit it.'),
  ('9af71843-a949-5d6b-a2fb-d23e4969ddf5', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 39, 39, 'Moreover your little ones, whom you said should be a prey, and your children, who this day have no knowledge of good or evil, they shall go in there, and to them will I give it, and they shall possess it.'),
  ('f036d99f-842c-52eb-a0fd-0413a1afb926', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 40, 40, 'But as for you, turn, and take your journey into the wilderness by the way to the Red Sea."'),
  ('588589c3-db79-53e4-a705-083ca2ffaceb', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 41, 41, 'Then you answered and said to me, "We have sinned against Yahweh, we will go up and fight, according to all that Yahweh our God commanded us." Every man of you put on his weapons of war, and presumed to go up into the hill country.'),
  ('f503e633-8d87-5a9e-a55f-206150110292', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 42, 42, 'Yahweh said to me, "Tell them, ''Don''t go up, neither fight; for I am not among you; lest you be struck before your enemies.''"'),
  ('08b1ac66-0d3e-5cdb-a929-0abacaec5ed6', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 43, 43, 'So I spoke to you, and you didn''t listen; but you rebelled against the commandment of Yahweh, and were presumptuous, and went up into the hill country.'),
  ('d93b4731-0562-5a36-a3a0-adbd4a85198c', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 44, 44, 'The Amorites, who lived in that hill country, came out against you, and chased you, as bees do, and beat you down in Seir, even to Hormah.'),
  ('ed3c1119-5507-5983-af7a-7daaadf8f61e', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 45, 45, 'You returned and wept before Yahweh; but Yahweh didn''t listen to your voice, nor gave ear to you.'),
  ('2acc9a5b-6d9f-5834-a40d-a98129b7aab3', 'd1342e11-720e-5d84-a922-94f743a16672', NULL, 46, 46, 'So you stayed in Kadesh many days, according to the days that you stayed [there].'),
  ('1468e9a3-52d7-5c11-acfe-cf72d7c15ea0', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 1, 1, 'Then we turned, and took our journey into the wilderness by the way to the Red Sea, as Yahweh spoke to me; and we encircled Mount Seir many days.'),
  ('6d91319b-d59d-5f0f-a874-17285ba6e124', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 2, 2, 'Yahweh spoke to me, saying,'),
  ('3e746075-b9e8-55eb-a7ae-06b29ad37490', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 3, 3, '"You have encircled this mountain long enough. Turn northward.'),
  ('26615c91-d48b-5ae8-aed7-82ec3fef56e7', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 4, 4, 'Command the people, saying, ''You are to pass through the border of your brothers the children of Esau, who dwell in Seir; and they will be afraid of you: take good heed to yourselves therefore;'),
  ('3b001890-0c43-5dc0-afd1-a181875450ef', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 5, 5, 'don''t contend with them; for I will not give you of their land, no, not so much as for the sole of the foot to tread on; because I have given Mount Seir to Esau for a possession.'),
  ('c62511ec-34df-5991-a3b0-dc71e063e063', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 6, 6, 'You shall purchase food of them for money, that you may eat; and you shall also buy water of them for money, that you may drink.''"'),
  ('d6a19a7d-9c19-5227-a3a4-5641f5810a59', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 7, 7, 'For Yahweh your God has blessed you in all the work of your hand; he has known your walking through this great wilderness: these forty years Yahweh your God has been with you; you have lacked nothing.'),
  ('904bcb34-f6a3-5ef5-aadc-72c6eac52a39', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 8, 8, 'So we passed by from our brothers the children of Esau, who dwell in Seir, from the way of the Arabah from Elath and from Ezion Geber. We turned and passed by the way of the wilderness of Moab.'),
  ('fd82172e-65ba-550f-a3e8-fd2bc5a1e0e1', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 9, 9, 'Yahweh said to me, "Don''t bother Moab, neither contend with them in battle; for I will not give you of his land for a possession; because I have given Ar to the children of Lot for a possession."'),
  ('56bf8776-13c0-5cf6-a269-7b049e551e26', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 10, 10, '(The Emim lived therein before, a people great, and many, and tall, as the Anakim:'),
  ('6b0cb744-97a9-5a37-a01e-ee3678715829', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 11, 11, 'these also are accounted Rephaim, as the Anakim; but the Moabites call them Emim.'),
  ('7729cd51-bb0d-583c-a084-52aa57458f73', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 12, 12, 'The Horites also lived in Seir before, but the children of Esau succeeded them; and they destroyed them from before them, and lived in their place; as Israel did to the land of his possession, which Yahweh gave to them.)'),
  ('4d3bb339-9455-5dba-a560-8caaf9844724', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 13, 13, '"Now rise up, and cross over the brook Zered." We went over the brook Zered.'),
  ('69ba56b5-9d4e-5fb0-a4db-6db6faf6c9a4', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 14, 14, 'The days in which we came from Kadesh Barnea, until we were come over the brook Zered, were thirty-eight years; until all the generation of the men of war were consumed from the midst of the camp, as Yahweh swore to them.'),
  ('a6bad54b-01cd-5a30-aec8-60b50ecf90ff', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 15, 15, 'Moreover the hand of Yahweh was against them, to destroy them from the midst of the camp, until they were consumed.'),
  ('4eda2419-c172-56c1-a89e-bf421c051a72', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 16, 16, 'So it happened, when all the men of war were consumed and dead from among the people,'),
  ('f0dfa881-0d3f-5683-a8df-7ecebee01be3', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 17, 17, 'that Yahweh spoke to me, saying,'),
  ('0a122eec-a7ca-51ab-a184-e9439c2f03fb', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 18, 18, '"You are this day to pass over Ar, the border of Moab:'),
  ('c989aca8-1b08-596d-a907-9a2f7a14391c', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 19, 19, 'and when you come near over against the children of Ammon, don''t bother them, nor contend with them; for I will not give you of the land of the children of Ammon for a possession; because I have given it to the children of Lot for a possession."'),
  ('e76074ff-7b59-5ed7-acbb-495400843e14', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 20, 20, '(That also is accounted a land of Rephaim: Rephaim lived therein before; but the Ammonites call them Zamzummim,'),
  ('c8bf65ae-7ca9-53cc-a7ab-e4cd19f78586', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 21, 21, 'a people great, and many, and tall, as the Anakim; but Yahweh destroyed them before them; and they succeeded them, and lived in their place;'),
  ('8c99c400-fbd4-555c-a689-1717ac4b4055', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 22, 22, 'as he did for the children of Esau, who dwell in Seir, when he destroyed the Horites from before them; and they succeeded them, and lived in their place even to this day:'),
  ('c69a4ec6-fbf2-526c-ac56-58c39f5093b6', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 23, 23, 'and the Avvim, who lived in villages as far as Gaza, the Caphtorim, who came forth out of Caphtor, destroyed them, and lived in their place.)'),
  ('dd3c4501-08fd-5d04-a15b-0998529e0d19', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 24, 24, '"Rise up, take your journey, and pass over the valley of the Arnon: behold, I have given into your hand Sihon the Amorite, king of Heshbon, and his land; begin to possess it, and contend with him in battle.'),
  ('bf4131ff-95ac-5643-a67e-be6a0ab6d320', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 25, 25, 'This day will I begin to put the dread of you and the fear of you on the peoples who are under the whole sky, who shall hear the report of you, and shall tremble, and be in anguish because of you."'),
  ('c789ee1d-d101-5163-a31a-34af1a8a491f', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 26, 26, 'I sent messengers out of the wilderness of Kedemoth to Sihon king of Heshbon with words of peace, saying,'),
  ('0fcacf6b-08fa-5827-a0ad-4256a2aa6102', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 27, 27, '"Let me pass through your land: I will go along by the highway, I will turn neither to the right hand nor to the left.'),
  ('00d4518a-6b85-5a1c-a33e-c827081813e0', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 28, 28, 'You shall sell me food for money, that I may eat; and give me water for money, that I may drink: only let me pass through on my feet,'),
  ('2608e971-f22b-5af1-aefd-24198df53a17', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 29, 29, 'as the children of Esau who dwell in Seir, and the Moabites who dwell in Ar, did to me; until I shall pass over the Jordan into the land which Yahweh our God gives us."'),
  ('984ef38a-0516-58c2-aa9b-ae5c4db65972', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 30, 30, 'But Sihon king of Heshbon would not let us pass by him; for Yahweh your God hardened his spirit, and made his heart obstinate, that he might deliver him into your hand, as at this day.'),
  ('c06f5bda-64dd-5d6d-ab14-551712c53d8a', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 31, 31, 'Yahweh said to me, "Behold, I have begun to deliver up Sihon and his land before you: begin to possess, that you may inherit his land."'),
  ('509cee0b-9a42-5129-a958-2143f9149bbf', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 32, 32, 'Then Sihon came out against us, he and all his people, to battle at Jahaz.'),
  ('9ec3f754-2bcb-5eb2-a3a6-8425455baf64', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 33, 33, 'Yahweh our God delivered him up before us; and we struck him, and his sons, and all his people.'),
  ('8be5d59f-f5ea-5cbf-a87a-924829f3ba48', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 34, 34, 'We took all his cities at that time, and utterly destroyed every inhabited city, with the women and the little ones; we left none remaining:'),
  ('6b3f299d-1bc2-532f-a166-886fa4aadc2f', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 35, 35, 'only the livestock we took for a prey to ourselves, with the spoil of the cities which we had taken.'),
  ('60c3e1b4-e205-5552-a171-0ab015062071', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 36, 36, 'From Aroer, which is on the edge of the valley of the Arnon, and [from] the city that is in the valley, even to Gilead, there was not a city too high for us; Yahweh our God delivered up all before us:'),
  ('c59e82b3-54c6-5af8-a234-410d2459801e', '6837c659-5530-5a5a-a9c8-b72dfa1a6a42', NULL, 37, 37, 'only to the land of the children of Ammon you didn''t come near; all the side of the river Jabbok, and the cities of the hill country, and wherever Yahweh our God forbade us.'),
  ('b8816393-7691-5103-aea5-a2557b71b595', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 1, 1, 'Then we turned, and went up the way to Bashan: and Og the king of Bashan came out against us, he and all his people, to battle at Edrei.'),
  ('b37f3bf3-96d5-53eb-ac75-7b635d05bdde', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 2, 2, 'Yahweh said to me, "Don''t fear him; for I have delivered him, and all his people, and his land, into your hand; and you shall do to him as you did to Sihon king of the Amorites, who lived at Heshbon."'),
  ('8cad1e31-8b61-5d03-a27c-b2f6c7ad500a', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 3, 3, 'So Yahweh our God delivered into our hand Og also, the king of Bashan, and all his people: and we struck him until none was left to him remaining.'),
  ('578e0034-5c49-583d-a736-1bb87f104f3d', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 4, 4, 'We took all his cities at that time; there was not a city which we didn''t take from them; sixty cities, all the region of Argob, the kingdom of Og in Bashan.'),
  ('88ec2278-7b78-562a-a4e1-a13f3900524e', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 5, 5, 'All these were cities fortified with high walls, gates, and bars; besides the unwalled towns a great many.'),
  ('37900e9c-5dad-58c4-a03b-a4b601d8d4d8', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 6, 6, 'We utterly destroyed them, as we did to Sihon king of Heshbon, utterly destroying every inhabited city, with the women and the little ones.'),
  ('1fb8c3fd-126e-5f7e-aaf0-8ffaeafb228f', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 7, 7, 'But all the livestock, and the spoil of the cities, we took for a prey to ourselves.'),
  ('5e93d8c1-66ba-5de5-ab10-1ad1add3fda8', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 8, 8, 'We took the land at that time out of the hand of the two kings of the Amorites who were beyond the Jordan, from the valley of the Arnon to Mount Hermon;'),
  ('35c044cc-0f14-52c3-ad5d-8d3b89ac4a97', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 9, 9, '([which] Hermon the Sidonians call Sirion, and the Amorites call it Senir;)'),
  ('3971fe14-c536-53d4-ae39-e00206e21ce4', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 10, 10, 'all the cities of the plain, and all Gilead, and all Bashan, to Salecah and Edrei, cities of the kingdom of Og in Bashan.'),
  ('b186d83d-df87-5603-a268-b226b631e951', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 11, 11, '(For only Og king of Bashan remained of the remnant of the Rephaim; behold, his bedstead was a bedstead of iron; isn''t it in Rabbah of the children of Ammon? nine cubits was its length, and four cubits its breadth, after the cubit of a man.)'),
  ('c8a6f29d-1d0a-5358-a903-a09d74a5fb36', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 12, 12, 'This land we took in possession at that time: from Aroer, which is by the valley of the Arnon, and half the hill country of Gilead, and its cities, gave I to the Reubenites and to the Gadites:'),
  ('541e200d-4827-5812-a43d-48950cfac9da', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 13, 13, 'and the rest of Gilead, and all Bashan, the kingdom of Og, gave I to the half-tribe of Manasseh; all the region of Argob, even all Bashan. (The same is called the land of Rephaim.'),
  ('eab256e7-f130-5274-adb7-c403164dee2e', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 14, 14, 'Jair the son of Manasseh took all the region of Argob, to the border of the Geshurites and the Maacathites, and called them, even Bashan, after his own name, Havvoth Jair, to this day.)'),
  ('d7f7cc97-8986-5209-adfc-209338016e7f', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 15, 15, 'I gave Gilead to Machir.'),
  ('1d27e7ab-54cd-5e2b-a87a-6d6e614d9b4a', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 16, 16, 'To the Reubenites and to the Gadites I gave from Gilead even to the valley of the Arnon, the middle of the valley, and the border [of it], even to the river Jabbok, which is the border of the children of Ammon;'),
  ('b28cca29-3de2-517d-a03c-fcf90abfd630', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 17, 17, 'the Arabah also, and the Jordan and the border [of it], from Chinnereth even to the sea of the Arabah, the Salt Sea, under the slopes of Pisgah eastward.'),
  ('542e2860-459a-5259-a08b-bcbcf9e47716', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 18, 18, 'I commanded you at that time, saying, "Yahweh your God has given you this land to possess it: you shall pass over armed before your brothers the children of Israel, all the men of valor.'),
  ('b1334cdd-dbf2-5a27-a414-3453dd647c40', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 19, 19, 'But your wives, and your little ones, and your livestock, (I know that you have much livestock), shall live in your cities which I have given you,'),
  ('b947bd0e-07c6-513f-a7d5-8bf1591a983e', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 20, 20, 'until Yahweh gives rest to your brothers, as to you, and they also possess the land which Yahweh your God gives them beyond the Jordan: then you shall return every man to his possession, which I have given you."'),
  ('83c63887-dcef-5b13-ac62-8bc9f50db245', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 21, 21, 'I commanded Joshua at that time, saying, "Your eyes have seen all that Yahweh your God has done to these two kings: so shall Yahweh do to all the kingdoms where you go over.'),
  ('715c9035-d1c6-563a-aca7-b2b63ed2082c', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 22, 22, 'You shall not fear them; for Yahweh your God, he it is who fights for you."'),
  ('4060c045-5fdc-5161-aed1-fbd914991359', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 23, 23, 'I begged Yahweh at that time, saying,'),
  ('ccf1268a-1245-5e86-affd-c0eefc5336ce', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 24, 24, '"Lord Yahweh, you have begun to show your servant your greatness, and your strong hand: for what god is there in heaven or in earth, that can do according to your works, and according to your mighty acts?'),
  ('c960d7e4-d30d-5548-a2c8-c805e92622da', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 25, 25, 'Please let me go over and see the good land that is beyond the Jordan, that goodly mountain, and Lebanon."'),
  ('e279b727-59ba-528b-a68f-b8c35792f179', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 26, 26, 'But Yahweh was angry with me for your sakes, and didn''t listen to me; and Yahweh said to me, "Let it suffice you; speak no more to me of this matter.'),
  ('5c998e38-a11a-5271-a6e1-737f9cf61ee4', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 27, 27, 'Go up to the top of Pisgah, and lift up your eyes westward, and northward, and southward, and eastward, and see with your eyes: for you shall not go over this Jordan.'),
  ('e7476aed-a354-5dcc-a9c1-27ccbb1a97d1', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 28, 28, 'But commission Joshua, and encourage him, and strengthen him; for he shall go over before this people, and he shall cause them to inherit the land which you shall see."'),
  ('c3a12542-9d78-5f17-a488-74677a3c04eb', '38ef9039-f77a-5b10-acb2-e91c018b2314', NULL, 29, 29, 'So we stayed in the valley over against Beth Peor.'),
  ('f349dbd1-2e41-5d6a-ad00-fd811b73e089', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 1, 1, 'Now, Israel, listen to the statutes and to the ordinances, which I teach you, to do them; that you may live, and go in and possess the land which Yahweh, the God of your fathers, gives you.'),
  ('b76cc18b-300c-5d5d-a0e1-a8f872711a84', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 2, 2, 'You shall not add to the word which I command you, neither shall you diminish from it, that you may keep the commandments of Yahweh your God which I command you.'),
  ('d6351fc6-ffeb-5e8e-a542-79fd16d32d7b', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 3, 3, 'Your eyes have seen what Yahweh did because of Baal Peor; for all the men who followed Baal Peor, Yahweh your God has destroyed them from the midst of you.'),
  ('543c7d34-8362-5dfe-ab8d-3db45085a6bd', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 4, 4, 'But you who did cling to Yahweh your God are all alive this day.'),
  ('751120c1-3ac1-5610-ad42-aa5fdae2a9a5', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 5, 5, 'Behold, I have taught you statutes and ordinances, even as Yahweh my God commanded me, that you should do so in the midst of the land where you go in to possess it.'),
  ('c7611980-5bef-59bb-a17b-e7bdb8235228', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 6, 6, 'Keep therefore and do them; for this is your wisdom and your understanding in the sight of the peoples, who shall hear all these statutes, and say, "Surely this great nation is a wise and understanding people."'),
  ('a3ad4b85-65b4-55e3-a824-569a575513b8', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 7, 7, 'For what great nation is there, that has a god so near to them, as Yahweh our God is whenever we call on him?'),
  ('4364097b-93cd-534c-a48d-fe841ecd6fa1', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 8, 8, 'What great nation is there, that has statutes and ordinances so righteous as all this law, which I set before you this day?'),
  ('e75887e0-be45-5bb1-a06a-e6adcfd09844', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 9, 9, 'Only take heed to yourself, and keep your soul diligently, lest you forget the things which your eyes saw, and lest they depart from your heart all the days of your life; but make them known to your children and your children''s children;'),
  ('da55f947-4f78-53e1-ab15-2154a359e0ef', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 10, 10, 'the day that you stood before Yahweh your God in Horeb, when Yahweh said to me, "Assemble me the people, and I will make them hear my words, that they may learn to fear me all the days that they live on the earth, and that they may teach their children."'),
  ('2a283598-d064-50ea-af62-3a6f8cec0d63', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 11, 11, 'You came near and stood under the mountain; and the mountain burned with fire to the heart of the sky, with darkness, cloud, and thick darkness.'),
  ('11477d98-705c-51cf-afd9-902bdc6a78f5', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 12, 12, 'Yahweh spoke to you out of the midst of the fire: you heard the voice of words, but you saw no form; only [you heard] a voice.'),
  ('f6856a85-7bdb-5a28-ad31-1f799625af55', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 13, 13, 'He declared to you his covenant, which he commanded you to perform, even the ten commandments; and he wrote them on two tables of stone.'),
  ('6b3904d1-7ad3-5f67-a801-4336ee0a60f0', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 14, 14, 'Yahweh commanded me at that time to teach you statutes and ordinances, that you might do them in the land where you go over to possess it.'),
  ('582ac5ac-c551-5707-a117-05ccd7fc33a0', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 15, 15, 'Take therefore good heed to yourselves; for you saw no kind of form on the day that Yahweh spoke to you in Horeb out of the midst of the fire.'),
  ('7665a4ee-8e2d-538c-a324-1c871f3e576a', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 16, 16, 'Lest you corrupt yourselves, and make yourself an engraved image in the form of any figure, the likeness of male or female,'),
  ('8e44fb07-3aad-588a-aff1-8053767d500b', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 17, 17, 'the likeness of any animal that is on the earth, the likeness of any winged bird that flies in the sky,'),
  ('3c8aad2e-9d3e-56a4-a9f0-2e0b94d416d6', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 18, 18, 'the likeness of anything that creeps on the ground, the likeness of any fish that is in the water under the earth;'),
  ('9544743f-f68f-520e-ad59-aa84f9926f8e', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 19, 19, 'and lest you lift up your eyes to the sky, and when you see the sun and the moon and the stars, even all the army of the sky, you are drawn away and worship them, and serve them, which Yahweh your God has allotted to all the peoples under the whole sky.'),
  ('58a9bd36-4c8d-5d66-a6af-cf6963094ced', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 20, 20, 'But Yahweh has taken you, and brought you forth out of the iron furnace, out of Egypt, to be to him a people of inheritance, as at this day.'),
  ('efade9a3-f879-5cbb-afaa-982d53252538', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 21, 21, 'Furthermore Yahweh was angry with me for your sakes, and swore that I should not go over the Jordan, and that I should not go in to that good land, which Yahweh your God gives you for an inheritance:'),
  ('a79c597c-e103-58e2-ae8a-31c552a2dc94', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 22, 22, 'but I must die in this land, I must not go over the Jordan; but you shall go over, and possess that good land.'),
  ('e619f9ae-0a5d-5852-aae7-21c0b00200b3', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 23, 23, 'Take heed to yourselves, lest you forget the covenant of Yahweh your God, which he made with you, and make you an engraved image in the form of anything which Yahweh your God has forbidden you.'),
  ('76a7c06b-bc64-5ec6-a940-c51469c9346f', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 24, 24, 'For Yahweh your God is a devouring fire, a jealous God.'),
  ('5815be9c-ca22-5f3a-a935-298bf4a7f2b6', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 25, 25, 'When you shall father children, and children''s children, and you shall have been long in the land, and shall corrupt yourselves, and make an engraved image in the form of anything, and shall do that which is evil in the sight of Yahweh your God, to provoke him to anger;'),
  ('9bfb148b-cff3-519c-a308-b2694e6f5aaa', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 26, 26, 'I call heaven and earth to witness against you this day, that you shall soon utterly perish from off the land whereunto you go over the Jordan to possess it; you shall not prolong your days on it, but shall utterly be destroyed.'),
  ('9c5f683a-a26b-5834-a1b2-b1a51cbe7df5', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 27, 27, 'Yahweh will scatter you among the peoples, and you shall be left few in number among the nations, where Yahweh shall lead you away.'),
  ('be5f67ac-04c1-5df0-ad96-f090d25b0856', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 28, 28, 'There you shall serve gods, the work of men''s hands, wood and stone, which neither see, nor hear, nor eat, nor smell.'),
  ('334681b1-0f9d-5365-a0ab-8049a3d42ccd', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 29, 29, 'But from there you shall seek Yahweh your God, and you shall find him, when you search after him with all your heart and with all your soul.'),
  ('6c7de677-1af8-5e93-a249-6cb03497a086', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 30, 30, 'When you are in oppression, and all these things are come on you, in the latter days you shall return to Yahweh your God, and listen to his voice:'),
  ('c4a4372e-b11f-5c5e-ae39-6594dc28418f', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 31, 31, 'for Yahweh your God is a merciful God; he will not fail you, neither destroy you, nor forget the covenant of your fathers which he swore to them.'),
  ('40c5f020-ff88-53ee-aac2-d1203d24ce9c', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 32, 32, 'For ask now of the days that are past, which were before you, since the day that God created man on the earth, and from the one end of the sky to the other, whether there has been [any such thing] as this great thing is, or has been heard like it?'),
  ('68048fb6-7727-5887-acd2-6bc6fdbfec94', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 33, 33, 'Did ever a people hear the voice of God speaking out of the midst of the fire, as you have heard, and live?'),
  ('7ea4c961-a478-5d98-af3b-4b8bb87c5bef', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 34, 34, 'Or has God tried to go and take him a nation from the midst of [another] nation, by trials, by signs, and by wonders, and by war, and by a mighty hand, and by an outstretched arm, and by great terrors, according to all that Yahweh your God did for you in Egypt before your eyes?'),
  ('49c448d1-19f4-5ee7-a90a-4bb4aea98c21', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 35, 35, 'It was shown to you so that you might know that Yahweh is God. There is no one else besides him.'),
  ('f24e573f-9770-56aa-ae35-3f95e8ae4062', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 36, 36, 'Out of heaven he made you to hear his voice, that he might instruct you: and on earth he made you to see his great fire; and you heard his words out of the midst of the fire.'),
  ('19f40140-4b39-5f6c-a21c-102c3de65224', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 37, 37, 'Because he loved your fathers, therefore he chose their seed after them, and brought you out with his presence, with his great power, out of Egypt;'),
  ('d1ea0881-449c-5cfd-a018-a3f372aa28eb', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 38, 38, 'to drive out nations from before you greater and mightier than you, to bring you in, to give you their land for an inheritance, as at this day.'),
  ('18aa65c3-275a-59d7-ac27-a89a16dd9555', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 39, 39, 'Know therefore this day, and lay it to your heart, that Yahweh he is God in heaven above and on the earth beneath; there is none else.'),
  ('08489585-9881-5a62-aaa2-e509761d4460', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 40, 40, 'You shall keep his statutes, and his commandments, which I command you this day, that it may go well with you, and with your children after you, and that you may prolong your days in the land, which Yahweh your God gives you, forever.'),
  ('06a5fb37-b683-54af-a3f2-eb33b5ce8dbf', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 41, 41, 'Then Moses set apart three cities beyond the Jordan toward the sunrise;'),
  ('7af03dc2-3002-592f-a843-12483ef36dfc', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 42, 42, 'that the manslayer might flee there, who kills his neighbor unawares, and didn''t hate him in time past; and that fleeing to one of these cities he might live:'),
  ('24aafe23-e1ab-59a0-a90c-33b4d3dda3bc', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 43, 43, '[namely], Bezer in the wilderness, in the plain country, for the Reubenites; and Ramoth in Gilead, for the Gadites; and Golan in Bashan, for the Manassites.'),
  ('28202894-e3bf-5a18-a8fa-ff2b1ad259ba', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 44, 44, 'This is the law which Moses set before the children of Israel:'),
  ('42e16a3b-3c65-5a9f-a553-225335467a23', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 45, 45, 'these are the testimonies, and the statutes, and the ordinances, which Moses spoke to the children of Israel, when they came forth out of Egypt,'),
  ('d518834d-642c-5afb-a19d-f2ad51c2f577', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 46, 46, 'beyond the Jordan, in the valley over against Beth Peor, in the land of Sihon king of the Amorites, who lived at Heshbon, whom Moses and the children of Israel struck, when they came forth out of Egypt.'),
  ('2e01276b-b2dc-5d65-a625-bbf943004e00', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 47, 47, 'They took his land in possession, and the land of Og king of Bashan, the two kings of the Amorites, who were beyond the Jordan toward the sunrise;'),
  ('206f338b-d8ad-52f9-af9e-d4d0594e1e76', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 48, 48, 'from Aroer, which is on the edge of the valley of the Arnon, even to Mount Sion (the same is Hermon),'),
  ('d23b4754-233f-5016-ae49-e1694682c58f', 'ce90e037-0a2f-50ab-abff-5a9b21f3da15', NULL, 49, 49, 'and all the Arabah beyond the Jordan eastward, even to the sea of the Arabah, under the slopes of Pisgah.'),
  ('d905baf0-f1eb-51f2-a5e9-33b86e5ad572', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 1, 1, 'Moses called to all Israel, and said to them, Hear, Israel, the statutes and the ordinances which I speak in your ears this day, that you may learn them, and observe to do them.'),
  ('e36b470e-bbed-52ce-aa3c-7241329e3cea', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 2, 2, 'Yahweh our God made a covenant with us in Horeb.'),
  ('e8217c0e-6e3f-542d-a178-b29097ee38db', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 3, 3, 'Yahweh didn''t make this covenant with our fathers, but with us, even us, who are all of us here alive this day.'),
  ('104946ab-a0c0-528e-acf4-020d561b3bf2', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 4, 4, 'Yahweh spoke with you face to face on the mountain out of the midst of the fire,'),
  ('fc7ac2fd-bb5b-5471-af6a-f6d1f5e97c77', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 5, 5, '(I stood between Yahweh and you at that time, to show you the word of Yahweh: for you were afraid because of the fire, and didn''t go up onto the mountain;) saying,'),
  ('e0816fd6-327a-5b3a-aabe-aa767eeaf6d4', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 6, 6, '"I am Yahweh your God, who brought you out of the land of Egypt, out of the house of bondage.'),
  ('ca3b2e32-0168-54e3-a81b-a91af6690ade', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 7, 7, '"You shall have no other gods before me.'),
  ('d84faf94-dc9e-5915-ae3b-9219e3b9809b', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 8, 8, '"You shall not make an engraved image for yourself, [nor] any likeness [of anything] that is in heaven above, or that is in the earth beneath, or that is in the water under the earth:'),
  ('de33d1d1-ece8-5ebc-a6d6-48a59a0bd3c5', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 9, 9, 'you shall not bow down yourself to them, nor serve them; for I, Yahweh, your God, am a jealous God, visiting the iniquity of the fathers on the children, and on the third and on the fourth generation of those who hate me;'),
  ('2da2dee4-d513-5f5d-ae42-2eaf86af097a', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 10, 10, 'and showing loving kindness to thousands of those who love me and keep my commandments.'),
  ('6cf25a09-91b7-5e37-a73d-bee52a959bb8', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 11, 11, '"You shall not take the name of Yahweh your God in vain: for Yahweh will not hold him guiltless who takes his name in vain.'),
  ('13637fd4-c249-5a7b-a1a2-331e3384f7cf', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 12, 12, '"Observe the Sabbath day, to keep it holy, as Yahweh your God commanded you.'),
  ('41037035-26bb-58ea-a294-60d2c7c56433', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 13, 13, 'You shall labor six days, and do all your work;'),
  ('2181c41b-fcbd-5b07-adf8-8489a9821e6f', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 14, 14, 'but the seventh day is a Sabbath to Yahweh your God, in which you shall not do any work, you, nor your son, nor your daughter, nor your male servant, nor your female servant, nor your ox, nor your donkey, nor any of your livestock, nor your stranger who is within your gates; that your male servant and your female servant may rest as well as you.'),
  ('6d4ffbbb-fa49-5d65-a02d-1227bca468aa', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 15, 15, 'You shall remember that you were a servant in the land of Egypt, and Yahweh your God brought you out of there by a mighty hand and by an outstretched arm: therefore Yahweh your God commanded you to keep the Sabbath day.'),
  ('5c35836b-76e2-5989-a312-6addb2b2c6e1', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 16, 16, '"Honor your father and your mother, as Yahweh your God commanded you; that your days may be long, and that it may go well with you, in the land which Yahweh your God gives you.'),
  ('5ed416c9-6d79-52dd-a547-f6e012263073', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 17, 17, '"You shall not murder.'),
  ('abd1b518-61d3-56de-a37d-9cb746ea85bc', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 18, 18, '"Neither shall you commit adultery.'),
  ('db613571-d96d-5b67-ae3d-62d31d75d9ca', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 19, 19, '"Neither shall you steal.'),
  ('cc221d73-417c-5c9d-ad0f-fa38c3a672c2', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 20, 20, '"Neither shall you give false testimony against your neighbor.'),
  ('9cdfb2f6-7ca3-5f41-a079-361899f0d8a4', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 21, 21, '"Neither shall you covet your neighbor''s wife; neither shall you desire your neighbor''s house, his field, or his male servant, or his female servant, his ox, or his donkey, or anything that is your neighbor''s."'),
  ('8438ee1d-462e-5bdf-a56c-23fd5eb2131f', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 22, 22, 'These words Yahweh spoke to all your assembly on the mountain out of the midst of the fire, of the cloud, and of the thick darkness, with a great voice: and he added no more. He wrote them on two tables of stone, and gave them to me.'),
  ('3fd9fc1c-07fa-5f3e-a62a-3f55943ee7c1', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 23, 23, 'It happened, when you heard the voice out of the midst of the darkness, while the mountain was burning with fire, that you came near to me, even all the heads of your tribes, and your elders;'),
  ('578c5457-11b5-5ae3-a5fc-de3312fd625d', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 24, 24, 'and you said, "Behold, Yahweh our God has shown us his glory and his greatness, and we have heard his voice out of the midst of the fire: we have seen this day that God does speak with man, and he lives.'),
  ('d5e7a57c-ddb4-5bd1-a8c6-1eba632f1f42', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 25, 25, 'Now therefore why should we die? For this great fire will consume us: if we hear the voice of Yahweh our God any more, then we shall die.'),
  ('a24236aa-93b2-5c35-aa24-58887c74ddfb', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 26, 26, 'For who is there of all flesh, that has heard the voice of the living God speaking out of the midst of the fire, as we have, and lived?'),
  ('3b70a8a9-f497-56ce-ab75-49c3715f20c4', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 27, 27, 'Go near, and hear all that Yahweh our God shall say: and tell us all that Yahweh our God shall tell you; and we will hear it, and do it."'),
  ('908693d9-5513-58a0-aef4-a3837a69567f', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 28, 28, 'Yahweh heard the voice of your words, when you spoke to me; and Yahweh said to me, "I have heard the voice of the words of this people, which they have spoken to you: they have well said all that they have spoken.'),
  ('67d77bcd-4f89-560f-ab93-a62f4d3bb884', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 29, 29, 'Oh that there were such a heart in them, that they would fear me, and keep all my commandments always, that it might be well with them, and with their children forever!'),
  ('84c18d4b-f93c-567f-ab6c-618d076b96cc', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 30, 30, '"Go tell them, Return to your tents.'),
  ('ff902668-fbd3-5296-a61f-687e41a2138a', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 31, 31, 'But as for you, stand here by me, and I will tell you all the commandment, and the statutes, and the ordinances, which you shall teach them, that they may do them in the land which I give them to possess it."'),
  ('32225cfe-621b-52c7-ab87-d267458ff4f6', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 32, 32, 'You shall observe to do therefore as Yahweh your God has commanded you: you shall not turn aside to the right hand or to the left.'),
  ('c06caec0-21fb-569f-a670-0484fae32660', '763775ed-f5cf-5dae-a538-17f985577a94', NULL, 33, 33, 'You shall walk in all the way which Yahweh your God has commanded you, that you may live, and that it may be well with you, and that you may prolong your days in the land which you shall possess.'),
  ('299c518d-15a7-5bc9-a9d1-03e7f2e486b2', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 1, 1, 'Now this is the commandment, the statutes, and the ordinances, which Yahweh your God commanded to teach you, that you might do them in the land where you go over to possess it;'),
  ('d94fcffe-b6b4-5ef9-a481-00c52cac648f', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 2, 2, 'that you might fear Yahweh your God, to keep all his statutes and his commandments, which I command you, you, and your son, and your son''s son, all the days of your life; and that your days may be prolonged.'),
  ('0d68efc2-8b26-5d6d-a524-ba5b5edc2687', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 3, 3, 'Hear therefore, Israel, and observe to do it; that it may be well with you, and that you may increase mightily, as Yahweh, the God of your fathers, has promised to you, in a land flowing with milk and honey.'),
  ('c8191095-d322-5d26-ab98-474fe69cc14a', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 4, 4, 'Hear, Israel: Yahweh is our God; Yahweh is one:'),
  ('f897a077-fed8-54c5-a483-69312de2ce4a', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 5, 5, 'and you shall love Yahweh your God with all your heart, and with all your soul, and with all your might.'),
  ('1855292a-caf6-5d01-acc8-fefe3d66827a', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 6, 6, 'These words, which I command you this day, shall be on your heart;'),
  ('8237657f-aed5-5da8-ab31-e750465f423e', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 7, 7, 'and you shall teach them diligently to your children, and shall talk of them when you sit in your house, and when you walk by the way, and when you lie down, and when you rise up.'),
  ('59796de3-803b-5184-adc0-4094a7ebbd9b', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 8, 8, 'You shall bind them for a sign on your hand, and they shall be for symbols between your eyes.'),
  ('39a5893d-df6c-5448-a2ed-fa478fa38726', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 9, 9, 'You shall write them on the door posts of your house, and on your gates.'),
  ('b917131c-6aba-513b-a4cd-22c9d18d9a1d', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 10, 10, 'It shall be, when Yahweh your God shall bring you into the land which he swore to your fathers, to Abraham, to Isaac, and to Jacob, to give you, great and goodly cities, which you didn''t build,'),
  ('1e4c0561-7b84-52af-ab00-78b26963a93d', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 11, 11, 'and houses full of all good things, which you didn''t fill, and cisterns dug out, which you didn''t dig, vineyards and olive trees, which you didn''t plant, and you shall eat and be full;'),
  ('86b2be3f-f3a8-5d47-a6a3-1eeab37692f4', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 12, 12, 'then beware lest you forget Yahweh, who brought you forth out of the land of Egypt, out of the house of bondage.'),
  ('d5e3419b-24c4-5bb6-aa63-ee7a66f09168', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 13, 13, 'You shall fear Yahweh your God; and you shall serve him, and shall swear by his name.'),
  ('e4cf2a05-5438-5778-ac26-665e9b0f6498', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 14, 14, 'You shall not go after other gods, of the gods of the peoples who are around you;'),
  ('fce796bd-afba-52ff-a0d5-d551df45088a', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 15, 15, 'for Yahweh your God in the midst of you is a jealous God; lest the anger of Yahweh your God be kindled against you, and he destroy you from off the face of the earth.'),
  ('63d5cd57-240d-57ee-a6d3-d6a7c3142414', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 16, 16, 'You shall not tempt Yahweh your God, as you tempted him in Massah.'),
  ('962b28b0-218d-52ca-ab58-b938e9111e76', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 17, 17, 'You shall diligently keep the commandments of Yahweh your God, and his testimonies, and his statutes, which he has commanded you.'),
  ('9fc97290-7f7c-5a58-aeff-fa1e5c54ed59', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 18, 18, 'You shall do that which is right and good in the sight of Yahweh; that it may be well with you, and that you may go in and possess the good land which Yahweh swore to your fathers,'),
  ('678d4c8e-4d6d-5d4d-a7fe-494e0cfa9585', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 19, 19, 'to thrust out all your enemies from before you, as Yahweh has spoken.'),
  ('18053039-2a2e-57db-ae6a-c8b739ca4491', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 20, 20, 'When your son asks you in time to come, saying, "What do the testimonies, the statutes, and the ordinances, which Yahweh our God has commanded you mean?"'),
  ('ce75dc94-b7a1-55b2-a319-53f38cec2c99', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 21, 21, 'then you shall tell your son, "We were Pharaoh''s bondservants in Egypt: and Yahweh brought us out of Egypt with a mighty hand;'),
  ('67f37c06-e334-5f44-a6e4-33a3c5923abe', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 22, 22, 'and Yahweh showed great and awesome signs and wonders on Egypt, on Pharaoh, and on all his house, before our eyes;'),
  ('4217a2b1-86f1-5e33-a7bd-730ba665f26b', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 23, 23, 'and he brought us out from there, that he might bring us in, to give us the land which he swore to our fathers.'),
  ('468652f9-d424-57ee-ac45-9b0c1331da0c', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 24, 24, 'Yahweh commanded us to do all these statutes, to fear Yahweh our God, for our good always, that he might preserve us alive, as at this day.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('db677ac2-6df5-5bf1-a944-9ddf7cc5be52', '826b36af-6881-5049-a43e-60fd295f41b5', NULL, 25, 25, 'It shall be righteousness to us, if we observe to do all this commandment before Yahweh our God, as he has commanded us."'),
  ('c0978c88-7228-5a18-a98c-38e8d442c759', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 1, 1, 'When Yahweh your God shall bring you into the land where you go to possess it, and shall cast out many nations before you, the Hittite, and the Girgashite, and the Amorite, and the Canaanite, and the Perizzite, and the Hivite, and the Jebusite, seven nations greater and mightier than you;'),
  ('8d36762d-4532-5c6c-a916-b1b0f4d1d343', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 2, 2, 'and when Yahweh your God shall deliver them up before you, and you shall strike them; then you shall utterly destroy them: you shall make no covenant with them, nor show mercy to them;'),
  ('1288b3ad-36fa-5fd6-a077-0131bd6be6d3', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 3, 3, 'neither shall you make marriages with them; your daughter you shall not give to his son, nor shall you take his daughter for your son.'),
  ('189e0d16-bf26-5d75-a43d-6667b6576cc7', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 4, 4, 'For he will turn away your son from following me, that they may serve other gods: so the anger of Yahweh would be kindled against you, and he would destroy you quickly.'),
  ('25b2bcf2-ba04-51d7-ae18-bde6c56bb212', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 5, 5, 'But you shall deal with them like this: you shall break down their altars, and dash their pillars in pieces, and cut down their Asherim, and burn their engraved images with fire.'),
  ('c97be78e-e9a2-52ee-aa29-a5f41d4a3cc4', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 6, 6, 'For you are a holy people to Yahweh your God: Yahweh your God has chosen you to be a people for his own possession, above all peoples who are on the face of the earth.'),
  ('c9dbc4ac-6325-59e9-a339-ed820895099c', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 7, 7, 'Yahweh didn''t set his love on you, nor choose you, because you were more in number than any people; for you were the fewest of all peoples:'),
  ('4b790edc-9aa1-5f80-a11c-e1ea96df2d94', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 8, 8, 'but because Yahweh loves you, and because he would keep the oath which he swore to your fathers, has Yahweh brought you out with a mighty hand, and redeemed you out of the house of bondage, from the hand of Pharaoh king of Egypt.'),
  ('646fef72-b1fd-5fd4-a304-d06e97c50f52', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 9, 9, 'Know therefore that Yahweh your God, he is God, the faithful God, who keeps covenant and loving kindness with them who love him and keep his commandments to a thousand generations,'),
  ('2f93042f-8d23-5496-af4d-067e24082691', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 10, 10, 'and repays those who hate him to their face, to destroy them: he will not be slack to him who hates him, he will repay him to his face.'),
  ('4698b663-3c27-56d2-a8e6-060cc734f9ab', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 11, 11, 'You shall therefore keep the commandment, and the statutes, and the ordinances, which I command you this day, to do them.'),
  ('548d25b7-281f-54f7-a2ef-bdf54a02054c', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 12, 12, 'It shall happen, because you listen to these ordinances, and keep and do them, that Yahweh your God will keep with you the covenant and the loving kindness which he swore to your fathers:'),
  ('c5dd3c76-581f-56e6-a2d5-4f5e2171f8c8', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 13, 13, 'and he will love you, and bless you, and multiply you; he will also bless the fruit of your body and the fruit of your ground, your grain and your new wine and your oil, the increase of your livestock and the young of your flock, in the land which he swore to your fathers to give you.'),
  ('6ff2999f-449d-5879-ad78-68acce281d2d', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 14, 14, 'You shall be blessed above all peoples: there shall not be male or female barren among you, or among your livestock.'),
  ('ab43d586-3c34-51e3-a19b-34803c9199ce', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 15, 15, 'Yahweh will take away from you all sickness; and none of the evil diseases of Egypt, which you know, he will put on you, but will lay them on all those who hate you.'),
  ('a5d63dae-c606-5598-aa03-99d793322faf', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 16, 16, 'You shall consume all the peoples whom Yahweh your God shall deliver to you; your eye shall not pity them: neither shall you serve their gods; for that will be a snare to you.'),
  ('fd81d687-6a62-5e6c-ac6c-0f81bc8f1e28', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 17, 17, 'If you shall say in your heart, "These nations are more than I; how can I dispossess them?"'),
  ('5689f817-9575-5483-a55e-ee86b91bc550', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 18, 18, 'you shall not be afraid of them: you shall well remember what Yahweh your God did to Pharaoh, and to all Egypt;'),
  ('987d248e-1cb4-53b1-a6fb-b6449cf11ee0', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 19, 19, 'the great trials which your eyes saw, and the signs, and the wonders, and the mighty hand, and the outstretched arm, by which Yahweh your God brought you out: so shall Yahweh your God do to all the peoples of whom you are afraid.'),
  ('dec7a451-bca1-5ad0-a00a-115035267d52', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 20, 20, 'Moreover Yahweh your God will send the hornet among them, until those who are left, and hide themselves, perish from before you.'),
  ('b87e68ca-c0d3-58ba-aaf9-214a28708598', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 21, 21, 'You shall not be scared of them; for Yahweh your God is in the midst of you, a great and awesome God.'),
  ('b8245833-6a4b-59f0-a5a8-e63f4bce4576', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 22, 22, 'Yahweh your God will cast out those nations before you by little and little: you may not consume them at once, lest the animals of the field increase on you.'),
  ('abd49557-fcb6-554d-a8d3-fe92afa55ae2', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 23, 23, 'But Yahweh your God will deliver them up before you, and will confuse them with a great confusion, until they be destroyed.'),
  ('572b2d3a-773a-55ef-a153-4e0e49029606', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 24, 24, 'He will deliver their kings into your hand, and you shall make their name to perish from under the sky: no man shall be able to stand before you, until you have destroyed them.'),
  ('61881e7e-bbaa-51d3-a6b4-a345235dfc82', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 25, 25, 'You shall burn the engraved images of their gods with fire. You shall not covet the silver or the gold that is on them, nor take it for yourself, lest you be snared in it; for it is an abomination to Yahweh your God.'),
  ('3be2fcbb-e480-5124-a921-397f3f805123', 'c8d7f52c-5010-5c79-adaa-020e07684845', NULL, 26, 26, 'You shall not bring an abomination into your house, and become a devoted thing like it. You shall utterly detest it, and you shall utterly abhor it; for it is a devoted thing.'),
  ('9250efe8-0060-5006-a38e-43536fc816f6', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 1, 1, 'You shall observe to do all the commandment which I command you this day, that you may live, and multiply, and go in and possess the land which Yahweh swore to your fathers.'),
  ('a96ed376-0a81-564c-a054-147cc9fe79ad', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 2, 2, 'You shall remember all the way which Yahweh your God has led you these forty years in the wilderness, that he might humble you, to prove you, to know what was in your heart, whether you would keep his commandments, or not.'),
  ('35b669dc-6814-50a0-a4dc-aa3895a40c40', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 3, 3, 'He humbled you, and allowed you to hunger, and fed you with manna, which you didn''t know, neither did your fathers know; that he might make you know that man does not live by bread only, but by everything that proceeds out of the mouth of Yahweh does man live.'),
  ('03657672-7567-5a4a-a6b7-89b2a48163b9', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 4, 4, 'Your clothing didn''t grow old on you, neither did your foot swell, these forty years.'),
  ('95c01064-0321-53a2-abd0-ffc9369ddf32', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 5, 5, 'You shall consider in your heart that as a man chastens his son, so Yahweh your God chastens you.'),
  ('b2f10935-eb2f-5a64-a2f0-359dccb757d2', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 6, 6, 'You shall keep the commandments of Yahweh your God, to walk in his ways, and to fear him.'),
  ('2f784891-d7b3-53eb-aba9-fea5b38d8733', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 7, 7, 'For Yahweh your God brings you into a good land, a land of brooks of water, of springs, and underground water flowing into valleys and hills;'),
  ('b9292402-364c-56a8-ab5e-8432d8cf491d', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 8, 8, 'a land of wheat and barley, and vines and fig trees and pomegranates; a land of olive trees and honey;'),
  ('fa96bc8a-2e01-54fd-a629-996049686562', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 9, 9, 'a land in which you shall eat bread without scarceness, you shall not lack anything in it; a land whose stones are iron, and out of whose hills you may dig copper.'),
  ('e7f6652e-d4fc-5f37-ae7a-5d97e273fdf5', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 10, 10, 'You shall eat and be full, and you shall bless Yahweh your God for the good land which he has given you.'),
  ('d8d09a7f-7348-576a-a960-2072f0b6e1a4', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 11, 11, 'Beware lest you forget Yahweh your God, in not keeping his commandments, and his ordinances, and his statutes, which I command you this day:'),
  ('b409c6e8-b051-511d-a3b4-c1ff83380e42', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 12, 12, 'lest, when you have eaten and are full, and have built goodly houses, and lived therein;'),
  ('0c57649b-9629-5444-abd4-243e02d336cf', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 13, 13, 'and when your herds and your flocks multiply, and your silver and your gold is multiplied, and all that you have is multiplied;'),
  ('0730e881-d54b-5f76-a879-b66280e06c5e', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 14, 14, 'then your heart be lifted up, and you forget Yahweh your God, who brought you forth out of the land of Egypt, out of the house of bondage;'),
  ('5395fcb3-710f-5715-a05e-e0a3c9f72b69', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 15, 15, 'who led you through the great and terrible wilderness, [in which were] fiery serpents and scorpions, and thirsty ground where there was no water; who brought you forth water out of the rock of flint;'),
  ('7714dc48-a50a-5a3b-a25b-fe8c00a93951', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 16, 16, 'who fed you in the wilderness with manna, which your fathers didn''t know; that he might humble you, and that he might prove you, to do you good at your latter end:'),
  ('5fad66e0-30ca-5179-a831-c20e0c74f7d4', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 17, 17, 'and [lest] you say in your heart, "My power and the might of my hand has gotten me this wealth."'),
  ('ad63de8f-76fa-5847-a024-b2e4a8c5d8e2', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 18, 18, 'But you shall remember Yahweh your God, for it is he who gives you power to get wealth; that he may establish his covenant which he swore to your fathers, as at this day.'),
  ('f6f1e77c-a56d-5f2e-ad37-605ec4c011a1', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 19, 19, 'It shall be, if you shall forget Yahweh your God, and walk after other gods, and serve them, and worship them, I testify against you this day that you shall surely perish.'),
  ('0cd052e9-fb51-57c9-ac77-64b9acd93efd', 'adaf4171-afc5-5ae7-a3be-a6c7db6db50e', NULL, 20, 20, 'As the nations that Yahweh makes to perish before you, so you shall perish; because you wouldn''t listen to the voice of Yahweh your God.'),
  ('01c97143-165a-5277-a058-10abfcf4b01e', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 1, 1, 'Hear, Israel: you are to pass over the Jordan this day, to go in to dispossess nations greater and mightier than yourself, cities great and fortified up to the sky,'),
  ('6b350790-52af-50d3-a2a1-29a1bf8785fc', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 2, 2, 'a people great and tall, the sons of the Anakim, whom you know, and of whom you have heard say, "Who can stand before the sons of Anak?"'),
  ('a5e70fb9-93fd-5b7e-a3c7-620099553ee9', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 3, 3, 'Know therefore this day, that Yahweh your God is he who goes over before you as a devouring fire; he will destroy them, and he will bring them down before you: so you shall drive them out, and make them to perish quickly, as Yahweh has spoken to you.'),
  ('aa06a5cc-9345-5584-acb4-2e5730c8b914', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 4, 4, 'Don''t say in your heart, after Yahweh your God has thrust them out from before you, saying, "For my righteousness Yahweh has brought me in to possess this land;" because Yahweh drives them out before you because of the wickedness of these nations.'),
  ('d7c40559-268b-5e7a-a75d-11054da6eab5', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 5, 5, 'Not for your righteousness, or for the uprightness of your heart, do you go in to possess their land; but for the wickedness of these nations Yahweh your God does drive them out from before you, and that he may establish the word which Yahweh swore to your fathers, to Abraham, to Isaac, and to Jacob.'),
  ('cd5aec8f-a1b8-5797-a2c8-6c498606b113', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 6, 6, 'Know therefore, that Yahweh your God doesn''t give you this good land to possess it for your righteousness; for you are a stiff-necked people.'),
  ('bb4e37e6-ed4a-5a9f-a1df-04ec12dbad38', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 7, 7, 'Remember, don''t forget, how you provoked Yahweh your God to wrath in the wilderness: from the day that you went forth out of the land of Egypt, until you came to this place, you have been rebellious against Yahweh.'),
  ('66ded40f-7bbf-56a6-ae0e-ae4c62144f33', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 8, 8, 'Also in Horeb you provoked Yahweh to wrath, and Yahweh was angry with you to destroy you.'),
  ('e334ae4e-e03e-55ac-a5d6-0509a331addd', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 9, 9, 'When I was gone up onto the mountain to receive the tables of stone, even the tables of the covenant which Yahweh made with you, then I stayed on the mountain forty days and forty nights; I did neither eat bread nor drink water.'),
  ('e57ef20e-35e5-535e-a770-6b1978ed8e8a', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 10, 10, 'Yahweh delivered to me the two tables of stone written with the finger of God; and on them [was written] according to all the words, which Yahweh spoke with you on the mountain out of the midst of the fire in the day of the assembly.'),
  ('60a84534-2733-5987-ae12-f9237ddf2491', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 11, 11, 'It came to pass at the end of forty days and forty nights, that Yahweh gave me the two tables of stone, even the tables of the covenant.'),
  ('64d989c0-5f0a-5a65-a63a-258743792e97', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 12, 12, 'Yahweh said to me, "Arise, get down quickly from here; for your people whom you have brought forth out of Egypt have corrupted themselves; they have quickly turned aside out of the way which I commanded them; they have made them a molten image."'),
  ('b859e6c3-29ca-5de4-a535-bb119a5c4480', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 13, 13, 'Furthermore Yahweh spoke to me, saying, "I have seen this people, and behold, it is a stiff-necked people:'),
  ('ee433025-b46d-5c83-ad31-f966f563eda1', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 14, 14, 'let me alone, that I may destroy them, and blot out their name from under the sky; and I will make of you a nation mightier and greater than they."'),
  ('bf18eb4e-58a9-51de-a23d-a39b6b03fd6d', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 15, 15, 'So I turned and came down from the mountain, and the mountain was burning with fire: and the two tables of the covenant were in my two hands.'),
  ('7254f06f-3ae6-5d45-aeba-c5e6a6bd87c0', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 16, 16, 'I looked, and behold, you had sinned against Yahweh your God; you had made yourselves a molten calf: you had turned aside quickly out of the way which Yahweh had commanded you.'),
  ('846c9594-b445-568d-af48-3f6f82bb7b8c', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 17, 17, 'I took hold of the two tables, and cast them out of my two hands, and broke them before your eyes.'),
  ('d678f699-7d8b-5687-acd2-4816425063c3', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 18, 18, 'I fell down before Yahweh, as at the first, forty days and forty nights; I did neither eat bread nor drink water; because of all your sin which you sinned, in doing that which was evil in the sight of Yahweh, to provoke him to anger.'),
  ('9683176f-ce15-571e-a984-2476c7d8091e', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 19, 19, 'For I was afraid of the anger and hot displeasure, with which Yahweh was angry against you to destroy you. But Yahweh listened to me that time also.'),
  ('0756ba46-643a-5eb1-ac21-7f9e6547b012', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 20, 20, 'Yahweh was very angry with Aaron to destroy him: and I prayed for Aaron also at the same time.'),
  ('8c0c4941-7ddd-515e-abca-76b5f9431fd0', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 21, 21, 'I took your sin, the calf which you had made, and burnt it with fire, and stamped it, grinding it very small, until it was as fine as dust: and I cast its dust into the brook that descended out of the mountain.'),
  ('a68a1177-80c4-5493-a182-7eb896b73e2b', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 22, 22, 'At Taberah, and at Massah, and at Kibroth Hattaavah, you provoked Yahweh to wrath.'),
  ('454bb675-49eb-5eaa-a657-3e80f0fee7bd', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 23, 23, 'When Yahweh sent you from Kadesh Barnea, saying, "Go up and possess the land which I have given you;" then you rebelled against the commandment of Yahweh your God, and you didn''t believe him, nor listen to his voice.'),
  ('55a45468-c7a3-58bb-af08-e7355616b1be', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 24, 24, 'You have been rebellious against Yahweh from the day that I knew you.'),
  ('d4f5f08d-9274-58c4-a4f3-07f3fca873d1', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 25, 25, 'So I fell down before Yahweh the forty days and forty nights that I fell down, because Yahweh had said he would destroy you.'),
  ('2eb26e47-b817-53f7-a463-75c615fbf982', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 26, 26, 'I prayed to Yahweh, and said, "Lord Yahweh, don''t destroy your people and your inheritance, that you have redeemed through your greatness, that you have brought forth out of Egypt with a mighty hand.'),
  ('aa08dddd-adfa-5435-a627-1fdff6ae50b7', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 27, 27, 'Remember your servants, Abraham, Isaac, and Jacob; don''t look to the stubbornness of this people, nor to their wickedness, nor to their sin,'),
  ('1f5637f7-ac33-50a6-a30d-fcfdb2858abe', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 28, 28, 'lest the land you brought us out from say, ''Because Yahweh was not able to bring them into the land which he promised to them, and because he hated them, he has brought them out to kill them in the wilderness.'''),
  ('743803a9-e8b0-50c9-a675-df1685090834', 'd91616b9-d87f-512f-a778-3188d699b2c9', NULL, 29, 29, 'Yet they are your people and your inheritance, which you brought out by your great power and by your outstretched arm."'),
  ('7f0e730a-dc66-5738-aedf-46546f7c4666', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 1, 1, 'At that time Yahweh said to me, "Cut two tables of stone like the first, and come up to me onto the mountain, and make an ark of wood.'),
  ('8a10d080-703e-5015-ac69-6ad5bc7dad14', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 2, 2, 'I will write on the tables the words that were on the first tables which you broke, and you shall put them in the ark."'),
  ('a31cfa2c-4498-5cbe-a81a-718b02833939', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 3, 3, 'So I made an ark of acacia wood, and cut two tables of stone like the first, and went up onto the mountain, having the two tables in my hand.'),
  ('a8802a35-d1ae-51bf-a13f-1894fc092d84', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 4, 4, 'He wrote on the tables, according to the first writing, the ten commandments, which Yahweh spoke to you on the mountain out of the midst of the fire in the day of the assembly: and Yahweh gave them to me.'),
  ('a8a97b67-b23b-5d0f-a3d8-338d89d651c3', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 5, 5, 'I turned and came down from the mountain, and put the tables in the ark which I had made; and there they are as Yahweh commanded me.'),
  ('28626ac5-9a22-58ca-a4bc-8353b8c036db', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 6, 6, '(The children of Israel traveled from Beeroth Bene Jaakan to Moserah. There Aaron died, and there he was buried; and Eleazar his son ministered in the priest''s office in his place.'),
  ('b1c94fe5-e537-5604-a620-2905bab30eca', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 7, 7, 'From there they traveled to Gudgodah; and from Gudgodah to Jotbathah, a land of brooks of water.'),
  ('1016519f-3b37-5560-aebc-61d2ddad1aa9', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 8, 8, 'At that time Yahweh set apart the tribe of Levi, to bear the ark of the covenant of Yahweh, to stand before Yahweh to minister to him, and to bless in his name, to this day.'),
  ('8505fdaa-7889-53e6-a322-6365fd8db819', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 9, 9, 'Therefore Levi has no portion nor inheritance with his brothers; Yahweh is his inheritance, according as Yahweh your God spoke to him.)'),
  ('7e86456b-b3cd-56bb-acf0-deaa7508448f', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 10, 10, 'I stayed on the mountain, as at the first time, forty days and forty nights: and Yahweh listened to me that time also; Yahweh would not destroy you.'),
  ('d83ed876-b8d9-52f2-a3fe-a1921dae71d2', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 11, 11, 'Yahweh said to me, "Arise, take your journey before the people; and they shall go in and possess the land, which I swore to their fathers to give to them."'),
  ('62b4fd73-8f30-5223-a102-40a306ef42e4', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 12, 12, 'Now, Israel, what does Yahweh your God require of you, but to fear Yahweh your God, to walk in all his ways, and to love him, and to serve Yahweh your God with all your heart and with all your soul,'),
  ('d6d25840-d13f-5b4e-a13a-dfb98aab3ff9', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 13, 13, 'to keep the commandments of Yahweh, and his statutes, which I command you this day for your good?'),
  ('aeb2fcc3-57da-5f16-af23-7bff3e94fca1', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 14, 14, 'Behold, to Yahweh your God belongs heaven and the heaven of heavens, the earth, with all that is therein.'),
  ('f3115bdb-27f5-53df-a6d7-af8d99f868da', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 15, 15, 'Only Yahweh had a delight in your fathers to love them, and he chose their seed after them, even you above all peoples, as at this day.'),
  ('4eb1c3a7-03d8-5952-af3d-7349000ebb0e', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 16, 16, 'Circumcise therefore the foreskin of your heart, and be no more stiff-necked.'),
  ('a02896cc-f69f-531b-aff1-da12c15268b0', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 17, 17, 'For Yahweh your God, he is God of gods, and Lord of lords, the great God, the mighty, and the awesome, who doesn''t respect persons, nor takes reward.'),
  ('06cfdc83-d6af-50a1-a82d-6397572c8a5a', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 18, 18, 'He does execute justice for the fatherless and widow, and loves the foreigner, in giving him food and clothing.'),
  ('f0fcfbaa-aab8-5dd7-a43d-2cb9f8fb2858', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 19, 19, 'Therefore love the foreigner; for you were foreigners in the land of Egypt.'),
  ('c7f6c56e-cd0f-55fb-afc7-a055728ff937', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 20, 20, 'You shall fear Yahweh your God; you shall serve him; and you shall cling to him, and you shall swear by his name.'),
  ('557bc068-ad0b-5bf7-a05f-414c76e8248a', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 21, 21, 'He is your praise, and he is your God, who has done for you these great and awesome things, which your eyes have seen.'),
  ('26f05907-5eca-562d-ae18-ad858ecfcaee', 'e2e3a79b-f741-5337-a8fc-c5d68de54850', NULL, 22, 22, 'Your fathers went down into Egypt with seventy persons; and now Yahweh your God has made you as the stars of the sky for multitude.'),
  ('57c4c560-58b0-5194-af8c-db67ef42f98d', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 1, 1, 'Therefore you shall love Yahweh your God, and keep his instructions, and his statutes, and his ordinances, and his commandments, always.'),
  ('dd9d15e9-81f8-589b-ac40-8a34f3902373', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 2, 2, 'Know this day: for I don''t speak with your children who have not known, and who have not seen the chastisement of Yahweh your God, his greatness, his mighty hand, and his outstretched arm,'),
  ('41658dad-a573-5aaa-ae4a-ff74cb2d4df2', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 3, 3, 'and his signs, and his works, which he did in the midst of Egypt to Pharaoh the king of Egypt, and to all his land;'),
  ('bb732d23-98de-5923-abf6-9a0e9954b88a', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 4, 4, 'and what he did to the army of Egypt, to their horses, and to their chariots; how he made the water of the Red Sea to overflow them as they pursued after you, and how Yahweh has destroyed them to this day;'),
  ('7a447721-88a4-5ab1-a504-a4e82b6f7460', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 5, 5, 'and what he did to you in the wilderness, until you came to this place;'),
  ('1b6d9bdf-18a6-56f1-a025-11f1342740fa', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 6, 6, 'and what he did to Dathan and Abiram, the sons of Eliab, the son of Reuben; how the earth opened its mouth, and swallowed them up, and their households, and their tents, and every living thing that followed them, in the midst of all Israel:'),
  ('8a802888-f053-54c7-a259-69734525bbdf', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 7, 7, 'but your eyes have seen all the great work of Yahweh which he did.'),
  ('a401167f-1b43-52b8-a6fb-ab46ee946fcc', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 8, 8, 'Therefore you shall keep all the commandment which I command you this day, that you may be strong, and go in and possess the land, where you go over to possess it;'),
  ('41c05933-e9f9-5bfa-aa7b-746feb8af40b', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 9, 9, 'and that you may prolong your days in the land, which Yahweh swore to your fathers to give to them and to their seed, a land flowing with milk and honey.'),
  ('f17ed196-a040-5387-a860-6835732f7c0e', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 10, 10, 'For the land, where you go in to possess it, isn''t as the land of Egypt, that you came out from, where you sowed your seed, and watered it with your foot, as a garden of herbs;'),
  ('fd3cc4c9-5401-5e79-ab25-c9d200b6e625', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 11, 11, 'but the land, where you go over to possess it, is a land of hills and valleys, [and] drinks water of the rain of the sky,'),
  ('0893e780-9ad9-5334-a30e-71434334db69', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 12, 12, 'a land which Yahweh your God cares for: the eyes of Yahweh your God are always on it, from the beginning of the year even to the end of the year.'),
  ('2d017c9c-6512-523b-ac19-e5dab463c1d8', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 13, 13, 'It shall happen, if you shall listen diligently to my commandments which I command you this day, to love Yahweh your God, and to serve him with all your heart and with all your soul,'),
  ('559155d8-27cb-559d-a850-dcd79ccc20d6', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 14, 14, 'that I will give the rain of your land in its season, the former rain and the latter rain, that you may gather in your grain, and your new wine, and your oil.'),
  ('e786ad85-1d58-5aec-a3dc-fad4000ec371', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 15, 15, 'I will give grass in your fields for your livestock, and you shall eat and be full.'),
  ('7dd53314-dc11-5ffc-a143-f708aa0b422e', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 16, 16, 'Take heed to yourselves, lest your heart be deceived, and you turn aside, and serve other gods, and worship them;'),
  ('91741f7c-2952-5a07-a1e5-2bc8226e6ec9', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 17, 17, 'and the anger of Yahweh be kindled against you, and he shut up the sky, so that there shall be no rain, and the land shall not yield its fruit; and you perish quickly from off the good land which Yahweh gives you.'),
  ('973e4cd3-f36a-53f5-ac66-b370d23738bf', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 18, 18, 'Therefore you shall lay up these my words in your heart and in your soul; and you shall bind them for a sign on your hand, and they shall be for symbols between your eyes.'),
  ('ec25c2de-25e5-5d12-acc6-02c3cf04b770', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 19, 19, 'You shall teach them your children, talking of them, when you sit in your house, and when you walk by the way, and when you lie down, and when you rise up.'),
  ('a50b147d-b8d1-5563-a0d8-1b5ac8d73c5c', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 20, 20, 'You shall write them on the door posts of your house, and on your gates;'),
  ('5286fb7e-593c-5a49-a5ea-cb33cd5e74e9', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 21, 21, 'that your days may be multiplied, and the days of your children, in the land which Yahweh swore to your fathers to give them, as the days of the heavens above the earth.'),
  ('4fef04f8-8fe6-53f2-ab61-5be32fe12687', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 22, 22, 'For if you shall diligently keep all this commandment which I command you, to do it, to love Yahweh your God, to walk in all his ways, and to cling to him;'),
  ('10ed2010-1db2-514a-a001-afdf794bfde3', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 23, 23, 'then will Yahweh drive out all these nations from before you, and you shall dispossess nations greater and mightier than yourselves.'),
  ('f99b074b-35e5-59db-aee6-417c558b72a4', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 24, 24, 'Every place whereon the sole of your foot shall tread shall be yours: from the wilderness, and Lebanon, from the river, the river Euphrates, even to the hinder sea shall be your border.'),
  ('cefe14c8-e64a-574d-aaa0-ade7b5370332', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 25, 25, 'No man shall be able to stand before you: Yahweh your God shall lay the fear of you and the dread of you on all the land that you shall tread on, as he has spoken to you.'),
  ('0a53aa90-fb50-565b-af84-cafd3c41556f', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 26, 26, 'Behold, I set before you this day a blessing and a curse:'),
  ('7a226464-7e5c-5e5d-ab02-c64b9bd07c5d', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 27, 27, 'the blessing, if you shall listen to the commandments of Yahweh your God, which I command you this day;'),
  ('885d9157-0a72-5e70-aa38-cf5995da6969', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 28, 28, 'and the curse, if you shall not listen to the commandments of Yahweh your God, but turn aside out of the way which I command you this day, to go after other gods, which you have not known.'),
  ('c94e480d-23d8-5ebc-aebe-558e2ec5147f', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 29, 29, 'It shall happen, when Yahweh your God shall bring you into the land where you go to possess it, that you shall set the blessing on Mount Gerizim, and the curse on Mount Ebal.'),
  ('7c20910f-d169-5cce-a064-eecf9b5549ff', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 30, 30, 'Aren''t they beyond the Jordan, behind the way of the going down of the sun, in the land of the Canaanites who dwell in the Arabah, over against Gilgal, beside the oaks of Moreh?'),
  ('10f9b706-71fa-56a6-ac0e-d4f6e1b6bf5a', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 31, 31, 'For you are to pass over the Jordan to go in to possess the land which Yahweh your God gives you, and you shall possess it, and dwell therein.'),
  ('6cff7e5e-f8cc-5df7-a9e8-b5a8205f9def', 'c0136367-fd42-52c0-a35a-85bc06cf5544', NULL, 32, 32, 'You shall observe to do all the statutes and the ordinances which I set before you this day.'),
  ('1dc7a8b1-e8f4-5fed-a42b-f256781f8a4e', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 1, 1, 'These are the statutes and the ordinances which you shall observe to do in the land which Yahweh, the God of your fathers, has given you to possess it, all the days that you live on the earth.'),
  ('56806344-2245-5af4-a783-db8bb2f0bf53', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 2, 2, 'You shall surely destroy all the places in which the nations that you shall dispossess served their gods, on the high mountains, and on the hills, and under every green tree:'),
  ('21d09b66-659f-5284-aab3-bcccb6fd0808', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 3, 3, 'and you shall break down their altars, and dash in pieces their pillars, and burn their Asherim with fire; and you shall cut down the engraved images of their gods; and you shall destroy their name out of that place.'),
  ('700769d8-33ea-5ce3-ae05-47fc8e65d8af', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 4, 4, 'You shall not do so to Yahweh your God.'),
  ('ee1d0233-6bdd-5ff7-aca8-0406f8233f59', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 5, 5, 'But to the place which Yahweh your God shall choose out of all your tribes, to put his name there, even to his habitation you shall seek, and there you shall come;'),
  ('ba4b09b3-397f-5ddb-a215-d9ea85a1bb3d', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 6, 6, 'and there you shall bring your burnt offerings, and your sacrifices, and your tithes, and the wave offering of your hand, and your vows, and your freewill offerings, and the firstborn of your herd and of your flock:'),
  ('e762dc80-180a-5e6f-aa98-336a1127f238', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 7, 7, 'and there you shall eat before Yahweh your God, and you shall rejoice in all that you put your hand to, you and your households, in which Yahweh your God has blessed you.'),
  ('ded245e0-6771-52e4-a1ce-e8fde5b3363d', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 8, 8, 'You shall not do after all the things that we do here this day, every man whatever is right in his own eyes;'),
  ('ca078dc0-92e8-5f13-ad4d-204edf60c151', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 9, 9, 'for you haven''t yet come to the rest and to the inheritance, which Yahweh your God gives you.'),
  ('b5c1eaab-b683-5be1-a453-3bd237431a53', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 10, 10, 'But when you go over the Jordan, and dwell in the land which Yahweh your God causes you to inherit, and he gives you rest from all your enemies around you, so that you dwell in safety;'),
  ('6143a71f-f318-5c1e-ab9f-64ed5ea97059', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 11, 11, 'then it shall happen that to the place which Yahweh your God shall choose, to cause his name to dwell there, there you shall bring all that I command you: your burnt offerings, and your sacrifices, your tithes, and the wave offering of your hand, and all your choice vows which you vow to Yahweh.'),
  ('2b3e4936-dece-5260-a7ef-24e30248ba8c', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 12, 12, 'You shall rejoice before Yahweh your God, you, and your sons, and your daughters, and your male servants, and your female servants, and the Levite who is within your gates, because he has no portion nor inheritance with you.'),
  ('4fd7767e-de8c-5703-a6cb-01d210771944', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 13, 13, 'Take heed to yourself that you don''t offer your burnt offerings in every place that you see;'),
  ('c2c1d430-2844-5821-a996-dd5c215c2e5f', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 14, 14, 'but in the place which Yahweh shall choose in one of your tribes, there you shall offer your burnt offerings, and there you shall do all that I command you.'),
  ('6db6077f-9f63-572f-a6dc-7b7b41bff613', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 15, 15, 'Notwithstanding, you may kill and eat flesh within all your gates, after all the desire of your soul, according to the blessing of Yahweh your God which he has given you: the unclean and the clean may eat of it, as of the gazelle, and as of the hart.'),
  ('7f008bd6-1c96-5f2a-a199-a679a3149ab5', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 16, 16, 'Only you shall not eat the blood; you shall pour it out on the earth as water.'),
  ('f930d23e-d8e5-5889-a1d8-3853b0e0ef69', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 17, 17, 'You may not eat within your gates the tithe of your grain, or of your new wine, or of your oil, or the firstborn of your herd or of your flock, nor any of your vows which you vow, nor your freewill offerings, nor the wave offering of your hand;'),
  ('8e74241d-66f7-58a0-a721-38ebe1f5a002', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 18, 18, 'but you shall eat them before Yahweh your God in the place which Yahweh your God shall choose, you, and your son, and your daughter, and your male servant, and your female servant, and the Levite who is within your gates: and you shall rejoice before Yahweh your God in all that you put your hand to.'),
  ('7a15fc1f-3c76-52b6-a01c-5a73dc3ead65', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 19, 19, 'Take heed to yourself that you don''t forsake the Levite as long as you live in your land.'),
  ('2c1c74aa-c6bb-5f4c-a424-3ed08e89df36', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 20, 20, 'When Yahweh your God shall enlarge your border, as he has promised you, and you shall say, "I want to eat meat," because your soul desires to eat meat; you may eat meat, after all the desire of your soul.'),
  ('64dc3c2e-d346-5f30-a9fc-614a1583d140', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 21, 21, 'If the place which Yahweh your God shall choose, to put his name there, is too far from you, then you shall kill of your herd and of your flock, which Yahweh has given you, as I have commanded you; and you may eat within your gates, after all the desire of your soul.'),
  ('fdbb28e5-aba7-5ea3-a926-d1f1e82e5ed2', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 22, 22, 'Even as the gazelle and as the hart is eaten, so you shall eat of it: the unclean and the clean may eat of it alike.'),
  ('e9839c6d-f40f-5ff4-ade6-0d440542247a', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 23, 23, 'Only be sure that you don''t eat the blood: for the blood is the life; and you shall not eat the life with the flesh.'),
  ('b8644550-9d21-52c7-a8cc-424c5c3fc5f4', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 24, 24, 'You shall not eat it; you shall pour it out on the earth as water.'),
  ('c8526ede-0d56-5c9c-a328-f137e9763da0', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 25, 25, 'You shall not eat it; that it may go well with you, and with your children after you, when you shall do that which is right in the eyes of Yahweh.'),
  ('fe42e15f-1182-5a5a-a570-5fb6f548b50b', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 26, 26, 'Only your holy things which you have, and your vows, you shall take, and go to the place which Yahweh shall choose:'),
  ('fd84518f-e0e8-5be9-a4bd-43fa769da034', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 27, 27, 'and you shall offer your burnt offerings, the flesh and the blood, on the altar of Yahweh your God; and the blood of your sacrifices shall be poured out on the altar of Yahweh your God; and you shall eat the flesh.'),
  ('f96a3bb0-9f11-53e1-a21e-7982fb412c27', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 28, 28, 'Observe and hear all these words which I command you, that it may go well with you, and with your children after you forever, when you do that which is good and right in the eyes of Yahweh your God.'),
  ('97a15e83-f813-5f84-ab29-ca7d604afba6', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 29, 29, 'When Yahweh your God shall cut off the nations from before you, where you go in to dispossess them, and you dispossess them, and dwell in their land;'),
  ('b76d5354-ffc9-5e77-a6a9-b184e4b5b778', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 30, 30, 'take heed to yourself that you not be ensnared to follow them, after that they are destroyed from before you; and that you not inquire after their gods, saying, "How do these nations serve their gods? I will do likewise."'),
  ('97d10fff-deae-57c1-af91-3f3697f60db8', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 31, 31, 'You shall not do so to Yahweh your God: for every abomination to Yahweh, which he hates, have they done to their gods; for even their sons and their daughters do they burn in the fire to their gods.'),
  ('d247f659-c0f2-5777-af1f-e9c4fc3b5378', '52544218-c207-58dd-af80-954f8ffcf55e', NULL, 32, 32, 'Whatever thing I command you, that you shall observe to do: you shall not add thereto, nor diminish from it.'),
  ('71da7e72-e2e0-5f40-a4b4-3770c1562eaf', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 1, 1, 'If there arise in the midst of you a prophet, or a dreamer of dreams, and he give you a sign or a wonder,'),
  ('c3e8d515-7f84-5789-a6f2-ab371323523c', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 2, 2, 'and the sign or the wonder come to pass, of which he spoke to you, saying, "Let us go after other gods" (which you have not known) "and let us serve them;"'),
  ('ed1f1083-2680-5cdf-aba4-beabfc2e94e7', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 3, 3, 'you shall not listen to the words of that prophet, or to that dreamer of dreams: for Yahweh your God proves you, to know whether you love Yahweh your God with all your heart and with all your soul.'),
  ('9bb94360-567f-50e6-a04d-f4f091c526bb', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 4, 4, 'You shall walk after Yahweh your God, and fear him, and keep his commandments, and obey his voice, and you shall serve him, and cling to him.'),
  ('9ed7cd01-b3a9-521c-a979-59b1a9c63cb0', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 5, 5, 'That prophet, or that dreamer of dreams, shall be put to death, because he has spoken rebellion against Yahweh your God, who brought you out of the land of Egypt, and redeemed you out of the house of bondage, to draw you aside out of the way which Yahweh your God commanded you to walk in. So you shall put away the evil from the midst of you.'),
  ('3cabe722-3d63-5076-adb6-27c4cbd0011e', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 6, 6, 'If your brother, the son of your mother, or your son, or your daughter, or the wife of your bosom, or your friend, who is as your own soul, entice you secretly, saying, "Let us go and serve other gods," which you have not known, you, nor your fathers;'),
  ('0d71b18c-ea3a-5c0a-a0ea-a7dc7f392e10', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 7, 7, 'of the gods of the peoples who are around you, near to you, or far off from you, from the one end of the earth even to the other end of the earth;'),
  ('0d9b3cc9-a108-5076-a2c3-11dbec4bcece', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 8, 8, 'you shall not consent to him, nor listen to him; neither shall your eye pity him, neither shall you spare, neither shall you conceal him:'),
  ('3a7d10ab-8ba9-54d8-a9f2-3bc8679dbb74', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 9, 9, 'but you shall surely kill him; your hand shall be first on him to put him to death, and afterwards the hand of all the people.'),
  ('6975387f-1b3d-5ed5-a0f0-b58f3a5d1ed7', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 10, 10, 'You shall stone him to death with stones, because he has sought to draw you away from Yahweh your God, who brought you out of the land of Egypt, out of the house of bondage.'),
  ('b53d124e-c734-540b-aa9e-c5736b0d6bf0', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 11, 11, 'All Israel shall hear, and fear, and shall not do any more such wickedness as this is in the midst of you.'),
  ('9ef3ace6-f8f9-56f5-a56b-56fdee7bc88a', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 12, 12, 'If you shall hear tell concerning one of your cities, which Yahweh your God gives you to dwell there, saying,'),
  ('8d933433-2012-53bf-a12a-50137c61574f', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 13, 13, 'Certain base fellows are gone out from the midst of you, and have drawn away the inhabitants of their city, saying, "Let us go and serve other gods," which you have not known;'),
  ('58197b1c-86f3-5a48-a182-33e86a3bdd18', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 14, 14, 'then you shall inquire, and make search, and ask diligently; and, behold, if it be truth, and the thing certain, that such abomination is done in the midst of you,'),
  ('aea8a282-8cab-5b05-a3cb-78ffdcf709ed', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 15, 15, 'you shall surely strike the inhabitants of that city with the edge of the sword, destroying it utterly, and all that is therein and its livestock, with the edge of the sword.'),
  ('30371dd3-e057-54bf-a6fc-1430e85643c7', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 16, 16, 'You shall gather all its spoil into the midst of its street, and shall burn with fire the city, and all its spoil every whit, to Yahweh your God: and it shall be a heap forever; it shall not be built again.'),
  ('fafc3502-8983-51a4-ad2e-5b36b305873f', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 17, 17, 'Nothing of the devoted thing shall cling to your hand; that Yahweh may turn from the fierceness of his anger, and show you mercy, and have compassion on you, and multiply you, as he has sworn to your fathers;'),
  ('10251078-bb17-50ac-a0a0-c33ae5d67e24', '8e78f21f-e3c7-55de-ac90-85ed3acc72fb', NULL, 18, 18, 'when you shall listen to the voice of Yahweh your God, to keep all his commandments which I command you this day, to do that which is right in the eyes of Yahweh your God.'),
  ('f57512be-3ea7-5b04-afb7-11cc4289a178', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 1, 1, 'You are the children of Yahweh your God: you shall not cut yourselves, nor make any baldness between your eyes for the dead.'),
  ('7b4f80fd-6d43-564c-a6f9-7ad30b3a6e83', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 2, 2, 'For you are a holy people to Yahweh your God, and Yahweh has chosen you to be a people for his own possession, above all peoples who are on the face of the earth.'),
  ('90ab7f25-dbca-5e57-a901-89b11137c29b', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 3, 3, 'You shall not eat any abominable thing.'),
  ('22c75d5d-229f-5831-af10-d2327f6c5619', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 4, 4, 'These are the animals which you may eat: the ox, the sheep, and the goat,'),
  ('42df7d13-d5aa-5a11-a11a-6cd77d0e20e6', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 5, 5, 'the hart, and the gazelle, and the roebuck, and the wild goat, and the ibex, and the antelope, and the chamois.'),
  ('f476f1fd-ee97-5024-acf7-2602b80b4dbb', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 6, 6, 'Every animal that parts the hoof, and has the hoof cloven in two, [and] chews the cud, among the animals, that may you eat.'),
  ('d9e86b84-f98d-5181-abff-d1feb20e1385', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 7, 7, 'Nevertheless these you shall not eat of them that chew the cud, or of those who have the hoof cloven: the camel, and the hare, and the rabbit; because they chew the cud but don''t part the hoof, they are unclean to you.'),
  ('c7ecf200-8176-590b-a83d-9f59056aedba', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 8, 8, 'The pig, because it has a split hoof but doesn''t chew the cud, is unclean to you: of their flesh you shall not eat, and their carcasses you shall not touch.'),
  ('0ce555dd-5499-5008-a776-cc80fbb3070f', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 9, 9, 'These you may eat of all that are in the waters: whatever has fins and scales may you eat;'),
  ('94108c68-0a44-59d6-a9fe-68d41f1e8892', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 10, 10, 'and whatever doesn''t have fins and scales you shall not eat; it is unclean to you.'),
  ('f60f8ed1-97c4-5588-a0d0-ac81ae61db7b', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 11, 11, 'Of all clean birds you may eat.'),
  ('093ebe69-87d6-587e-a829-087b9be83b51', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 12, 12, 'But these are they of which you shall not eat: the eagle, and the vulture, and the osprey,'),
  ('9f5b8028-dc4f-5388-af0b-8b6d27aa2c90', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 13, 13, 'and the red kite, and the falcon, and the kite after its kind,'),
  ('e8ee30e9-81bc-547a-aa0f-f7936abc3545', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 14, 14, 'and every raven after its kind,'),
  ('29a48440-bcdc-5558-a7b8-549882c234bb', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 15, 15, 'and the ostrich, and the owl, and the seagull, and the hawk after its kind,'),
  ('44b4aa42-263a-5569-a0cf-879d810b2d01', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 16, 16, 'the little owl, and the great owl, and the horned owl,'),
  ('319b586a-923c-52d2-a494-f393e9ed7af1', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 17, 17, 'and the pelican, and the vulture, and the cormorant,'),
  ('37bcc9fd-7e41-5456-a00a-4b83e1e856ea', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 18, 18, 'and the stork, and the heron after its kind, and the hoopoe, and the bat.'),
  ('c26b0b8a-7a56-513e-a800-5835298c6d59', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 19, 19, 'All winged creeping things are unclean to you: they shall not be eaten.'),
  ('29c709f6-f593-5875-acd6-c91834e99173', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 20, 20, 'Of all clean birds you may eat.'),
  ('782f91cd-0cca-5d4a-af7f-4715793b9e58', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 21, 21, 'You shall not eat of anything that dies of itself: you may give it to the foreigner living among you who is within your gates, that he may eat it; or you may sell it to a foreigner: for you are a holy people to Yahweh your God. You shall not boil a young goat in its mother''s milk.'),
  ('3beffab7-4055-5208-a667-1dc175257809', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 22, 22, 'You shall surely tithe all the increase of your seed, that which comes forth from the field year by year.'),
  ('8148823a-7e72-5f1b-ac6e-de056ec141c4', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 23, 23, 'You shall eat before Yahweh your God, in the place which he shall choose, to cause his name to dwell there, the tithe of your grain, of your new wine, and of your oil, and the firstborn of your herd and of your flock; that you may learn to fear Yahweh your God always.'),
  ('cdaf5b56-464b-531b-a27f-0940a94bfe7f', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 24, 24, 'If the way is too long for you, so that you are not able to carry it, because the place is too far from you, which Yahweh your God shall choose, to set his name there, when Yahweh your God shall bless you;'),
  ('7e003878-e7b8-5505-af17-d657910af4e5', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 25, 25, 'then you shall turn it into money, and bind up the money in your hand, and shall go to the place which Yahweh your God shall choose:'),
  ('beede607-1460-5eef-a7a4-69bd3396c68e', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 26, 26, 'and you shall bestow the money for whatever your soul desires, for cattle, or for sheep, or for wine, or for strong drink, or for whatever your soul asks of you; and you shall eat there before Yahweh your God, and you shall rejoice, you and your household.'),
  ('20be214e-9902-5de3-a3fb-99f1333717a8', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 27, 27, 'The Levite who is within your gates, you shall not forsake him; for he has no portion nor inheritance with you.'),
  ('ad0f251f-c46d-54db-a4f4-5d09e9159b31', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 28, 28, 'At the end of every three years you shall bring forth all the tithe of your increase in the same year, and shall lay it up within your gates:'),
  ('92569b93-b467-517f-a2e1-3ddd64e3e731', '02f1f292-e9f7-5a7d-a541-edd8edf5569d', NULL, 29, 29, 'and the Levite, because he has no portion nor inheritance with you, and the foreigner living among you, and the fatherless, and the widow, who are within your gates, shall come, and shall eat and be satisfied; that Yahweh your God may bless you in all the work of your hand which you do.'),
  ('130106be-223e-54cd-a1a7-897afbc480be', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 1, 1, 'At the end of every seven years you shall make a release.'),
  ('cdc8d51d-12ea-5f82-ac94-bda4f6741ff0', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 2, 2, 'This is the way of the release: every creditor shall release that which he has lent to his neighbor; he shall not exact it of his neighbor and his brother; because Yahweh''s release has been proclaimed.'),
  ('c680e1b1-ab19-522b-aa11-5aa5e4e8d2a0', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 3, 3, 'Of a foreigner you may exact it: but whatever of your is with your brother your hand shall release.'),
  ('9a1891f4-3715-52e8-a4a6-a7febd9c06e8', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 4, 4, 'However there shall be no poor with you; (for Yahweh will surely bless you in the land which Yahweh your God gives you for an inheritance to possess it;)'),
  ('4cf8b83a-04a7-5643-a94d-27cabd9e7db7', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 5, 5, 'if only you diligently listen to the voice of Yahweh your God, to observe to do all this commandment which I command you this day.'),
  ('0d9b7f10-3f85-54bb-a54a-6a5ea69db5cb', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 6, 6, 'For Yahweh your God will bless you, as he promised you: and you shall lend to many nations, but you shall not borrow; and you shall rule over many nations, but they shall not rule over you.'),
  ('ffcf5a45-d5a0-527b-a9cf-59df2ffd657f', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 7, 7, 'If a poor man, one of your brothers, is with you within any of your gates in your land which Yahweh your God gives you, you shall not harden your heart, nor shut your hand from your poor brother;'),
  ('a36fb6fe-5b80-5162-a70b-a39fe9468a17', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 8, 8, 'but you shall surely open your hand to him, and shall surely lend him sufficient for his need [in that] which he wants.'),
  ('74599902-2f54-5a96-a651-8d70dd062691', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 9, 9, 'Beware that there not be a base thought in your heart, saying, "The seventh year, the year of release, is at hand;" and your eye be evil against your poor brother, and you give him nothing; and he cry to Yahweh against you, and it be sin to you.'),
  ('83db1f1a-4a58-5c90-ad08-d130a67d4c85', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 10, 10, 'You shall surely give him, and your heart shall not be grieved when you give to him; because that for this thing Yahweh your God will bless you in all your work, and in all that you put your hand to.'),
  ('ae34ec66-14fa-5489-a88f-3e6a0a9a9259', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 11, 11, 'For the poor will never cease out of the land: therefore I command you, saying, You shall surely open your hand to your brother, to your needy, and to your poor, in your land.'),
  ('16bdd4d4-1e82-5c31-aaab-85cf07ac8c1d', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 12, 12, 'If your brother, a Hebrew man, or a Hebrew woman, is sold to you, and serves you six years; then in the seventh year you shall let him go free from you.'),
  ('ba9d608b-f788-5826-a5b8-e6875af9080d', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 13, 13, 'When you let him go free from you, you shall not let him go empty:'),
  ('838f7b7d-9519-5174-aa9f-d5b91cec403f', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 14, 14, 'you shall furnish him liberally out of your flock, and out of your threshing floor, and out of your winepress; as Yahweh your God has blessed you, you shall give to him.'),
  ('6c42b684-353d-5c99-ac7b-48640c7eb6a9', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 15, 15, 'You shall remember that you were a bondservant in the land of Egypt, and Yahweh your God redeemed you: therefore I command you this thing today.'),
  ('950e91ae-73f0-52a2-a7bb-2cef14120272', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 16, 16, 'It shall be, if he tells you, "I will not go out from you;" because he loves you and your house, because he is well with you;'),
  ('745c2c6e-efe9-561c-a32f-c1bfbc9552e9', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 17, 17, 'then you shall take an awl, and thrust it through his ear to the door, and he shall be your servant forever. Also to your female servant you shall do likewise.'),
  ('2d49b2a5-ff36-5058-ab60-dd583b217c4f', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 18, 18, 'It shall not seem hard to you, when you let him go free from you; for to the double of the hire of a hireling has he served you six years: and Yahweh your God will bless you in all that you do.'),
  ('2c4d6f7e-14f1-5406-ad99-ee8d9bff28aa', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 19, 19, 'All the firstborn males that are born of your herd and of your flock you shall sanctify to Yahweh your God: you shall do no work with the firstborn of your herd, nor shear the firstborn of your flock.'),
  ('3e35f4ba-3c14-5717-a219-264b22eab7d0', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 20, 20, 'You shall eat it before Yahweh your God year by year in the place which Yahweh shall choose, you and your household.'),
  ('f1979774-adc2-52c3-a942-d592ba2d5a19', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 21, 21, 'If it have any blemish, [as if it be] lame or blind, any ill blemish whatever, you shall not sacrifice it to Yahweh your God.'),
  ('47a50b41-d0c1-5851-a1c7-39e62bd0f166', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 22, 22, 'You shall eat it within your gates: the unclean and the clean [shall eat it] alike, as the gazelle, and as the hart.'),
  ('6dd02d8a-77ae-57cd-a75c-d28b48e1f7f3', 'a1ecfb4c-e94b-58b5-a7d8-c4e80c6d6c8e', NULL, 23, 23, 'Only you shall not eat its blood; you shall pour it out on the ground as water.'),
  ('89b8e396-4706-57ca-ae94-5f873ebfbebe', '1768e377-da22-53b9-a803-17c05b731432', NULL, 1, 1, 'Observe the month of Abib, and keep the Passover to Yahweh your God; for in the month of Abib Yahweh your God brought you forth out of Egypt by night.'),
  ('83e99dd7-3a29-5f0e-a676-3aa445218f8a', '1768e377-da22-53b9-a803-17c05b731432', NULL, 2, 2, 'You shall sacrifice the Passover to Yahweh your God, of the flock and the herd, in the place which Yahweh shall choose, to cause his name to dwell there.'),
  ('215f6b21-e52b-50d7-a4d5-c04cf3a798da', '1768e377-da22-53b9-a803-17c05b731432', NULL, 3, 3, 'You shall eat no leavened bread with it. You shall eat unleavened bread with it seven days, even the bread of affliction; for you came forth out of the land of Egypt in haste: that you may remember the day when you came forth out of the land of Egypt all the days of your life.'),
  ('3b15f209-9af5-5fb4-a79f-3d98115aebf9', '1768e377-da22-53b9-a803-17c05b731432', NULL, 4, 4, 'No yeast shall be seen with you in all your borders seven days; neither shall any of the flesh, which you sacrifice the first day at evening, remain all night until the morning.'),
  ('372e06e6-2ae9-5c48-af9b-979eeaca3869', '1768e377-da22-53b9-a803-17c05b731432', NULL, 5, 5, 'You may not sacrifice the Passover within any of your gates, which Yahweh your God gives you;'),
  ('353cc28a-23b3-5679-a924-de306085059c', '1768e377-da22-53b9-a803-17c05b731432', NULL, 6, 6, 'but at the place which Yahweh your God shall choose, to cause his name to dwell in, there you shall sacrifice the Passover at evening, at the going down of the sun, at the season that you came forth out of Egypt.'),
  ('e0f11a63-b6d9-55e2-a94c-37af30e6fe06', '1768e377-da22-53b9-a803-17c05b731432', NULL, 7, 7, 'You shall roast and eat it in the place which Yahweh your God shall choose: and you shall turn in the morning, and go to your tents.'),
  ('6adadf1b-b1e2-5786-a5d7-a4fb63a26ade', '1768e377-da22-53b9-a803-17c05b731432', NULL, 8, 8, 'Six days you shall eat unleavened bread; and on the seventh day shall be a solemn assembly to Yahweh your God; you shall do no work [therein].'),
  ('6f38908b-2b40-5785-aed8-bf09881dacee', '1768e377-da22-53b9-a803-17c05b731432', NULL, 9, 9, 'You shall count for yourselves seven weeks: from the time you begin to put the sickle to the standing grain you shall begin to number seven weeks.'),
  ('9e912445-9409-5230-af36-43181d95d31b', '1768e377-da22-53b9-a803-17c05b731432', NULL, 10, 10, 'You shall keep the feast of weeks to Yahweh your God with a tribute of a freewill offering of your hand, which you shall give, according as Yahweh your God blesses you:'),
  ('c6046a82-26fe-58ee-a085-a12eac32e6f6', '1768e377-da22-53b9-a803-17c05b731432', NULL, 11, 11, 'and you shall rejoice before Yahweh your God, you, and your son, and your daughter, and your male servant, and your female servant, and the Levite who is within your gates, and the foreigner, and the fatherless, and the widow, who are in the midst of you, in the place which Yahweh your God shall choose, to cause his name to dwell there.'),
  ('21ff9e57-afd1-585e-a6e6-9d64127932eb', '1768e377-da22-53b9-a803-17c05b731432', NULL, 12, 12, 'You shall remember that you were a bondservant in Egypt: and you shall observe and do these statutes.'),
  ('8c92a19b-c31f-5051-a95b-83987a805b78', '1768e377-da22-53b9-a803-17c05b731432', NULL, 13, 13, 'You shall keep the feast of tents seven days, after that you have gathered in from your threshing floor and from your winepress:'),
  ('8e92c2c8-e71d-50b6-a416-6ab4bbc4b0bd', '1768e377-da22-53b9-a803-17c05b731432', NULL, 14, 14, 'and you shall rejoice in your feast, you, and your son, and your daughter, and your male servant, and your female servant, and the Levite, and the foreigner, and the fatherless, and the widow, who are within your gates.'),
  ('6cdffa8e-f359-51da-ab10-daf8517b9571', '1768e377-da22-53b9-a803-17c05b731432', NULL, 15, 15, 'You shall keep a feast to Yahweh your God seven days in the place which Yahweh shall choose; because Yahweh your God will bless you in all your increase, and in all the work of your hands, and you shall be altogether joyful.'),
  ('0d1e719b-db20-5941-aa83-7e8bcc27bff7', '1768e377-da22-53b9-a803-17c05b731432', NULL, 16, 16, 'Three times in a year shall all your males appear before Yahweh your God in the place which he shall choose: in the feast of unleavened bread, and in the feast of weeks, and in the feast of tents; and they shall not appear before Yahweh empty:'),
  ('7ed8a0e0-88fd-5cd9-a14f-0b715d87c8e4', '1768e377-da22-53b9-a803-17c05b731432', NULL, 17, 17, 'every man shall give as he is able, according to the blessing of Yahweh your God which he has given you.'),
  ('c530fe69-0ab7-5651-aab4-daf2bf996245', '1768e377-da22-53b9-a803-17c05b731432', NULL, 18, 18, 'You shall make judges and officers in all your gates, which Yahweh your God gives you, according to your tribes; and they shall judge the people with righteous judgment.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('7ce4ac33-6c0c-5ee9-a11b-708d455bb78d', '1768e377-da22-53b9-a803-17c05b731432', NULL, 19, 19, 'You shall not wrest justice: you shall not respect persons; neither shall you take a bribe; for a bribe does blind the eyes of the wise, and pervert the words of the righteous.'),
  ('ceab3993-65e6-5f15-ac5e-27cc45eeba22', '1768e377-da22-53b9-a803-17c05b731432', NULL, 20, 20, 'You shall follow that which is altogether just, that you may live, and inherit the land which Yahweh your God gives you.'),
  ('98c529a1-276e-592f-af66-4e7d39a9ca5d', '1768e377-da22-53b9-a803-17c05b731432', NULL, 21, 21, 'You shall not plant for yourselves an Asherah of any kind of tree beside the altar of Yahweh your God, which you shall make for yourselves.'),
  ('42a826d8-ce64-5c62-a94e-68c4a4d269e1', '1768e377-da22-53b9-a803-17c05b731432', NULL, 22, 22, 'Neither shall you set yourself up a pillar; which Yahweh your God hates.'),
  ('59d46eda-8145-5880-ad62-e41bf1703d90', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 1, 1, 'You shall not sacrifice to Yahweh your God an ox, or a sheep, in which is a blemish, [or] anything evil; for that is an abomination to Yahweh your God.'),
  ('efb17a67-6172-58c3-ab9d-4555d303980b', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 2, 2, 'If there be found in the midst of you, within any of your gates which Yahweh your God gives you, man or woman, who does that which is evil in the sight of Yahweh your God, in transgressing his covenant,'),
  ('cbf33525-ab98-5150-a84e-b58a2303fcee', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 3, 3, 'and has gone and served other gods, and worshiped them, or the sun, or the moon, or any of the army of the sky, which I have not commanded;'),
  ('6ccb1635-ea87-5207-a05c-43f311243ca0', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 4, 4, 'and it be told you, and you have heard of it, then you shall inquire diligently; and behold, if it be true, and the thing certain, that such abomination is done in Israel,'),
  ('14c2f2d1-ce32-50d8-a041-87cff157c81e', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 5, 5, 'then you shall bring forth that man or that woman, who has done this evil thing, to your gates, even the man or the woman; and you shall stone them to death with stones.'),
  ('75ec0117-7d37-52d5-a5e2-4ebb040c4b37', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 6, 6, 'At the mouth of two witnesses, or three witnesses, shall he who is to die be put to death; at the mouth of one witness he shall not be put to death.'),
  ('791d75a8-a7d6-5e2b-a78c-3852353499a2', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 7, 7, 'The hand of the witnesses shall be first on him to put him to death, and afterward the hand of all the people. So you shall put away the evil from the midst of you.'),
  ('d523ad21-cdbd-5f65-ad1a-2f222595360d', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 8, 8, 'If there arises a matter too hard for you in judgment, between blood and blood, between plea and plea, and between stroke and stroke, being matters of controversy within your gates; then you shall arise, and go up to the place which Yahweh your God shall choose;'),
  ('9ce0d0d7-3a05-5e78-a214-e6996b531261', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 9, 9, 'and you shall come to the priests the Levites, and to the judge who shall be in those days: and you shall inquire; and they shall show you the sentence of judgment.'),
  ('f1ba0ed5-961b-52c5-a18d-f5bed8e3dd33', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 10, 10, 'You shall do according to the tenor of the sentence which they shall show you from that place which Yahweh shall choose; and you shall observe to do according to all that they shall teach you:'),
  ('a63a9216-14ce-55ed-ad14-f34ab3ddfac2', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 11, 11, 'according to the tenor of the law which they shall teach you, and according to the judgment which they shall tell you, you shall do; you shall not turn aside from the sentence which they shall show you, to the right hand, nor to the left.'),
  ('07504033-9540-521c-a8ec-765c2f5d75dd', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 12, 12, 'The man who does presumptuously, in not listening to the priest who stands to minister there before Yahweh your God, or to the judge, even that man shall die: and you shall put away the evil from Israel.'),
  ('c8580425-a1ed-592a-a045-6c6e2c22391a', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 13, 13, 'All the people shall hear, and fear, and do no more presumptuously.'),
  ('b7b191e0-ac27-5d6b-ae98-3f0ab2c89398', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 14, 14, 'When you are come to the land which Yahweh your God gives you, and shall possess it, and shall dwell therein, and shall say, "I will set a king over me, like all the nations that are around me;"'),
  ('197c1b4e-afcc-5df0-ae3a-922a53fe7791', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 15, 15, 'you shall surely set him king over yourselves, whom Yahweh your God shall choose: one from among your brothers you shall set king over you; you may not put a foreigner over you, who is not your brother.'),
  ('4ce5f01a-6f72-556a-a75d-364b06f6f216', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 16, 16, 'Only he shall not multiply horses to himself, nor cause the people to return to Egypt, to the end that he may multiply horses; because Yahweh has said to you, "You shall not go back that way again."'),
  ('55586d33-3353-50cf-a6d7-e5dd140ff8bc', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 17, 17, 'Neither shall he multiply wives to himself, that his heart not turn away: neither shall he greatly multiply to himself silver and gold.'),
  ('63f6e0bb-003b-551c-a8f7-df7e2e8479d3', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 18, 18, 'It shall be, when he sits on the throne of his kingdom, that he shall write him a copy of this law in a book, out of [that which is] before the priests the Levites:'),
  ('df383d6d-da68-50a7-a91e-f2dd533db1ce', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 19, 19, 'and it shall be with him, and he shall read therein all the days of his life; that he may learn to fear Yahweh his God, to keep all the words of this law and these statutes, to do them;'),
  ('666538c8-b61b-5d5e-adcf-8415eff690d2', 'c440d69c-88b3-5ab1-a08b-f75339ce62d3', NULL, 20, 20, 'that his heart not be lifted up above his brothers, and that he not turn aside from the commandment, to the right hand, or to the left: to the end that he may prolong his days in his kingdom, he and his children, in the midst of Israel.'),
  ('74a657ee-4b41-5f46-a345-07ecdfd7ad64', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 1, 1, 'The priests the Levites, [even] all the tribe of Levi, shall have no portion nor inheritance with Israel: they shall eat the offerings of Yahweh made by fire, and his inheritance.'),
  ('8d90036f-3859-59c3-a4d4-f70b1e93e1f9', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 2, 2, 'They shall have no inheritance among their brothers: Yahweh is their inheritance, as he has spoken to them.'),
  ('7144d48c-bf34-5bdb-a47f-09417fabc746', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 3, 3, 'This shall be the priests'' due from the people, from those who offer a sacrifice, whether it be ox or sheep, that they shall give to the priest the shoulder, and the two cheeks, and the maw.'),
  ('ed1681df-dfce-5910-a0a1-9f49bba431b0', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 4, 4, 'The first fruits of your grain, of your new wine, and of your oil, and the first of the fleece of your sheep, you shall give him.'),
  ('f6d74697-fe5f-5a32-a7d4-b04af7f0e472', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 5, 5, 'For Yahweh your God has chosen him out of all your tribes, to stand to minister in the name of Yahweh, him and his sons for ever.'),
  ('be4a6236-1939-5070-aa4b-29c659258ce6', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 6, 6, 'If a Levite comes from any of your gates out of all Israel, where he lives as a foreigner, and comes with all the desire of his soul to the place which Yahweh shall choose;'),
  ('8546096a-2f1a-50ee-a49b-c3f6d97a89c1', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 7, 7, 'then he shall minister in the name of Yahweh his God, as all his brothers the Levites do, who stand there before Yahweh.'),
  ('b004447e-879b-591a-a528-0f437ce169bb', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 8, 8, 'They shall have like portions to eat, besides that which comes of the sale of his patrimony.'),
  ('695c4dd2-2f6f-5c40-a1ad-fba7a6b27404', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 9, 9, 'When you are come into the land which Yahweh your God gives you, you shall not learn to do after the abominations of those nations.'),
  ('5c15e4a5-e5f4-5360-a50d-522749f471f7', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 10, 10, 'There shall not be found with you anyone who makes his son or his daughter to pass through the fire, one who uses divination, one who practices sorcery, or an enchanter, or a sorcerer,'),
  ('cccaa484-331f-5b82-a5ea-bbe3772cc1e0', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 11, 11, 'or a charmer, or a consulter with a familiar spirit, or a wizard, or a necromancer.'),
  ('122b19f4-5fbf-5493-a8a6-4dee573b90ba', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 12, 12, 'For whoever does these things is an abomination to Yahweh: and because of these abominations Yahweh your God does drive them out from before you.'),
  ('49c2431b-870d-5c2e-a730-f133da97c7bf', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 13, 13, 'You shall be perfect with Yahweh your God.'),
  ('afd5e6fb-21da-57b7-a439-f54cdc78f1e3', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 14, 14, 'For these nations, that you shall dispossess, listen to those who practice sorcery, and to diviners; but as for you, Yahweh your God has not allowed you so to do.'),
  ('db8e595f-f005-5a28-a2da-bc3037bf87fc', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 15, 15, 'Yahweh your God will raise up to you a prophet from the midst of you, of your brothers, like me. You shall listen to him.'),
  ('4101bc92-2c2b-5830-a6e5-c25d92b68ef4', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 16, 16, 'This is according to all that you desired of Yahweh your God in Horeb in the day of the assembly, saying, "Let me not hear again the voice of Yahweh my God, neither let me see this great fire any more, that I not die."'),
  ('b7db6fc9-8943-57d1-a34c-5817b1ea1eb5', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 17, 17, 'Yahweh said to me, "They have well said that which they have spoken.'),
  ('55286d57-94f7-5a19-aaab-15da0b83356f', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 18, 18, 'I will raise them up a prophet from among their brothers, like you; and I will put my words in his mouth, and he shall speak to them all that I shall command him.'),
  ('f492747b-88e2-5edb-a784-a36a1faa1e6e', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 19, 19, 'It shall happen, that whoever will not listen to my words which he shall speak in my name, I will require it of him.'),
  ('faaa5c00-a1e8-5ad3-abd9-400c94b52e47', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 20, 20, 'But the prophet, who shall speak a word presumptuously in my name, which I have not commanded him to speak, or who shall speak in the name of other gods, that same prophet shall die."'),
  ('556303f5-467b-5517-aa57-2100696dbe35', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 21, 21, 'If you say in your heart, "How shall we know the word which Yahweh has not spoken?"'),
  ('753b7f9f-8a0a-5041-a13e-b15e34206c77', '3b3f3f6c-56b9-5c9e-a66a-2863f5ef181f', NULL, 22, 22, 'when a prophet speaks in the name of Yahweh, if the thing doesn''t follow, nor happen, that is the thing which Yahweh has not spoken: the prophet has spoken it presumptuously, you shall not be afraid of him.'),
  ('4dcc4201-8a04-52e4-a383-63cb1ad268cf', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 1, 1, 'When Yahweh your God shall cut off the nations, whose land Yahweh your God gives you, and you succeed them, and dwell in their cities, and in their houses;'),
  ('86de65b2-4c61-5f2e-a3e0-6adc37c33360', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 2, 2, 'you shall set apart three cities for you in the midst of your land, which Yahweh your God gives you to possess it.'),
  ('519435b1-8499-5ac9-a254-334cc14ce7ef', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 3, 3, 'You shall prepare you the way, and divide the borders of your land, which Yahweh your God causes you to inherit, into three parts, that every manslayer may flee there.'),
  ('4b2bc91f-cd81-53da-acec-7f817fd094d5', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 4, 4, 'This is the case of the manslayer, that shall flee there and live: whoever kills his neighbor unawares, and didn''t hate him in time past;'),
  ('efa07b37-f2b4-52ce-ac5a-e17d1dbc5a71', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 5, 5, 'as when a man goes into the forest with his neighbor to chop wood, and his hand fetches a stroke with the axe to cut down the tree, and the head slips from the handle, and lights on his neighbor, so that he dies; he shall flee to one of these cities and live:'),
  ('d6b7de93-653d-5cce-a11e-75b60cd93821', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 6, 6, 'lest the avenger of blood pursue the manslayer, while his heart is hot, and overtake him, because the way is long, and strike him mortally; whereas he was not worthy of death, inasmuch as he didn''t hate him in time past.'),
  ('ec9c4b8c-6a00-59fb-a93d-2abb974b7152', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 7, 7, 'Therefore I command you, saying, You shall set apart three cities for yourselves.'),
  ('94f3d936-b3e1-583d-a353-4b6f1389b4c6', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 8, 8, 'If Yahweh your God enlarges your border, as he has sworn to your fathers, and gives you all the land which he promised to give to your fathers;'),
  ('53a4e8e4-9c6e-5e2b-a65c-a1cc9cb36830', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 9, 9, 'if you keep all this commandment to do it, which I command you this day, to love Yahweh your God, and to walk ever in his ways; then you shall add three cities more for yourselves, besides these three:'),
  ('3fbcd3d0-ce5d-57d6-a09f-075a87cb02af', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 10, 10, 'that innocent blood not be shed in the midst of your land, which Yahweh your God gives you for an inheritance, and so blood be on you.'),
  ('188eaf15-ecea-5269-af7f-7b5475030dfd', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 11, 11, 'But if any man hates his neighbor, and lies in wait for him, and rises up against him, and strikes him mortally so that he dies, and he flees into one of these cities;'),
  ('1814b994-cce6-5641-ac45-3dea182e6f8f', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 12, 12, 'then the elders of his city shall send and bring him there, and deliver him into the hand of the avenger of blood, that he may die.'),
  ('25754f76-6942-57fc-a746-00aea733c0b2', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 13, 13, 'Your eye shall not pity him, but you shall put away the innocent blood from Israel, that it may go well with you.'),
  ('43e1221e-9c10-512b-a3ca-327e4592f834', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 14, 14, 'You shall not remove your neighbor''s landmark, which they of old time have set, in your inheritance which you shall inherit, in the land that Yahweh your God gives you to possess it.'),
  ('78ae2e75-d24c-5aef-a041-54c3ed5379c4', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 15, 15, 'One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sins: at the mouth of two witnesses, or at the mouth of three witnesses, shall a matter be established.'),
  ('02df4305-6bf1-5f45-aaab-92a58a2aace3', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 16, 16, 'If an unrighteous witness rise up against any man to testify against him of wrongdoing,'),
  ('cef44188-96ca-54c4-ad7d-05fb76cdab21', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 17, 17, 'then both the men, between whom the controversy is, shall stand before Yahweh, before the priests and the judges who shall be in those days;'),
  ('e99ccc57-0e64-5ad2-ac59-da21f55bc0a6', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 18, 18, 'and the judges shall make diligent inquisition: and, behold, if the witness is a false witness, and has testified falsely against his brother;'),
  ('de2c10d7-6b44-57f7-a720-c27198fbc1ae', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 19, 19, 'then you shall do to him as he had thought to do to his brother: so you shall put away the evil from the midst of you.'),
  ('92524b42-fc24-5f24-af1f-54caaadd5141', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 20, 20, 'Those who remain shall hear, and fear, and shall henceforth commit no more any such evil in the midst of you.'),
  ('613163b4-f2dc-544a-a60e-d3dc02cf9c31', '9b4b3a90-9a8e-5f89-ab96-4fabc59a7470', NULL, 21, 21, 'Your eyes shall not pity; life [shall go] for life, eye for eye, tooth for tooth, hand for hand, foot for foot.'),
  ('42133880-be35-51db-a5e4-0e6d1ed95a64', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 1, 1, 'When you go forth to battle against your enemies, and see horses, and chariots, [and] a people more than you, you shall not be afraid of them; for Yahweh your God is with you, who brought you up out of the land of Egypt.'),
  ('0d74fb35-836e-5850-a5ab-47215b641d85', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 2, 2, 'It shall be, when you draw near to the battle, that the priest shall approach and speak to the people,'),
  ('823eeb1d-ab6d-5fc4-a35e-645d2b4fe9b2', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 3, 3, 'and shall tell them, "Hear, Israel, you draw near this day to battle against your enemies: don''t let your heart faint; don''t be afraid, nor tremble, neither be scared of them;'),
  ('91d54b98-6cef-5d06-af56-e46833a5d543', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 4, 4, 'for Yahweh your God is he who goes with you, to fight for you against your enemies, to save you."'),
  ('3ea60bbb-cd9e-5b36-a92a-f1068f8a0a06', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 5, 5, 'The officers shall speak to the people, saying, "What man is there who has built a new house, and has not dedicated it? Let him go and return to his house, lest he die in the battle, and another man dedicate it.'),
  ('39f33c83-442b-5a9e-a3d7-684287c4d3df', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 6, 6, 'What man is there who has planted a vineyard, and has not used its fruit? Let him go and return to his house, lest he die in the battle, and another man use its fruit.'),
  ('91df0bbc-950b-5e65-a536-9f4b4a04f71a', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 7, 7, 'What man is there who has pledged to be married a wife, and has not taken her? Let him go and return to his house, lest he die in the battle, and another man take her."'),
  ('993d92de-d45d-570a-a0f1-af365568c7f4', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 8, 8, 'The officers shall speak further to the people, and they shall say, "What man is there who is fearful and fainthearted? Let him go and return to his house, lest his brother''s heart melt as his heart."'),
  ('8a3fe4ae-62e0-52e2-accf-6a5bb76dd0b9', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 9, 9, 'It shall be, when the officers have made an end of speaking to the people, that they shall appoint captains of armies at the head of the people.'),
  ('fabd98f4-d95d-5284-a2b5-695026f1ca03', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 10, 10, 'When you draw near to a city to fight against it, then proclaim peace to it.'),
  ('d010e93e-4757-5e4a-a00f-a861063057aa', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 11, 11, 'It shall be, if it makes you answer of peace, and opens to you, then it shall be, that all the people who are found therein shall become tributary to you, and shall serve you.'),
  ('bf19f0eb-968e-5759-a68d-64a67a02574c', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 12, 12, 'If it will make no peace with you, but will make war against you, then you shall besiege it:'),
  ('138b79ef-9ebe-5c64-a5e1-a6a4644fbe73', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 13, 13, 'and when Yahweh your God delivers it into your hand, you shall strike every male of it with the edge of the sword:'),
  ('f23b86ae-244f-5d9d-ac38-da70c6ddca5a', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 14, 14, 'but the women, and the little ones, and the livestock, and all that is in the city, even all its spoil, you shall take for a prey to yourself; and you shall eat the spoil of your enemies, which Yahweh your God has given you.'),
  ('b75754c3-ec33-5715-a5ae-f65db05c5340', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 15, 15, 'Thus you shall do to all the cities which are very far off from you, which are not of the cities of these nations.'),
  ('71d12154-8fc4-5e1b-a0aa-8bd1fdaf5901', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 16, 16, 'But of the cities of these peoples, that Yahweh your God gives you for an inheritance, you shall save alive nothing that breathes;'),
  ('033d2461-c38d-50a9-ac22-ea48eec3982a', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 17, 17, 'but you shall utterly destroy them: the Hittite, and the Amorite, the Canaanite, and the Perizzite, the Hivite, and the Jebusite; as Yahweh your God has commanded you;'),
  ('6ac884ac-9ce4-5a24-af58-c7cf7842f311', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 18, 18, 'that they not teach you to do after all their abominations, which they have done to their gods; so would you sin against Yahweh your God.'),
  ('2cd090c3-49cd-56d1-ac1b-7c83c9df6b28', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 19, 19, 'When you shall besiege a city a long time, in making war against it to take it, you shall not destroy its trees by wielding an axe against them; for you may eat of them, and you shall not cut them down; for is the tree of the field man, that it should be besieged of you?'),
  ('d3fd6326-518d-514e-a1d6-10a743fe93b3', 'a45e154b-13de-5673-a32a-15ed0c30c761', NULL, 20, 20, 'Only the trees of which you know that they are not trees for food, you shall destroy and cut them down; and you shall build bulwarks against the city that makes war with you, until it fall.'),
  ('d929dd33-219e-5a96-aa4e-f16e635032f2', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 1, 1, 'If one be found slain in the land which Yahweh your God gives you to possess it, lying in the field, and it isn''t known who has struck him;'),
  ('5fb5e41c-7bfd-5c52-a29b-f5c866e30ac1', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 2, 2, 'then your elders and your judges shall come forth, and they shall measure to the cities which are around him who is slain:'),
  ('5a8f8cdc-cd7c-56d2-a3c3-f6bcc56a6aed', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 3, 3, 'and it shall be, that the city which is nearest to the slain man, even the elders of that city shall take a heifer of the herd, which hasn''t been worked with, and which has not drawn in the yoke;'),
  ('518cdb71-ab55-50f7-ad05-3c6c21ba549a', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 4, 4, 'and the elders of that city shall bring down the heifer to a valley with running water, which is neither plowed nor sown, and shall break the heifer''s neck there in the valley.'),
  ('687f5857-d4b7-502f-ab19-4261eeadac70', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 5, 5, 'The priests the sons of Levi shall come near; for them Yahweh your God has chosen to minister to him, and to bless in the name of Yahweh; and according to their word shall every controversy and every stroke be.'),
  ('5849dd0a-bed5-5319-a304-8041e1f700c2', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 6, 6, 'All the elders of that city, who are nearest to the slain man, shall wash their hands over the heifer whose neck was broken in the valley;'),
  ('7f42a784-2246-5eb8-a0d1-4d59c81c19e3', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 7, 7, 'and they shall answer and say, "Our hands have not shed this blood, neither have our eyes seen it.'),
  ('67b77e3b-09a0-503b-ab2a-ba33d4272e50', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 8, 8, 'Forgive, Yahweh, your people Israel, whom you have redeemed, and don''t allow innocent blood [to remain] in the midst of your people Israel." The blood shall be forgiven them.'),
  ('1de51406-f565-57b5-a69a-0eca8a4a0d92', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 9, 9, 'So you shall put away the innocent blood from the midst of you, when you shall do that which is right in the eyes of Yahweh.'),
  ('f7900d90-ffa5-500f-ad80-aa94b17e0940', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 10, 10, 'When you go forth to battle against your enemies, and Yahweh your God delivers them into your hands, and you carry them away captive,'),
  ('95aac713-ee3d-560b-a00d-68ca39b71eea', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 11, 11, 'and see among the captives a beautiful woman, and you have a desire to her, and would take her to you as wife;'),
  ('ed838679-50bd-5efd-af6c-4044d3ec4ce3', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 12, 12, 'then you shall bring her home to your house; and she shall shave her head, and pare her nails;'),
  ('40f732dc-8728-5b6c-a677-60f099c17d91', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 13, 13, 'and she shall put the clothing of her captivity from off her, and shall remain in your house, and bewail her father and her mother a full month: and after that you shall go in to her, and be her husband, and she shall be your wife.'),
  ('703b3e40-6f46-5acd-ab9f-6a9827caa85e', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 14, 14, 'It shall be, if you have no delight in her, then you shall let her go where she will; but you shall not sell her at all for money, you shall not deal with her as a slave, because you have humbled her.'),
  ('10c9d983-6442-5388-aa0a-0faaee5e42ee', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 15, 15, 'If a man have two wives, the one beloved, and the other hated, and they have borne him children, both the beloved and the hated; and if the firstborn son be hers who was hated;'),
  ('c64c00b6-818a-5876-abbc-929ae9b0593e', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 16, 16, 'then it shall be, in the day that he causes his sons to inherit that which he has, that he may not make the son of the beloved the firstborn before the son of the hated, who is the firstborn:'),
  ('88c9a5f6-f928-5313-a76c-0725522358ec', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 17, 17, 'but he shall acknowledge the firstborn, the son of the hated, by giving him a double portion of all that he has; for he is the beginning of his strength; the right of the firstborn is his.'),
  ('84da3b0e-1be7-56a5-a9d4-5fb7773f193e', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 18, 18, 'If a man have a stubborn and rebellious son, who will not obey the voice of his father, or the voice of his mother, and, though they chasten him, will not listen to them;'),
  ('d100ab33-c1b4-52bd-aab0-2b64b6bb83bf', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 19, 19, 'then shall his father and his mother lay hold on him, and bring him out to the elders of his city, and to the gate of his place;'),
  ('f16d1766-adb5-505a-ab35-e3ad85cbab9f', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 20, 20, 'and they shall tell the elders of his city, "This our son is stubborn and rebellious, he will not obey our voice; he is a glutton, and a drunkard."'),
  ('1143f917-c25b-5248-a0dc-2cfa7290d01f', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 21, 21, 'All the men of his city shall stone him to death with stones: so you shall put away the evil from the midst of you; and all Israel shall hear, and fear.'),
  ('92f2fc23-8e2c-5912-a593-75e67db72613', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 22, 22, 'If a man have committed a sin worthy of death, and he be put to death, and you hang him on a tree;'),
  ('bc61d9bb-db01-592b-a241-56e9dd2abfa4', '6dde6b67-0364-52d9-a12d-cc73f1ad2d0e', NULL, 23, 23, 'his body shall not remain all night on the tree, but you shall surely bury him the same day; for he who is hanged is accursed of God; that you don''t defile your land which Yahweh your God gives you for an inheritance.'),
  ('3f304b9b-a223-5544-ac11-2636cee3b7ad', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 1, 1, 'You shall not see your brother''s ox or his sheep go astray, and hide yourself from them: you shall surely bring them again to your brother.'),
  ('0108b15b-cb49-5ddd-a828-df91d3c107af', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 2, 2, 'If your brother isn''t near to you, or if you don''t know him, then you shall bring it home to your house, and it shall be with you until your brother seek after it, and you shall restore it to him.'),
  ('7652c1e2-9445-5264-a620-661af92f8fbd', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 3, 3, 'So you shall do with his donkey; and so you shall do with his garment; and so you shall do with every lost thing of your brother''s, which he has lost, and you have found: you may not hide yourself.'),
  ('e0dae6c3-85d5-550b-afb2-8293f28f70fb', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 4, 4, 'You shall not see your brother''s donkey or his ox fallen down by the way, and hide yourself from them: you shall surely help him to lift them up again.'),
  ('80233559-c521-5bc7-a845-1197b5692121', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 5, 5, 'A woman shall not wear men''s clothing, neither shall a man put on women''s clothing; for whoever does these things is an abomination to Yahweh your God.'),
  ('92b63111-8a20-563c-aa97-0c454c09f872', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 6, 6, 'If a bird''s nest chance to be before you in the way, in any tree or on the ground, with young ones or eggs, and the hen sitting on the young, or on the eggs, you shall not take the hen with the young:'),
  ('a3b6b481-46d7-5d78-a74a-51b505e16647', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 7, 7, 'you shall surely let the hen go, but the young you may take to yourself; that it may be well with you, and that you may prolong your days.'),
  ('e9972888-a8e3-59f6-a031-b0306c24892d', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 8, 8, 'When you build a new house, then you shall make a battlement for your roof, that you don''t bring blood on your house, if any man fall from there.'),
  ('bb2eae8e-ff01-546e-ae5c-69bc5289de40', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 9, 9, 'You shall not sow your vineyard with two kinds of seed, lest the whole fruit be forfeited, the seed which you have sown, and the increase of the vineyard.'),
  ('c6ed8827-5821-5a8f-a9c0-61333780052a', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 10, 10, 'You shall not plow with an ox and a donkey together.'),
  ('a23f072e-d31d-5764-a8c7-906b85e5059e', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 11, 11, 'You shall not wear a mixed stuff, wool and linen together.'),
  ('c11c69fb-2d1c-5d7b-a3ec-6faceda3a090', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 12, 12, 'You shall make yourselves fringes on the four borders of your cloak, with which you cover yourself.'),
  ('38a3cc86-8c88-5f6f-a386-59395e8def52', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 13, 13, 'If any man takes a wife, and goes in to her, and hates her,'),
  ('c18a4613-2284-53f1-a566-b664c95815ee', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 14, 14, 'and accuses her of shameful things, and brings up an evil name on her, and says, "I took this woman, and when I came near to her, I didn''t find in her the tokens of virginity;"'),
  ('e1145e72-ddd9-52f9-a58d-179e69db4f1a', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 15, 15, 'then shall the father of the young lady, and her mother, take and bring forth the tokens of the young lady''s virginity to the elders of the city in the gate;'),
  ('6b2be2c7-d991-5dda-a18b-dfb509528c91', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 16, 16, 'and the young lady''s father shall tell the elders, "I gave my daughter to this man to wife, and he hates her;'),
  ('9e3b4945-1bf8-529c-a798-b04821c44d24', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 17, 17, 'and behold, he has accused her of shameful things, saying, ''I didn''t find in your daughter the tokens of virginity;'' and yet these are the tokens of my daughter''s virginity." They shall spread the cloth before the elders of the city.'),
  ('95525c11-9773-51c5-a708-55c3bd98cbe0', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 18, 18, 'The elders of that city shall take the man and chastise him;'),
  ('eacbe5a0-9605-563d-a3ec-f37b266dc959', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 19, 19, 'and they shall fine him one hundred [shekels] of silver, and give them to the father of the young lady, because he has brought up an evil name on a virgin of Israel: and she shall be his wife; he may not put her away all his days.'),
  ('c01a8b28-e4a8-5af8-a64e-2542fbd2a25b', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 20, 20, 'But if this thing be true, that the tokens of virginity were not found in the young lady;'),
  ('44804fe7-7795-51b1-a245-c8f23d566417', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 21, 21, 'then they shall bring out the young lady to the door of her father''s house, and the men of her city shall stone her to death with stones, because she has done folly in Israel, to play the prostitute in her father''s house: so you shall put away the evil from the midst of you.'),
  ('8bf9d765-2318-5acd-a822-01fca2fe78a6', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 22, 22, 'If a man be found lying with a woman married to a husband, then they shall both of them die, the man who lay with the woman, and the woman: so you shall put away the evil from Israel.'),
  ('10610264-d34c-5546-af73-2dc08cbbfab9', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 23, 23, 'If there is a young lady who is a virgin pledged to be married to a husband, and a man find her in the city, and lie with her;'),
  ('8082145b-f5f5-528a-a841-6896c04b63cd', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 24, 24, 'then you shall bring them both out to the gate of that city, and you shall stone them to death with stones; the lady, because she didn''t cry, being in the city; and the man, because he has humbled his neighbor''s wife: so you shall put away the evil from the midst of you.'),
  ('db563bff-ea17-58ec-a3eb-cac2217d2bec', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 25, 25, 'But if the man find the lady who is pledged to be married in the field, and the man force her, and lie with her; then the man only who lay with her shall die:'),
  ('c68c0286-5ea7-5a37-a400-a45ee499b779', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 26, 26, 'but to the lady you shall do nothing; there is in the lady no sin worthy of death: for as when a man rises against his neighbor, and kills him, even so is this matter;'),
  ('11d33990-c51d-570f-a57e-3dd9626a5d07', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 27, 27, 'for he found her in the field, the pledged to be married lady cried, and there was none to save her.'),
  ('70789115-83e3-5c86-a576-ac26ff5854e3', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 28, 28, 'If a man find a lady who is a virgin, who is not pledged to be married, and lay hold on her, and lie with her, and they be found;'),
  ('c202b8b4-ed25-597a-a7fd-9a6b9943ca86', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 29, 29, 'then the man who lay with her shall give to the lady''s father fifty [shekels] of silver, and she shall be his wife, because he has humbled her; he may not put her away all his days.'),
  ('14064e9c-b62c-5512-ae34-2457a002a141', '87aacdf9-f244-539d-af79-140b9fc2e225', NULL, 30, 30, 'A man shall not take his father''s wife, and shall not uncover his father''s skirt.'),
  ('9ab15ff3-25ca-5580-ab2b-927a1dac09e9', '34170271-0dba-536b-ae65-a21a66777113', NULL, 1, 1, 'He who is wounded in the stones, or has his privy member cut off, shall not enter into the assembly of Yahweh.'),
  ('d71d6edf-4a8f-59f3-a43d-b0c0a21a50ef', '34170271-0dba-536b-ae65-a21a66777113', NULL, 2, 2, 'A bastard shall not enter into the assembly of Yahweh; even to the tenth generation shall none of his enter into the assembly of Yahweh.'),
  ('8f2f3fbb-788a-5803-aa92-93f992aff89f', '34170271-0dba-536b-ae65-a21a66777113', NULL, 3, 3, 'An Ammonite or a Moabite shall not enter into the assembly of Yahweh; even to the tenth generation shall none belonging to them enter into the assembly of Yahweh forever:'),
  ('ac752620-2c1e-5051-ad73-d8193d5bd2e9', '34170271-0dba-536b-ae65-a21a66777113', NULL, 4, 4, 'because they didn''t meet you with bread and with water in the way, when you came forth out of Egypt, and because they hired against you Balaam the son of Beor from Pethor of Mesopotamia, to curse you.'),
  ('134c35a1-f912-5b90-aa74-ebe9a4e423ba', '34170271-0dba-536b-ae65-a21a66777113', NULL, 5, 5, 'Nevertheless Yahweh your God wouldn''t listen to Balaam; but Yahweh your God turned the curse into a blessing to you, because Yahweh your God loved you.'),
  ('d4f14fa7-953a-56e1-a1fe-7a1c806e6382', '34170271-0dba-536b-ae65-a21a66777113', NULL, 6, 6, 'You shall not seek their peace nor their prosperity all your days forever.'),
  ('2b3835d9-879e-5fdc-a792-24e213fa3a41', '34170271-0dba-536b-ae65-a21a66777113', NULL, 7, 7, 'You shall not abhor an Edomite; for he is your brother: you shall not abhor an Egyptian, because you lived as a foreigner in his land.'),
  ('956e59a3-cf4a-502b-a4fd-e1c91933d91d', '34170271-0dba-536b-ae65-a21a66777113', NULL, 8, 8, 'The children of the third generation who are born to them shall enter into the assembly of Yahweh.'),
  ('7ae2fbff-3ad5-55e0-aa3e-1db708af3fa0', '34170271-0dba-536b-ae65-a21a66777113', NULL, 9, 9, 'When you go forth in camp against your enemies, then you shall keep yourselves from every evil thing.'),
  ('c9d9f31b-27a0-5ece-a252-f577cae4d1c1', '34170271-0dba-536b-ae65-a21a66777113', NULL, 10, 10, 'If there is among you any man who is not clean by reason of that which happens him by night, then shall he go outside of the camp. He shall not come within the camp:'),
  ('893349f5-0199-5800-a352-12f90ab673ff', '34170271-0dba-536b-ae65-a21a66777113', NULL, 11, 11, 'but it shall be, when evening comes on, he shall bathe himself in water; and when the sun is down, he shall come within the camp.'),
  ('912bcb84-59da-510d-aeb9-c7e7587ab8f0', '34170271-0dba-536b-ae65-a21a66777113', NULL, 12, 12, 'You shall have a place also outside of the camp, where you shall go forth abroad:'),
  ('39b05ee7-e92e-5665-a90a-30ffb08491e6', '34170271-0dba-536b-ae65-a21a66777113', NULL, 13, 13, 'and you shall have a paddle among your weapons; and it shall be, when you sit down abroad, you shall dig therewith, and shall turn back and cover that which comes from you:'),
  ('0acd142a-6937-50d3-a59c-167550b9c108', '34170271-0dba-536b-ae65-a21a66777113', NULL, 14, 14, 'for Yahweh your God walks in the midst of your camp, to deliver you, and to give up your enemies before you; therefore your camp shall be holy, that he may not see an unclean thing in you, and turn away from you.'),
  ('092fbd4b-f457-5f43-ad99-6b6b4b50331b', '34170271-0dba-536b-ae65-a21a66777113', NULL, 15, 15, 'You shall not deliver to his master a servant who is escaped from his master to you:'),
  ('b1532a52-c509-51e3-a3dc-915aff62b453', '34170271-0dba-536b-ae65-a21a66777113', NULL, 16, 16, 'he shall dwell with you, in the midst of you, in the place which he shall choose within one of your gates, where it pleases him best: you shall not oppress him.'),
  ('15cb6944-cf74-5558-ab3a-64fdb407fa0a', '34170271-0dba-536b-ae65-a21a66777113', NULL, 17, 17, 'There shall be no prostitute of the daughters of Israel, neither shall there be a sodomite of the sons of Israel.'),
  ('b88d9af9-b93e-55fc-a96e-29a797ddde8c', '34170271-0dba-536b-ae65-a21a66777113', NULL, 18, 18, 'You shall not bring the hire of a prostitute, or the wages of a dog, into the house of Yahweh your God for any vow: for even both these are an abomination to Yahweh your God.'),
  ('aba93419-b073-5444-a73c-53c2316dd345', '34170271-0dba-536b-ae65-a21a66777113', NULL, 19, 19, 'You shall not lend on interest to your brother; interest of money, interest of food, interest of anything that is lent on interest:'),
  ('c0156855-9af0-561a-a261-13f315d91464', '34170271-0dba-536b-ae65-a21a66777113', NULL, 20, 20, 'to a foreigner you may lend on interest; but to your brother you shall not lend on interest, that Yahweh your God may bless you in all that you put your hand to, in the land where you go in to possess it.'),
  ('573d0892-2c53-50c1-a712-d8a1fa9278c5', '34170271-0dba-536b-ae65-a21a66777113', NULL, 21, 21, 'When you shall vow a vow to Yahweh your God, you shall not be slack to pay it: for Yahweh your God will surely require it of you; and it would be sin in you.'),
  ('d55db61f-5f3b-5a6f-afc0-210a0b6bffa9', '34170271-0dba-536b-ae65-a21a66777113', NULL, 22, 22, 'But if you shall forbear to vow, it shall be no sin in you.'),
  ('4d8abdce-3788-524a-aadc-481bb100e72e', '34170271-0dba-536b-ae65-a21a66777113', NULL, 23, 23, 'That which is gone out of your lips you shall observe and do; according as you have vowed to Yahweh your God, a freewill offering, which you have promised with your mouth.'),
  ('1ae330ee-f142-54f8-a346-014e108dcc4f', '34170271-0dba-536b-ae65-a21a66777113', NULL, 24, 24, 'When you come into your neighbor''s vineyard, then you may eat of grapes your fill at your own pleasure; but you shall not put any in your vessel.'),
  ('01dc5bf3-ae86-50f4-ac27-c2c1cb856c9c', '34170271-0dba-536b-ae65-a21a66777113', NULL, 25, 25, 'When you come into your neighbor''s standing grain, then you may pluck the ears with your hand; but you shall not move a sickle to your neighbor''s standing grain.'),
  ('c6566a60-80ce-52ea-a81f-26cf60262c78', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 1, 1, 'When a man takes a wife, and marries her, then it shall be, if she find no favor in his eyes, because he has found some unseemly thing in her, that he shall write her a bill of divorce, and give it in her hand, and send her out of his house.'),
  ('4689ae79-5bf3-5891-a9b6-5bd8713d015a', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 2, 2, 'When she is departed out of his house, she may go and be another man''s [wife].'),
  ('31d09860-f4ea-57a7-a6bd-1f9acc8efb07', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 3, 3, 'If the latter husband hate her, and write her a bill of divorce, and give it in her hand, and send her out of his house; or if the latter husband die, who took her to be his wife;'),
  ('ed2bd5ba-ba1a-5b5b-a091-4a6382505ed5', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 4, 4, 'her former husband, who sent her away, may not take her again to be his wife, after that she is defiled; for that is abomination before Yahweh: and you shall not cause the land to sin, which Yahweh your God gives you for an inheritance.'),
  ('40badfa2-c57f-5245-a6b4-a43b5494577a', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 5, 5, 'When a man takes a new wife, he shall not go out in the army, neither shall he be assigned any business: he shall be free at home one year, and shall cheer his wife whom he has taken.'),
  ('0568e801-d761-5b51-a964-db5b3ed77ef0', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 6, 6, 'No man shall take the mill or the upper millstone to pledge; for he takes [a man''s] life to pledge.'),
  ('d38dd07a-4d29-565b-ac78-990828572146', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 7, 7, 'If a man be found stealing any of his brothers of the children of Israel, and he deal with him as a slave, or sell him; then that thief shall die: so you shall put away the evil from the midst of you.'),
  ('66795559-9414-558a-a59f-4204cbccd4b4', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 8, 8, 'Take heed in the plague of leprosy, that you observe diligently, and do according to all that the priests the Levites shall teach you: as I commanded them, so you shall observe to do.'),
  ('9dcf5667-80e6-5db9-aec4-d6d130f77ad7', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 9, 9, 'Remember what Yahweh your God did to Miriam, by the way as you came forth out of Egypt.'),
  ('05881872-bb30-53c6-abfe-5ff01f6a3f35', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 10, 10, 'When you do lend your neighbor any kind of loan, you shall not go into his house to get his pledge.'),
  ('30fe515d-989f-5bf1-a113-a7cc78ebbfe2', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 11, 11, 'You shall stand outside, and the man to whom you do lend shall bring forth the pledge outside to you.'),
  ('e945386a-133d-5ab9-ad08-a4fed44e36db', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 12, 12, 'If he be a poor man, you shall not sleep with his pledge;'),
  ('cb08f76e-d54e-5620-a71c-fac34c85b953', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 13, 13, 'you shall surely restore to him the pledge when the sun goes down, that he may sleep in his garment, and bless you: and it shall be righteousness to you before Yahweh your God.'),
  ('b1508ec9-6f18-52c1-a805-07d3c693b819', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 14, 14, 'You shall not oppress a hired servant who is poor and needy, whether he be of your brothers, or of your foreigners who are in your land within your gates:'),
  ('3b61fd33-4b8e-53fd-a5dc-18a5adec443b', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 15, 15, 'in his day you shall give him his hire, neither shall the sun go down on it; for he is poor, and sets his heart on it: lest he cry against you to Yahweh, and it be sin to you.'),
  ('8e396b13-53e0-5978-a906-39f92ae6611a', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 16, 16, 'The fathers shall not be put to death for the children, neither shall the children be put to death for the fathers: every man shall be put to death for his own sin.'),
  ('12df1ca6-fcf1-5c08-aa8a-a5ffe2c1ef00', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 17, 17, 'You shall not wrest the justice [due] to the foreigner, [or] to the fatherless, nor take the widow''s clothing to pledge;'),
  ('9282aa2e-7641-55ec-afa8-b200f808224a', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 18, 18, 'but you shall remember that you were a bondservant in Egypt, and Yahweh your God redeemed you there: therefore I command you to do this thing.'),
  ('ea554151-2675-5f1c-a321-fc1798fb3537', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 19, 19, 'When you reap your harvest in your field, and have forgot a sheaf in the field, you shall not go again to get it: it shall be for the foreigner, for the fatherless, and for the widow; that Yahweh your God may bless you in all the work of your hands.'),
  ('2a0201e2-3cfd-510f-afc5-a11d265031f4', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 20, 20, 'When you beat your olive tree, you shall not go over the boughs again: it shall be for the foreigner, for the fatherless, and for the widow.'),
  ('64802166-1819-515b-ae2f-5749c97778f2', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 21, 21, 'When you gather [the grapes of] your vineyard, you shall not glean it after yourselves: it shall be for the foreigner, for the fatherless, and for the widow.'),
  ('6fb21279-bbe9-5760-a5ad-b5040d2acfc8', 'f3e9d59e-fdf0-5cc8-a0ea-beba250a96d3', NULL, 22, 22, 'You shall remember that you were a bondservant in the land of Egypt: therefore I command you to do this thing.'),
  ('bbb4ff20-d656-5f8e-a98c-ef095ec2d70d', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 1, 1, 'If there be a controversy between men, and they come to judgment, and [the judges] judge them; then they shall justify the righteous, and condemn the wicked;'),
  ('26e930bf-058e-5744-a40f-d17eb70cc4da', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 2, 2, 'and it shall be, if the wicked man be worthy to be beaten, that the judge shall cause him to lie down, and to be beaten before his face, according to his wickedness, by number.'),
  ('8e55169b-f92f-593d-a310-e1fcdb13b695', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 3, 3, 'Forty stripes he may give him, he shall not exceed; lest, if he should exceed, and beat him above these with many stripes, then your brother should seem vile to you.'),
  ('53d7ab45-4237-54e8-aa4e-0df6d2ddd829', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 4, 4, 'You shall not muzzle the ox when he treads out [the grain].'),
  ('5900f45a-b9bb-5d54-a2db-aba959144243', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 5, 5, 'If brothers dwell together, and one of them die, and have no son, the wife of the dead shall not be married outside to a stranger: her husband''s brother shall go in to her, and take her to him as wife, and perform the duty of a husband''s brother to her.'),
  ('78149533-a6c3-54c3-a6d4-853cba7d1e14', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 6, 6, 'It shall be, that the firstborn whom she bears shall succeed in the name of his brother who is dead, that his name not be blotted out of Israel.'),
  ('1aafd269-1279-549b-a98a-e6b94ad24621', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 7, 7, 'If the man doesn''t want to take his brother''s wife, then his brother''s wife shall go up to the gate to the elders, and say, "My husband''s brother refuses to raise up to his brother a name in Israel; he will not perform the duty of a husband''s brother to me."'),
  ('a596c52c-3127-5d04-a850-2eee3f8ae8e7', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 8, 8, 'Then the elders of his city shall call him, and speak to him: and if he stand, and say, "I don''t want to take her;"'),
  ('1f7dd911-12a0-5fc0-acd0-365f9779c39c', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 9, 9, 'then his brother''s wife shall come to him in the presence of the elders, and loose his shoe from off his foot, and spit in his face; and she shall answer and say, "So shall it be done to the man who does not build up his brother''s house."'),
  ('2354d4fe-69ca-5aa1-a0b7-e11f1b40143d', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 10, 10, 'His name shall be called in Israel, The house of him who has his shoe untied.'),
  ('f8e895d3-c6f7-5577-a0e1-18b7270801c6', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 11, 11, 'When men strive together one with another, and the wife of the one draws near to deliver her husband out of the hand of him who strikes him, and puts forth her hand, and takes him by the secrets;'),
  ('43eeac3f-5fc5-5059-aace-86c5d8fe235f', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 12, 12, 'then you shall cut off her hand, your eye shall have no pity.'),
  ('bd891f47-125e-5020-aff3-74dc883e2156', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 13, 13, 'You shall not have in your bag diverse weights, a great and a small.'),
  ('5f51683c-d204-529e-a922-dc5a547bc28c', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 14, 14, 'You shall not have in your house diverse measures, a great and a small.'),
  ('602e4f05-1164-53cd-a500-6b6625e0950f', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 15, 15, 'You shall have a perfect and just weight. You shall have a perfect and just measure, that your days may be long in the land which Yahweh your God gives you.'),
  ('b63b962b-e6bb-54de-a029-22232f2ceae5', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 16, 16, 'For all who do such things, [even] all who do unrighteously, are an abomination to Yahweh your God.'),
  ('ba660f0c-0a6c-5957-a3c4-9379852d4404', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 17, 17, 'Remember what Amalek did to you by the way as you came forth out of Egypt;'),
  ('d8429bbf-0680-5d87-ae9c-998936284a52', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 18, 18, 'how he met you by the way, and struck the hindmost of you, all who were feeble behind you, when you were faint and weary; and he didn''t fear God.'),
  ('266311af-aa81-5e73-aa19-e6862889066b', '3f390100-da47-581d-a9e0-d2a681ef83f4', NULL, 19, 19, 'Therefore it shall be, when Yahweh your God has given you rest from all your enemies all around, in the land which Yahweh your God gives you for an inheritance to possess it, that you shall blot out the memory of Amalek from under the sky; you shall not forget.'),
  ('a94e07c7-e069-58b9-a8b5-8314b9a3781a', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 1, 1, 'It shall be, when you are come in to the land which Yahweh your God gives you for an inheritance, and possess it, and dwell therein,'),
  ('101059e4-2b41-5384-a6f3-f18264167ea1', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 2, 2, 'that you shall take of the first of all the fruit of the ground, which you shall bring in from your land that Yahweh your God gives you; and you shall put it in a basket, and shall go to the place which Yahweh your God shall choose, to cause his name to dwell there.'),
  ('6004612d-d094-5eaa-a85a-07f17315eb84', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 3, 3, 'You shall come to the priest who shall be in those days, and tell him, "I profess this day to Yahweh your God, that I am come to the land which Yahweh swore to our fathers to give us."'),
  ('feb32a9e-1d35-51be-ab62-1f6889bdbcd1', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 4, 4, 'The priest shall take the basket out of your hand, and set it down before the altar of Yahweh your God.'),
  ('cff15067-26b5-569d-aef3-db2ebe89aa41', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 5, 5, 'You shall answer and say before Yahweh your God, "A Syrian ready to perish was my father; and he went down into Egypt, and lived there, few in number; and he became there a nation, great, mighty, and populous.'),
  ('fba2a88c-f286-53f1-aab9-6383aa91f270', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 6, 6, 'The Egyptians dealt ill with us, and afflicted us, and laid on us hard bondage:'),
  ('f12ea3b1-7760-5094-af79-c1646875be22', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 7, 7, 'and we cried to Yahweh, the God of our fathers, and Yahweh heard our voice, and saw our affliction, and our toil, and our oppression;'),
  ('77e3c9e0-238e-563a-a6c4-badbfacccc14', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 8, 8, 'and Yahweh brought us forth out of Egypt with a mighty hand, and with an outstretched arm, and with great terror, and with signs, and with wonders;'),
  ('ccb26856-e90c-55b3-a8e9-72e4b0a3d887', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 9, 9, 'and he has brought us into this place, and has given us this land, a land flowing with milk and honey.'),
  ('90835578-80ff-50b2-a59b-620aa4bd707d', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 10, 10, 'Now, behold, I have brought the first of the fruit of the ground, which you, Yahweh, have given me." You shall set it down before Yahweh your God, and worship before Yahweh your God.'),
  ('cf2da935-ba27-5782-a4d5-dc173326aa63', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 11, 11, 'You shall rejoice in all the good which Yahweh your God has given to you, and to your house, you, and the Levite, and the foreigner who is in the midst of you.'),
  ('b71960eb-2b17-5868-a95e-d43cbadabf45', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 12, 12, 'When you have made an end of tithing all the tithe of your increase in the third year, which is the year of tithing, then you shall give it to the Levite, to the foreigner, to the fatherless, and to the widow, that they may eat within your gates, and be filled.'),
  ('2a3ecf1c-8f9e-59cf-a502-ccf228b91151', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 13, 13, 'You shall say before Yahweh your God, "I have put away the holy things out of my house, and also have given them to the Levite, and to the foreigner, to the fatherless, and to the widow, according to all your commandment which you have commanded me: I have not transgressed any of your commandments, neither have I forgotten them:'),
  ('d4e3f5f8-eb78-553e-a401-f0fa92ace064', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 14, 14, 'I have not eaten of it in my mourning, neither have I put away of it, being unclean, nor given of it for the dead: I have listened to the voice of Yahweh my God; I have done according to all that you have commanded me.'),
  ('f75c33b1-bb22-5dcb-a1e8-6fa05b654678', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 15, 15, 'Look down from your holy habitation, from heaven, and bless your people Israel, and the ground which you have given us, as you swore to our fathers, a land flowing with milk and honey."'),
  ('727cd3ae-51f0-5359-a194-c45338a4a954', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 16, 16, 'This day Yahweh your God commands you to do these statutes and ordinances: you shall therefore keep and do them with all your heart, and with all your soul.'),
  ('0bce314d-038f-5f78-accf-1f11386243a0', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 17, 17, 'You have declared Yahweh this day to be your God, and that you would walk in his ways, and keep his statutes, and his commandments, and his ordinances, and listen to his voice:'),
  ('ff1c44ff-92a8-5894-a7dc-0ce9f9ce00b7', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 18, 18, 'and Yahweh has declared you this day to be a people for his own possession, as he has promised you, and that you should keep all his commandments;'),
  ('dc5ae8dd-e366-59fe-a06e-45ed95a66e61', 'e9f61ab0-4b5c-5ca9-a838-6db2e570673a', NULL, 19, 19, 'and to make you high above all nations that he has made, in praise, and in name, and in honor; and that you may be a holy people to Yahweh your God, as he has spoken.'),
  ('df463338-c762-5c0b-a0f6-38ac47a8ea12', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 1, 1, 'Moses and the elders of Israel commanded the people, saying, "Keep all the commandment which I command you this day.'),
  ('15f6ba2a-a9cf-5e95-a387-70b216298f0a', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 2, 2, 'It shall be on the day when you shall pass over the Jordan to the land which Yahweh your God gives you, that you shall set yourself up great stones, and plaster them with plaster:'),
  ('46dab922-ce95-50e7-ab0a-bce92dd092d9', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 3, 3, 'and you shall write on them all the words of this law, when you have passed over; that you may go in to the land which Yahweh your God gives you, a land flowing with milk and honey, as Yahweh, the God of your fathers, has promised you.'),
  ('dc5003ba-da2d-5735-a477-a1915618387e', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 4, 4, 'It shall be, when you have passed over the Jordan, that you shall set up these stones, which I command you this day, in Mount Ebal, and you shall plaster them with plaster.'),
  ('52fbf336-9f5e-58e9-ac4d-db9643b1e967', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 5, 5, 'There you shall build an altar to Yahweh your God, an altar of stones: you shall lift up no iron [tool] on them.'),
  ('ee583829-74d7-5665-a24f-8c84bca60a63', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 6, 6, 'You shall build the altar of Yahweh your God of uncut stones; and you shall offer burnt offerings thereon to Yahweh your God:'),
  ('1acba06f-b2b3-5cae-afb8-6763db3083f1', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 7, 7, 'and you shall sacrifice peace offerings, and shall eat there; and you shall rejoice before Yahweh your God.'),
  ('e75fcb44-3a2b-5f91-a59e-f05e688120e6', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 8, 8, 'You shall write on the stones all the words of this law very plainly."'),
  ('2bce123b-66fd-5340-ad09-50e769a4254b', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 9, 9, 'Moses and the priests the Levites spoke to all Israel, saying, "Keep silence, and listen, Israel: this day you have become the people of Yahweh your God.'),
  ('76be0763-38ce-5626-ae93-273000f3b4df', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 10, 10, 'You shall therefore obey the voice of Yahweh your God, and do his commandments and his statutes, which I command you this day."'),
  ('39590411-24d2-5c25-ae03-53ddf9d7c55a', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 11, 11, 'Moses commanded the people the same day, saying,'),
  ('f32643e1-1b1d-5fdd-a221-c40e82fb55d0', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 12, 12, '"These shall stand on Mount Gerizim to bless the people, when you have passed over the Jordan: Simeon, and Levi, and Judah, and Issachar, and Joseph, and Benjamin.'),
  ('dfca9f50-c04f-53bd-a070-bf9b473107d3', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 13, 13, 'These shall stand on Mount Ebal for the curse: Reuben, Gad, and Asher, and Zebulun, Dan, and Naphtali.'),
  ('55bd907a-5d46-54ba-ac72-c5b15d874a13', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 14, 14, 'The Levites shall answer, and tell all the men of Israel with a loud voice,'),
  ('49f3e3ea-11c6-548e-a0cd-98eba59ae4eb', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 15, 15, '''Cursed is the man who makes an engraved or molten image, an abomination to Yahweh, the work of the hands of the craftsman, and sets it up in secret.'' All the people shall answer and say, ''Amen.'''),
  ('71f980fe-3c36-5b60-a120-162da0768cf0', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 16, 16, '''Cursed is he who sets light by his father or his mother.'' All the people shall say, ''Amen.'''),
  ('9a043dd7-04e6-5ffe-af1d-915a291ff3de', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 17, 17, '''Cursed is he who removes his neighbor''s landmark.'' All the people shall say, ''Amen.'''),
  ('67004f33-2a72-56d9-a0d5-8d17d6873c00', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 18, 18, '''Cursed is he who makes the blind to wander out of the way.'' All the people shall say, ''Amen.'''),
  ('57585b51-7c0e-50c6-a28e-d4be8ca9f618', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 19, 19, '''Cursed is he who wrests the justice [due] to the foreigner, fatherless, and widow.'' All the people shall say, ''Amen.'''),
  ('0149e890-5b08-5840-a988-b3f32a3d748d', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 20, 20, '''Cursed is he who lies with his father''s wife, because he has uncovered his father''s skirt.'' All the people shall say, ''Amen.'''),
  ('2a88aa4e-0f9b-5b17-a314-72a90c182e16', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 21, 21, '''Cursed is he who lies with any kind of animal.'' All the people shall say, ''Amen.'''),
  ('8eb16f78-7346-5752-a6be-4b7ab1f234fa', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 22, 22, '''Cursed is he who lies with his sister, the daughter of his father, or the daughter of his mother.'' All the people shall say, ''Amen.'''),
  ('50dce932-d6cb-56fb-a646-bd01de9bdb57', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 23, 23, '''Cursed is he who lies with his mother-in-law.'' All the people shall say, ''Amen.'''),
  ('040a6ea3-82ca-5bd9-adcc-9c27b28080fc', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 24, 24, '''Cursed is he who strikes his neighbor in secret.'' All the people shall say, ''Amen.'''),
  ('71f66c2c-5bcd-5b4d-aecd-d203bd828a0f', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 25, 25, '''Cursed is he who takes a bribe to kill an innocent person.'' All the people shall say, ''Amen.''')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('bb961d6a-16d6-5b69-aabd-b82deb0e964e', '2f2e9cc4-307e-5f96-afd6-67605acab9f5', NULL, 26, 26, '''Cursed is he who doesn''t confirm the words of this law to do them.'' All the people shall say, ''Amen.''"'),
  ('d42d1334-6dce-5bbf-aae0-f5d30255cb1d', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 1, 1, 'It shall happen, if you shall listen diligently to the voice of Yahweh your God, to observe to do all his commandments which I command you this day, that Yahweh your God will set you on high above all the nations of the earth:'),
  ('76be80e9-121b-5bd4-a04b-855689ee2100', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 2, 2, 'and all these blessings shall come on you, and overtake you, if you shall listen to the voice of Yahweh your God.'),
  ('df634dc6-81c1-556e-ab0e-28966a1023b4', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 3, 3, 'You shall be blessed in the city, and you shall be blessed in the field.'),
  ('d8eb5deb-6886-596f-ab4c-2fd207a85c5c', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 4, 4, 'You shall be blessed in the fruit of your body, the fruit of your ground, the fruit of your animals, the increase of your livestock, and the young of your flock.'),
  ('a761a1a2-584a-5d8b-a123-80fd10f239e2', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 5, 5, 'Your basket and your kneading trough shall be blessed.'),
  ('a664c277-c413-5df9-ad6f-79736bff9597', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 6, 6, 'You shall be blessed when you come in, and you shall be blessed when you go out.'),
  ('1d96b322-2083-5c43-ad43-d50c1feff779', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 7, 7, 'Yahweh will cause your enemies who rise up against you to be struck before you. They will come out against you one way, and will flee before you seven ways.'),
  ('1faf6c93-485f-57dd-a50d-08648eb1518c', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 8, 8, 'Yahweh will command the blessing on you in your barns, and in all that you put your hand to; and he will bless you in the land which Yahweh your God gives you.'),
  ('b7645a9d-3177-5e36-a6f4-627853796332', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 9, 9, 'Yahweh will establish you for a holy people to himself, as he has sworn to you; if you shall keep the commandments of Yahweh your God, and walk in his ways.'),
  ('064107ac-fa8d-5ae3-aff4-ab5e7bce90fa', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 10, 10, 'All the peoples of the earth shall see that you are called by the name of Yahweh; and they shall be afraid of you.'),
  ('058f6515-fd7b-5b7c-a005-ab522e5644ac', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 11, 11, 'Yahweh will make you plenteous for good, in the fruit of your body, and in the fruit of your livestock, and in the fruit of your ground, in the land which Yahweh swore to your fathers to give you.'),
  ('9038a03b-c236-5d6a-a828-435d59c10ebb', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 12, 12, 'Yahweh will open to you his good treasure in the sky, to give the rain of your land in its season, and to bless all the work of your hand: and you shall lend to many nations, and you shall not borrow.'),
  ('e7746582-2d16-5f78-a27e-01d87380cc2c', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 13, 13, 'Yahweh will make you the head, and not the tail; and you shall be above only, and you shall not be beneath; if you shall listen to the commandments of Yahweh your God, which I command you this day, to observe and to do [them],'),
  ('0343eeef-7e3b-5246-a953-89350b2d5b70', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 14, 14, 'and shall not turn aside from any of the words which I command you this day, to the right hand, or to the left, to go after other gods to serve them.'),
  ('f45ad5bb-54ee-5e0f-ab43-67cfcb94ed69', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 15, 15, 'But it shall come to pass, if you will not listen to the voice of Yahweh your God, to observe to do all his commandments and his statutes which I command you this day, that all these curses shall come on you, and overtake you.'),
  ('1db84774-c211-5c7b-a651-5f6680b609e9', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 16, 16, 'You shall be cursed in the city, and you shall be cursed in the field.'),
  ('542f5703-0192-54a9-a5af-a4fb461fa5d8', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 17, 17, 'Your basket and your kneading trough shall be cursed.'),
  ('a9d5d516-bae3-53a0-a366-f4866eba481d', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 18, 18, 'The fruit of your body, the fruit of your ground, the increase of your livestock, and the young of your flock shall be cursed.'),
  ('0bba79cf-ba15-5516-a24c-63c963315911', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 19, 19, 'You shall be cursed when you come in, and you shall be cursed when you go out.'),
  ('de2007e8-ac06-50fd-ae16-55de13d6ae84', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 20, 20, 'Yahweh will send on you cursing, confusion, and rebuke, in all that you put your hand to do, until you are destroyed, and until you perish quickly; because of the evil of your doings, by which you have forsaken me.'),
  ('bc46fed7-97bf-58bf-a2be-304196c01b99', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 21, 21, 'Yahweh will make the pestilence cling to you, until he has consumed you from off the land, where you go in to possess it.'),
  ('37308d9b-d05c-5d8d-a057-b350e629080c', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 22, 22, 'Yahweh will strike you with consumption, and with fever, and with inflammation, and with fiery heat, and with the sword, and with blight, and with mildew; and they shall pursue you until you perish.'),
  ('975de796-b316-5d0b-af44-d56b39ed9fdb', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 23, 23, 'Your sky that is over your head shall be brass, and the earth that is under you shall be iron.'),
  ('4e370089-bc59-5817-a589-1a07af7122c0', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 24, 24, 'Yahweh will make the rain of your land powder and dust: from the sky shall it come down on you, until you are destroyed.'),
  ('83331b21-19dd-5bbf-a1e4-f81b6ecd2cd6', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 25, 25, 'Yahweh will cause you to be struck before your enemies; you shall go out one way against them, and shall flee seven ways before them: and you shall be tossed back and forth among all the kingdoms of the earth.'),
  ('85e828cd-7a7e-52cc-a7ad-bf9b3ba7795c', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 26, 26, 'Your dead body shall be food to all birds of the sky, and to the animals of the earth; and there shall be none to frighten them away.'),
  ('825753c7-5a08-5c86-ae0c-6b3ebd1aa06b', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 27, 27, 'Yahweh will strike you with the boil of Egypt, and with the tumors, and with the scurvy, and with the itch, of which you can not be healed.'),
  ('0480350a-3a5d-517a-aaa5-37ef93b6a394', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 28, 28, 'Yahweh will strike you with madness, and with blindness, and with astonishment of heart;'),
  ('13cc04fa-2836-5d6f-a20f-ef7f606fc02e', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 29, 29, 'and you shall grope at noonday, as the blind gropes in darkness, and you shall not prosper in your ways: and you shall be only oppressed and robbed always, and there shall be none to save you.'),
  ('2163f79d-31cb-5171-abb4-b549913bfb47', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 30, 30, 'You shall betroth a wife, and another man shall lie with her: you shall build a house, and you shall not dwell therein: you shall plant a vineyard, and shall not use its fruit.'),
  ('e1a927d1-d671-59fd-ab0a-bacba4f3735e', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 31, 31, 'Your ox shall be slain before your eyes, and you shall not eat of it: your donkey shall be violently taken away from before your face, and shall not be restored to you: your sheep shall be given to your enemies, and you shall have none to save you.'),
  ('2b67a325-947d-51c1-a45d-7e94cf061e83', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 32, 32, 'Your sons and your daughters shall be given to another people; and your eyes shall look, and fail with longing for them all the day: and there shall be nothing in the power of your hand.'),
  ('af72f2e5-f92c-56fa-a0a4-3ad743f52796', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 33, 33, 'The fruit of your ground, and all your labors, shall a nation which you don''t know eat up; and you shall be only oppressed and crushed always;'),
  ('979a3ef0-dc75-534f-adaf-358ea1909d65', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 34, 34, 'so that you shall be mad for the sight of your eyes which you shall see.'),
  ('55063ce5-7bbd-5722-a657-677b5e395e70', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 35, 35, 'Yahweh will strike you in the knees, and in the legs, with a sore boil, of which you can not be healed, from the sole of your foot to the crown of your head.'),
  ('8a1c27be-0285-5772-a78a-e189a5308cda', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 36, 36, 'Yahweh will bring you, and your king whom you shall set over you, to a nation that you have not known, you nor your fathers; and there you shall serve other gods, wood and stone.'),
  ('727641d8-64fc-5140-aa30-afd57a6e1cf3', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 37, 37, 'You shall become an astonishment, a proverb, and a byword, among all the peoples where Yahweh shall lead you away.'),
  ('4fbfb517-6613-5338-a892-644876c70e2f', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 38, 38, 'You shall carry much seed out into the field, and shall gather little in; for the locust shall consume it.'),
  ('689e54b1-cffb-5e22-a966-40b12619db0f', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 39, 39, 'You shall plant vineyards and dress them, but you shall neither drink of the wine, nor gather [the grapes]; for the worm shall eat them.'),
  ('9f06d8e9-f8e2-52d0-ac23-8b5ec6b5e616', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 40, 40, 'You shall have olive trees throughout all your borders, but you shall not anoint yourself with the oil; for your olive shall cast [its fruit].'),
  ('6ee16299-f2cc-55e6-a757-4a0fa9f4e8b6', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 41, 41, 'You shall father sons and daughters, but they shall not be yours; for they shall go into captivity.'),
  ('c3aaaaff-fbae-58ee-a6ac-d5bf733dcd82', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 42, 42, 'All your trees and the fruit of your ground shall the locust possess.'),
  ('0f180922-9491-5cfb-a1b7-ebd8dbafdb57', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 43, 43, 'The foreigner who is in the midst of you shall mount up above you higher and higher; and you shall come down lower and lower.'),
  ('e82b8499-079f-51f3-a010-26998bf16080', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 44, 44, 'He shall lend to you, and you shall not lend to him: he shall be the head, and you shall be the tail.'),
  ('22f82753-867f-5e0e-a111-f6f4fff87c05', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 45, 45, 'All these curses shall come on you, and shall pursue you, and overtake you, until you are destroyed; because you didn''t listen to the voice of Yahweh your God, to keep his commandments and his statutes which he commanded you:'),
  ('f736ef9c-6272-5618-afae-9f647b881aac', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 46, 46, 'and they shall be on you for a sign and for a wonder, and on your seed forever.'),
  ('51e4e5d2-66a4-5165-adb7-be5220199a39', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 47, 47, 'Because you didn''t serve Yahweh your God with joyfulness, and with gladness of heart, by reason of the abundance of all things;'),
  ('0e0a8925-026a-5c53-a520-b7abab01bab6', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 48, 48, 'therefore you shall serve your enemies whom Yahweh shall send against you, in hunger, and in thirst, and in nakedness, and in want of all things: and he shall put a yoke of iron on your neck, until he has destroyed you.'),
  ('14b3837e-fd4a-5662-a65b-f3f204f97079', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 49, 49, 'Yahweh will bring a nation against you from far, from the end of the earth, as the eagle flies; a nation whose language you shall not understand;'),
  ('bc12c22d-5330-5853-ae2e-b663bad40b4b', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 50, 50, 'a nation of fierce facial expressions, that shall not respect the person of the old, nor show favor to the young,'),
  ('4557803e-7444-5c3a-ad44-768f3061178a', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 51, 51, 'and shall eat the fruit of your livestock, and the fruit of your ground, until you are destroyed; that also shall not leave you grain, new wine, or oil, the increase of your livestock, or the young of your flock, until they have caused you to perish.'),
  ('099b1e36-8092-5eb3-acd8-1bf347ab1b3d', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 52, 52, 'They shall besiege you in all your gates, until your high and fortified walls come down, in which you trusted, throughout all your land; and they shall besiege you in all your gates throughout all your land, which Yahweh your God has given you.'),
  ('edf38488-068f-53c4-a562-565d7dffa5b8', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 53, 53, 'You shall eat the fruit of your own body, the flesh of your sons and of your daughters, whom Yahweh your God has given you, in the siege and in the distress with which your enemies shall distress you.'),
  ('84105fa7-5024-57f6-afb6-468c192e50bb', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 54, 54, 'The man who is tender among you, and very delicate, his eye shall be evil toward his brother, and toward the wife of his bosom, and toward the remnant of his children whom he has remaining;'),
  ('a42ec166-5d70-5cd7-a2e0-67d2261992e3', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 55, 55, 'so that he will not give to any of them of the flesh of his children whom he shall eat, because he has nothing left him, in the siege and in the distress with which your enemy shall distress you in all your gates.'),
  ('adf3c45a-ef00-5b14-a521-d4b3e1ed7e7f', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 56, 56, 'The tender and delicate woman among you, who would not adventure to set the sole of her foot on the ground for delicateness and tenderness, her eye shall be evil toward the husband of her bosom, and toward her son, and toward her daughter,'),
  ('ad64984f-cd64-5d5d-af5a-756934db6793', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 57, 57, 'and toward her young one who comes out from between her feet, and toward her children whom she shall bear; for she shall eat them for want of all things secretly, in the siege and in the distress with which your enemy shall distress you in your gates.'),
  ('a30b3852-d1b0-5327-a68f-6de025b4f5ce', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 58, 58, 'If you will not observe to do all the words of this law that are written in this book, that you may fear this glorious and fearful name, YAHWEH YOUR GOD;'),
  ('e913cb39-4789-500d-af45-c4111b5f6115', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 59, 59, 'then Yahweh will make your plagues wonderful, and the plagues of your seed, even great plagues, and of long continuance, and severe sicknesses, and of long continuance.'),
  ('cb43d3f2-a6cc-53ce-ab9a-8027122f16b2', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 60, 60, 'He will bring on you again all the diseases of Egypt, which you were afraid of; and they shall cling to you.'),
  ('1151821e-b41f-5650-a8d8-c48c303144be', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 61, 61, 'Also every sickness, and every plague, which is not written in the book of this law, Yahweh will bring them on you, until you are destroyed.'),
  ('a64d5d30-1406-5247-af07-a16a484ee0e7', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 62, 62, 'You shall be left few in number, whereas you were as the stars of the sky for multitude; because you didn''t listen to the voice of Yahweh your God.'),
  ('fab6036c-411f-561a-a044-7074d5e401e1', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 63, 63, 'It shall happen that as Yahweh rejoiced over you to do you good, and to multiply you, so Yahweh will rejoice over you to cause you to perish, and to destroy you; and you shall be plucked from off the land where you go in to possess it.'),
  ('7c8008e0-c39a-5422-afa9-b85b89238404', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 64, 64, 'Yahweh will scatter you among all peoples, from the one end of the earth even to the other end of the earth; and there you shall serve other gods, which you have not known, you nor your fathers, even wood and stone.'),
  ('3c00bbf9-f297-51eb-a48e-971c98f299a4', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 65, 65, 'Among these nations you shall find no ease, and there shall be no rest for the sole of your foot: but Yahweh will give you there a trembling heart, and failing of eyes, and pining of soul;'),
  ('22bb6634-afc6-5294-ae38-845fafe084aa', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 66, 66, 'and your life shall hang in doubt before you; and you shall fear night and day, and shall have no assurance of your life.'),
  ('2f2579f8-6b95-53f2-a54e-3e2956996269', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 67, 67, 'In the morning you shall say, "I wish it were evening!" and at evening you shall say, "I wish it were morning!" for the fear of your heart which you shall fear, and for the sight of your eyes which you shall see.'),
  ('bba84661-7394-5332-ab54-65fcd5383ffb', 'c894226c-641e-59ca-aa36-158422edef4c', NULL, 68, 68, 'Yahweh will bring you into Egypt again with ships, by the way of which I said to you, You shall see it no more again: and there you shall sell yourselves to your enemies for bondservants and for bondmaids, and no man shall buy you.'),
  ('88d3b5ee-7eb5-5955-a986-e78950b81ea0', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 1, 1, 'These are the words of the covenant which Yahweh commanded Moses to make with the children of Israel in the land of Moab, besides the covenant which he made with them in Horeb.'),
  ('9cc7685f-630e-5cae-a672-18fbbd844282', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 2, 2, 'Moses called to all Israel, and said to them, You have seen all that Yahweh did before your eyes in the land of Egypt to Pharaoh, and to all his servants, and to all his land;'),
  ('c001690a-9574-5325-a9f4-a3a808f148a6', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 3, 3, 'the great trials which your eyes saw, the signs, and those great wonders:'),
  ('76dd5e0f-3f96-5c03-aa76-404a44c4b066', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 4, 4, 'but Yahweh has not given you a heart to know, and eyes to see, and ears to hear, to this day.'),
  ('eed6420b-7fad-59cc-a6b4-8f64c395e8a0', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 5, 5, 'I have led you forty years in the wilderness: your clothes have not grown old on you, and your shoes have not grown old on your feet.'),
  ('1ea9d1f1-4ae8-5257-a9a8-0af649a7abaf', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 6, 6, 'You have not eaten bread, neither have you drunk wine or strong drink; that you may know that I am Yahweh your God.'),
  ('1e97e2e2-33a3-52e5-a616-1f01ef247409', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 7, 7, 'When you came to this place, Sihon the king of Heshbon, and Og the king of Bashan, came out against us to battle, and we struck them:'),
  ('434cf449-89f9-50c8-a236-94a78349f55c', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 8, 8, 'and we took their land, and gave it for an inheritance to the Reubenites, and to the Gadites, and to the half-tribe of the Manassites.'),
  ('8c1ba556-0ff7-5252-a882-c4bbcca115f5', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 9, 9, 'Keep therefore the words of this covenant, and do them, that you may prosper in all that you do.'),
  ('13b43d44-84d8-51ac-af73-784779fa3129', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 10, 10, 'You stand this day all of you before Yahweh your God; your heads, your tribes, your elders, and your officers, even all the men of Israel,'),
  ('d323dd8c-db0e-5571-a3a9-9a555ed1f4c6', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 11, 11, 'your little ones, your wives, and your foreigner who is in the midst of your camps, from the one who cuts your wood to the one who draws your water;'),
  ('774df768-cb51-50ee-a04a-439c4caf6513', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 12, 12, 'that you may enter into the covenant of Yahweh your God, and into his oath, which Yahweh your God makes with you this day;'),
  ('186a0df6-cf97-5ff7-a268-20cf2bd118b3', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 13, 13, 'that he may establish you this day to himself for a people, and that he may be to you a God, as he spoke to you, and as he swore to your fathers, to Abraham, to Isaac, and to Jacob.'),
  ('6d790bd5-0afe-54f2-af40-f0f732a64d55', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 14, 14, 'Neither with you only do I make this covenant and this oath,'),
  ('b3bbd38f-bd4c-5715-a34a-acdda999ff69', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 15, 15, 'but with him who stands here with us this day before Yahweh our God, and also with him who is not here with us this day'),
  ('c5383731-af6f-5785-a208-3a063685a0cb', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 16, 16, '(for you know how we lived in the land of Egypt, and how we came through the midst of the nations through which you passed;'),
  ('84d5a358-6f69-554e-a66e-7b73dfe3d1b5', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 17, 17, 'and you have seen their abominations, and their idols, wood and stone, silver and gold, which were among them);'),
  ('a9cdeffe-778d-5736-a71c-414c421c4e60', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 18, 18, 'lest there should be among you man, or woman, or family, or tribe, whose heart turns away this day from Yahweh our God, to go to serve the gods of those nations; lest there should be among you a root that bears gall and wormwood;'),
  ('4ad0eafa-f8c9-52c4-abf1-d08a9858f4f5', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 19, 19, 'and it happen, when he hears the words of this curse, that he bless himself in his heart, saying, "I shall have peace, though I walk in the stubbornness of my heart, to destroy the moist with the dry."'),
  ('9254c65b-6894-57b3-a550-8a55a914bf51', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 20, 20, 'Yahweh will not pardon him, but then the anger of Yahweh and his jealousy will smoke against that man, and all the curse that is written in this book shall lie on him, and Yahweh will blot out his name from under the sky.'),
  ('872108e8-1b75-512d-a2ed-8685006d6308', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 21, 21, 'Yahweh will set him apart to evil out of all the tribes of Israel, according to all the curses of the covenant that is written in this book of the law.'),
  ('fe422425-106b-5db4-abb0-1d4c72dd6755', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 22, 22, 'The generation to come, your children who shall rise up after you, and the foreigner who shall come from a far land, shall say, when they see the plagues of that land, and the sicknesses with which Yahweh has made it sick;'),
  ('2557e9e8-e551-50de-aff2-2dcec4473a73', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 23, 23, '[and that] the whole land of it is sulfur, and salt, [and] a burning, [that] it is not sown, nor bears, nor any grass grows therein, like the overthrow of Sodom and Gomorrah, Admah and Zeboiim, which Yahweh overthrew in his anger, and in his wrath:'),
  ('5301cb39-f9ce-5d1d-ad93-e7983d7236b7', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 24, 24, 'even all the nations shall say, "Why has Yahweh done thus to this land? What does the heat of this great anger mean?"'),
  ('e41250b8-fd16-5818-a750-8e73b1bb9071', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 25, 25, 'Then men shall say, "Because they forsook the covenant of Yahweh, the God of their fathers, which he made with them when he brought them forth out of the land of Egypt,'),
  ('6b95279a-f3fd-5387-ac06-0d915856f288', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 26, 26, 'and went and served other gods, and worshiped them, gods that they didn''t know, and that he had not given to them:'),
  ('a8781fd3-7830-5cb7-a35e-054296ff0fe4', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 27, 27, 'therefore the anger of Yahweh was kindled against this land, to bring on it all the curse that is written in this book;'),
  ('ba88ddca-a186-5df9-a4c0-de34cbb7ede2', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 28, 28, 'and Yahweh rooted them out of their land in anger, and in wrath, and in great indignation, and cast them into another land, as at this day."'),
  ('e358a0c5-d6b8-52a7-a13d-aec09079f734', '31e5d979-3a9f-5bc3-a2f1-67bae70d734b', NULL, 29, 29, 'The secret things belong to Yahweh our God; but the things that are revealed belong to us and to our children forever, that we may do all the words of this law.'),
  ('5ca66f09-1fe7-5a16-a40b-2f57dd489fdb', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 1, 1, 'It shall happen, when all these things have come on you, the blessing and the curse, which I have set before you, and you shall call them to mind among all the nations, where Yahweh your God has driven you,'),
  ('cfa9642a-691a-5388-adc6-b04e5a86b7ce', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 2, 2, 'and shall return to Yahweh your God, and shall obey his voice according to all that I command you this day, you and your children, with all your heart, and with all your soul;'),
  ('1a08a6d3-2506-5283-a1e6-d9aca87fd260', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 3, 3, 'that then Yahweh your God will turn your captivity, and have compassion on you, and will return and gather you from all the peoples, where Yahweh your God has scattered you.'),
  ('e394804c-d6b4-5ac7-a7a2-f49d83eb26b3', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 4, 4, 'If [any of] your outcasts are in the uttermost parts of the heavens, from there will Yahweh your God gather you, and from there he will bring you back:'),
  ('f3b28fba-6c32-58de-a601-ecdc83ff1133', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 5, 5, 'and Yahweh your God will bring you into the land which your fathers possessed, and you shall possess it; and he will do you good, and multiply you above your fathers.'),
  ('93e208c9-69e5-571c-a03b-be14da70810c', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 6, 6, 'Yahweh your God will circumcise your heart, and the heart of your seed, to love Yahweh your God with all your heart, and with all your soul, that you may live.'),
  ('626da187-6a5f-5c5a-aef9-634895e85dd1', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 7, 7, 'Yahweh your God will put all these curses on your enemies, and on those who hate you, who persecuted you.'),
  ('e58de410-3145-59f0-a099-641eeb9a64c1', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 8, 8, 'You shall return and obey the voice of Yahweh, and do all his commandments which I command you this day.'),
  ('00751190-c316-508d-ac1a-099a608c83b2', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 9, 9, 'Yahweh your God will make you plenteous in all the work of your hand, in the fruit of your body, and in the fruit of your livestock, and in the fruit of your ground, for good: for Yahweh will again rejoice over you for good, as he rejoiced over your fathers;'),
  ('80ed8f62-b799-522f-a096-58586751a256', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 10, 10, 'if you shall obey the voice of Yahweh your God, to keep his commandments and his statutes which are written in this book of the law; if you turn to Yahweh your God with all your heart, and with all your soul.'),
  ('4ba06bd5-2840-52b2-ae56-dce9bc91b54a', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 11, 11, 'For this commandment which I command you this day, it is not too hard for you, neither is it far off.'),
  ('8cb693c6-7c40-5cf8-a7c8-dee3655375a1', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 12, 12, 'It is not in heaven, that you should say, "Who shall go up for us to heaven, and bring it to us, and make us to hear it, that we may do it?"'),
  ('c6820984-c335-5948-ad4b-f299c4c330bc', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 13, 13, 'Neither is it beyond the sea, that you should say, "Who shall go over the sea for us, and bring it to us, and make us to hear it, that we may do it?"'),
  ('9b7b2e89-4ffd-5ad9-ab8e-d8a817aed27e', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 14, 14, 'But the word is very near to you, in your mouth, and in your heart, that you may do it.'),
  ('3dc5b4a3-b021-5988-aeed-0e297fd02bff', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 15, 15, 'Behold, I have set before you this day life and good, and death and evil;'),
  ('94c04c3a-4ee8-5cf5-a51d-d1b41b5dcfcd', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 16, 16, 'in that I command you this day to love Yahweh your God, to walk in his ways, and to keep his commandments and his statutes and his ordinances, that you may live and multiply, and that Yahweh your God may bless you in the land where you go in to possess it.'),
  ('d6224eab-fc6b-5aff-a289-6d8d567881dc', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 17, 17, 'But if your heart turns away, and you will not hear, but shall be drawn away, and worship other gods, and serve them;'),
  ('cf5f1549-222a-52d2-aa22-137188ce4c36', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 18, 18, 'I denounce to you this day, that you shall surely perish; you shall not prolong your days in the land, where you pass over the Jordan to go in to possess it.'),
  ('738eeb06-7839-5c6e-affc-021f7388389c', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 19, 19, 'I call heaven and earth to witness against you this day, that I have set before you life and death, the blessing and the curse: therefore choose life, that you may live, you and your seed;'),
  ('83952f6a-80a1-585e-ae95-abfe02be7204', 'a13946ce-6cf8-559d-a411-6145ce976641', NULL, 20, 20, 'to love Yahweh your God, to obey his voice, and to cling to him; for he is your life, and the length of your days; that you may dwell in the land which Yahweh swore to your fathers, to Abraham, to Isaac, and to Jacob, to give them.'),
  ('2a95f88b-f44e-51cf-a710-31a2d93ab8ff', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 1, 1, 'Moses went and spoke these words to all Israel.'),
  ('deb3ebff-b2ad-5a9c-a169-3cc2c04d2f30', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 2, 2, 'He said to them, "I am one hundred twenty years old this day; I can no more go out and come in: and Yahweh has said to me, ''You shall not go over this Jordan.'''),
  ('cc72bd7e-53de-5f8f-acb4-c2200783f017', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 3, 3, 'Yahweh your God, he will go over before you; he will destroy these nations from before you, and you shall dispossess them: [and] Joshua, he shall go over before you, as Yahweh has spoken.'),
  ('e6abac06-fb81-5021-a6c2-fc36343ff9f3', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 4, 4, 'Yahweh will do to them as he did to Sihon and to Og, the kings of the Amorites, and to their land; whom he destroyed.'),
  ('39d65f84-398b-5536-ac02-bf49781978d6', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 5, 5, 'Yahweh will deliver them up before you, and you shall do to them according to all the commandment which I have commanded you.'),
  ('a5a3f8d1-fa8c-5c2c-a87d-e5528b81cf81', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 6, 6, 'Be strong and courageous, don''t be afraid, nor be scared of them: for Yahweh your God, he it is who does go with you; he will not fail you, nor forsake you."'),
  ('a501d4af-daa3-542e-a524-95d223cc90f7', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 7, 7, 'Moses called to Joshua, and said to him in the sight of all Israel, "Be strong and courageous: for you shall go with this people into the land which Yahweh has sworn to their fathers to give them; and you shall cause them to inherit it.'),
  ('e7e5818e-65aa-5426-a505-781d9cea6e2a', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 8, 8, 'Yahweh, he it is who does go before you; he will be with you, he will not fail you, neither forsake you: don''t be afraid, neither be dismayed."'),
  ('ec7bcfdb-a747-5f00-a28e-3a89c0460621', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 9, 9, 'Moses wrote this law, and delivered it to the priests the sons of Levi, who bore the ark of the covenant of Yahweh, and to all the elders of Israel.'),
  ('812547f3-1bff-54c9-ad90-dcfc74ce426c', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 10, 10, 'Moses commanded them, saying, "At the end of [every] seven years, in the set time of the year of release, in the feast of tents,'),
  ('fced0b74-c1b8-50e6-acbf-91ebf47692e4', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 11, 11, 'when all Israel is come to appear before Yahweh your God in the place which he shall choose, you shall read this law before all Israel in their hearing.'),
  ('8cabc2e0-69d0-500c-a5de-4cf682065d0c', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 12, 12, 'Assemble the people, the men and the women and the little ones, and your foreigner who is within your gates, that they may hear, and that they may learn, and fear Yahweh your God, and observe to do all the words of this law;'),
  ('277608e7-1ae7-5c8a-a756-ceeda521ee27', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 13, 13, 'and that their children, who have not known, may hear, and learn to fear Yahweh your God, as long as you live in the land where you go over the Jordan to possess it."'),
  ('e9290e11-e859-5dae-af12-b28969ca9eb5', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 14, 14, 'Yahweh said to Moses, "Behold, your days approach that you must die: call Joshua, and present yourselves in the Tent of Meeting, that I may commission him." Moses and Joshua went, and presented themselves in the Tent of Meeting.'),
  ('634c2c93-6088-5f9f-a5c8-7a35f45335a9', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 15, 15, 'Yahweh appeared in the Tent in a pillar of cloud: and the pillar of cloud stood over the door of the Tent.'),
  ('ac2fc37d-8e5f-5765-a5be-baf3961f73e0', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 16, 16, 'Yahweh said to Moses, "Behold, you shall sleep with your fathers; and this people will rise up, and play the prostitute after the strange gods of the land, where they go to be among them, and will forsake me, and break my covenant which I have made with them.'),
  ('e60a4402-5289-56af-a9c9-6c8c681f217a', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 17, 17, 'Then my anger shall be kindled against them in that day, and I will forsake them, and I will hide my face from them, and they shall be devoured, and many evils and troubles shall come on them; so that they will say in that day, ''Haven''t these evils come on us because our God is not among us?'''),
  ('1077b1d2-3acc-5741-ab86-cba658c22f93', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 18, 18, 'I will surely hide my face in that day for all the evil which they shall have worked, in that they are turned to other gods.'),
  ('4be434ae-eba3-5e1d-a52d-03253586d935', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 19, 19, '"Now therefore write this song for yourselves, and teach it to the children of Israel: put it in their mouths, that this song may be a witness for me against the children of Israel.'),
  ('10ccaec6-7aae-508d-acf5-a5dad6332d36', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 20, 20, 'For when I shall have brought them into the land which I swore to their fathers, flowing with milk and honey, and they shall have eaten and filled themselves, and grown fat; then will they turn to other gods, and serve them, and despise me, and break my covenant.'),
  ('cac6903d-7a5f-53e1-a8ff-8617552b6582', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 21, 21, 'It shall happen, when many evils and troubles are come on them, that this song shall testify before them as a witness; for it shall not be forgotten out of the mouths of their seed: for I know their imagination which they frame this day, before I have brought them into the land which I swore."'),
  ('02e88d51-efd3-5445-a379-f4dc3538135f', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 22, 22, 'So Moses wrote this song the same day, and taught it the children of Israel.'),
  ('5e26f485-09e6-5750-ac45-bc214ed67bc3', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 23, 23, 'He commissioned Joshua the son of Nun, and said, "Be strong and courageous; for you shall bring the children of Israel into the land which I swore to them: and I will be with you."'),
  ('76e07bf2-73e8-5d81-a053-ecb7e0c6ce48', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 24, 24, 'It happened, when Moses had made an end of writing the words of this law in a book, until they were finished,'),
  ('ba598ac0-2c1f-5df0-ab1b-cfd383de64fa', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 25, 25, 'that Moses commanded the Levites, who bore the ark of the covenant of Yahweh, saying,'),
  ('fc812b87-d060-50db-a587-ec0c23841ac8', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 26, 26, '"Take this book of the law, and put it by the side of the ark of the covenant of Yahweh your God, that it may be there for a witness against you.'),
  ('fd617a9f-55fa-5aa0-a16f-20b91a84c547', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 27, 27, 'For I know your rebellion, and your stiff neck: behold, while I am yet alive with you this day, you have been rebellious against Yahweh; and how much more after my death?'),
  ('634409e2-403b-5373-a8c2-07e90be027bc', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 28, 28, 'Assemble to me all the elders of your tribes, and your officers, that I may speak these words in their ears, and call heaven and earth to witness against them.'),
  ('26c298a2-0267-5b4d-a5aa-7c5a55b42e13', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 29, 29, 'For I know that after my death you will utterly corrupt yourselves, and turn aside from the way which I have commanded you; and evil will happen to you in the latter days; because you will do that which is evil in the sight of Yahweh, to provoke him to anger through the work of your hands."'),
  ('1ef88ed3-586f-52b7-a3a2-e39c4113854c', 'a616acdd-cac5-5856-ada3-7e5978147ef6', NULL, 30, 30, 'Moses spoke in the ears of all the assembly of Israel the words of this song, until they were finished.'),
  ('5229dee0-bc19-5e8b-afa2-e51b09705526', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 1, 1, 'Give ear, you heavens, and I will speak. Let the earth hear the words of my mouth.'),
  ('13a638c6-e3b4-5990-ad10-d3c3867918ac', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 2, 2, 'My doctrine shall drop as the rain. My speech shall condense as the dew, as the small rain on the tender grass, as the showers on the herb.'),
  ('a15bd292-cf58-5cb8-afbb-36416c45ca6b', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 3, 3, 'For I will proclaim the name of Yahweh. Ascribe greatness to our God!'),
  ('a46d801b-1b74-5476-a609-9e2f17290b1c', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 4, 4, 'The Rock, his work is perfect, for all his ways are justice: a God of faithfulness and without iniquity, just and right is he.'),
  ('999901e5-a347-513d-ae4e-6800fccfe622', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 5, 5, 'They have dealt corruptly with him, [they are] not his children, [it is] their blemish. [They are] a perverse and crooked generation.'),
  ('82d18596-5e50-5d6b-a7d6-5aa65b6da282', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 6, 6, 'Do you thus requite Yahweh, foolish people and unwise? Isn''t he your father who has bought you? He has made you, and established you.'),
  ('fc43de72-9df9-59ab-a24d-675cce85d684', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 7, 7, 'Remember the days of old. Consider the years of many generations. Ask your father, and he will show you; your elders, and they will tell you.'),
  ('e7649c08-dadf-5988-a0a7-efa60cc52639', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 8, 8, 'When the Most High gave to the nations their inheritance, when he separated the children of men, he set the bounds of the peoples according to the number of the children of Israel.'),
  ('a028effb-a1cc-52b9-ae9c-e4a6034e1dec', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 9, 9, 'For Yahweh''s portion is his people. Jacob is the lot of his inheritance.'),
  ('b54e06c2-924d-5c87-a442-dedfd2898922', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 10, 10, 'He found him in a desert land, in the waste howling wilderness. He surrounded him. He cared for him. He kept him as the apple of his eye.'),
  ('96557c34-4b28-509f-a3cf-abcc051d86f3', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 11, 11, 'As an eagle that stirs up her nest, that flutters over her young, he spread abroad his wings, he took them, he bore them on his feathers.'),
  ('cf5d621c-3aec-5ea7-ae5d-1a22dc739794', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 12, 12, 'Yahweh alone led him. There was no foreign god with him.'),
  ('2e407793-5ae0-5c9d-a209-5b5b15646544', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 13, 13, 'He made him ride on the high places of the earth. He ate the increase of the field. He caused him to suck honey out of the rock, oil out of the flinty rock;'),
  ('9b9e986e-7d91-551b-a7a5-9f77d101ce27', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 14, 14, 'Butter of the herd, and milk of the flock, with fat of lambs, rams of the breed of Bashan, and goats, with the finest of the wheat. Of the blood of the grape you drank wine.'),
  ('8cab4021-d24a-519e-aeba-fae2f4235c27', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 15, 15, 'But Jeshurun grew fat, and kicked. You have grown fat. You have grown thick. You have become sleek. Then he forsook God who made him, and lightly esteemed the Rock of his salvation.'),
  ('5d0298b5-49f5-5bc8-a29d-76baf1daa017', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 16, 16, 'They moved him to jealousy with strange [gods]. They provoked him to anger with abominations.'),
  ('962ad340-5afb-50ca-a119-476a64b41fa2', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 17, 17, 'They sacrificed to demons, [which were] no God, to gods that they didn''t know, to new [gods] that came up of late, which your fathers didn''t dread.'),
  ('dfe5e1e1-50af-5d0a-af31-ee298ae75eee', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 18, 18, 'Of the Rock who became your father, you are unmindful, and have forgotten God who gave you birth.'),
  ('bf8dad08-7c30-5b2d-a82e-d0c98013a267', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 19, 19, 'Yahweh saw [it], and abhorred [them], because of the provocation of his sons and his daughters.'),
  ('47616d80-487e-54e0-a76d-9347222b8b31', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 20, 20, 'He said, "I will hide my face from them. I will see what their end shall be; for they are a very perverse generation, children in whom is no faithfulness.'),
  ('5d98f81c-448f-5c09-ad1c-2b4c5d3f7e82', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 21, 21, 'They have moved me to jealousy with that which is not God. They have provoked me to anger with their vanities. I will move them to jealousy with those who are not a people. I will provoke them to anger with a foolish nation.'),
  ('7c6457e9-f2bb-548c-ade1-58c9f1553527', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 22, 22, 'For a fire is kindled in my anger, Burns to the lowest Sheol, Devours the earth with its increase, and sets the foundations of the mountains on fire.'),
  ('c0b92bc2-9fb4-5c1c-a4f1-15dc7ec586f5', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 23, 23, '"I will heap evils on them. I will spend my arrows on them.'),
  ('3f63bb36-a39f-504d-aebe-32d4b80bc015', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 24, 24, '[They shall be] wasted with hunger, and devoured with burning heat and bitter destruction. I will send the teeth of animals on them, With the poison of crawling things of the dust.'),
  ('580b959d-1bad-51d9-a860-6d7345a8f876', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 25, 25, 'Outside the sword shall bereave, and in the rooms, terror; on both young man and virgin, The nursing infant with the gray-haired man.'),
  ('2f874f15-d84c-5287-a84b-ca4f96b0b9a9', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 26, 26, 'I said, I would scatter them afar. I would make the memory of them to cease from among men;'),
  ('7bcbe0b2-b8f7-596a-a213-0b4b53988eb1', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 27, 27, 'were it not that I feared the provocation of the enemy, lest their adversaries should judge wrongly, lest they should say, ''Our hand is exalted, Yahweh has not done all this.''"'),
  ('fe5e7f3b-39d4-57b7-a113-a032254cfb43', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 28, 28, 'For they are a nation void of counsel. There is no understanding in them.'),
  ('039b7276-3040-57e8-a919-8dbb6c13daf9', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 29, 29, 'Oh that they were wise, that they understood this, that they would consider their latter end!'),
  ('48a870bd-c9e8-592a-a516-1d4ee7072a11', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 30, 30, 'How could one chase a thousand, and two put ten thousand to flight, unless their Rock had sold them, and Yahweh had delivered them up?'),
  ('bd773026-3c68-5261-a9c6-dbf40ccb3c86', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 31, 31, 'For their rock is not as our Rock, even our enemies themselves being judges.'),
  ('8f77d8d2-eb2c-5858-a6e4-a8e43f40c9ee', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 32, 32, 'For their vine is of the vine of Sodom, of the fields of Gomorrah. Their grapes are grapes of gall, Their clusters are bitter.'),
  ('b0587f87-97c8-5ef9-af26-8583155ad71c', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 33, 33, 'Their wine is the poison of serpents, The cruel venom of asps.'),
  ('717f46a6-82c5-52ae-a7d6-88178e28aa61', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 34, 34, '"Isn''t this laid up in store with me, sealed up among my treasures?'),
  ('ed09b953-a145-59ef-af3b-199368e4a1a8', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 35, 35, 'Vengeance is mine, and recompense, at the time when their foot slides; for the day of their calamity is at hand. The things that are to come on them shall make haste."'),
  ('4520b1ef-cb4a-5b89-a9ec-7482cc4f6c7c', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 36, 36, 'For Yahweh will judge his people, and have compassion on his servants, when he sees that [their] power is gone, There is none [remaining], shut up or left at large.'),
  ('5696d5ca-7487-5036-a01a-f66406bf19a1', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 37, 37, 'He will say, "Where are their gods, The rock in which they took refuge;'),
  ('6d117163-ae07-5665-a11c-17dae7fd00cc', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 38, 38, 'Which ate the fat of their sacrifices, And drank the wine of their drink offering? Let them rise up and help you! Let them be your protection.'),
  ('15cbd887-d085-5fee-a988-933eebe446cd', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 39, 39, '"See now that I, even I, am he, There is no god with me. I kill, and I make alive. I wound, and I heal. There is no one who can deliver out of my hand.'),
  ('1976975b-7063-5819-a7bd-1c1d5ef3d5f8', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 40, 40, 'For I lift up my hand to heaven, And say, As I live forever,'),
  ('69b971b2-5b2e-5ac3-ae66-6a943ae1a27e', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 41, 41, 'if I whet my glittering sword, My hand take hold on judgment; I will render vengeance to my adversaries, and will recompense those who hate me.'),
  ('ffe8ac16-1bae-5ea6-a464-d5f522cf1be8', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 42, 42, 'I will make my arrows drunk with blood. My sword shall devour flesh with the blood of the slain and the captives, from the head of the leaders of the enemy."'),
  ('4646f50c-2df2-5245-a2a6-17c191cb0214', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 43, 43, 'Rejoice, you nations, [with] his people, for he will avenge the blood of his servants. He will render vengeance to his adversaries, And will make expiation for his land, for his people.'),
  ('70d89f97-9125-5506-a9e8-58417239f935', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 44, 44, 'Moses came and spoke all the words of this song in the ears of the people, he and Joshua the son of Nun.'),
  ('a0f51ca4-f7e2-5f1e-adec-55508832d316', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 45, 45, 'Moses made an end of speaking all these words to all Israel;'),
  ('744f2f1c-2f49-5a3f-adf6-6e9071b019f5', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 46, 46, 'He said to them, "Set your heart to all the words which I testify to you this day, which you shall command your children to observe to do, [even] all the words of this law.'),
  ('f9f2651d-2da0-5240-acf7-da0e07def146', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 47, 47, 'For it is no vain thing for you; because it is your life, and through this thing you shall prolong your days in the land, where you go over the Jordan to possess it."'),
  ('c2fcca49-e5cf-5186-a732-3c290b026aba', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 48, 48, 'Yahweh spoke to Moses that same day, saying,'),
  ('c978b4b1-342c-5d8b-a452-deda24147e70', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 49, 49, '"Go up into this mountain of Abarim, to Mount Nebo, which is in the land of Moab, that is over against Jericho; and see the land of Canaan, which I give to the children of Israel for a possession;'),
  ('cf35732a-0e08-5085-a783-f5cf28cf43b1', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 50, 50, 'and die on the mountain where you go up, and be gathered to your people, as Aaron your brother died on Mount Hor, and was gathered to his people:'),
  ('c78659f1-5b53-5fcd-ae2e-880ca8e79337', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 51, 51, 'because you trespassed against me in the midst of the children of Israel at the waters of Meribah of Kadesh, in the wilderness of Zin; because you didn''t sanctify me in the midst of the children of Israel.'),
  ('a67d987f-768b-5afb-a589-4a09dab43100', 'de5475d4-8d9f-55ca-a939-6f22b4ef51c9', NULL, 52, 52, 'For you shall see the land before you; but you shall not go there into the land which I give the children of Israel."'),
  ('a027ea0f-3dfd-544e-aab3-74c5bf02dfed', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 1, 1, 'This is the blessing, with which Moses the man of God blessed the children of Israel before his death.'),
  ('3390d9df-4095-56cd-a65a-4d885c3fa439', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 2, 2, 'He said, "Yahweh came from Sinai, And rose from Seir to them. He shone forth from Mount Paran. He came from the ten thousands of holy ones. At his right hand was a fiery law for them.'),
  ('d4d0f428-da3b-59eb-a21b-e3ee5c5e736c', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 3, 3, 'Yes, he loves the people. All his saints are in your hand. They sat down at your feet; [Everyone] shall receive of your words.'),
  ('6bdc1eec-b6aa-51f9-aacf-9e71ff9709f2', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 4, 4, 'Moses commanded us a law, An inheritance for the assembly of Jacob.'),
  ('25556725-169e-5dd7-a7d9-20ca172499b8', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 5, 5, 'He was king in Jeshurun, When the heads of the people were gathered, All the tribes of Israel together.'),
  ('b54e09a1-baed-5354-a3b8-5ccc7cc5f811', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 6, 6, '"Let Reuben live, and not die; Nor let his men be few."'),
  ('a4f1dbfd-0baf-5d03-a5f7-e0fedf462ad8', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 7, 7, 'This is [the blessing] of Judah: and he said, "Hear, Yahweh, the voice of Judah. Bring him in to his people. With his hands he contended for himself. You shall be a help against his adversaries."'),
  ('c0880b8d-d96e-5d2a-a088-3e6ec26fcb94', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 8, 8, 'Of Levi he said, "Your Thummim and your Urim are with your godly one, whom you proved at Massah, with whom you strove at the waters of Meribah;'),
  ('3eb92b40-ef79-5bbb-a1b1-7d23fe8342a1', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 9, 9, 'who said of his father, and of his mother, ''I have not seen him;'' Neither did he acknowledge his brothers, Nor did he know his own children: For they have observed your word, and keep your covenant.'),
  ('20b9803f-22c1-50a2-a248-fde53cb85eb5', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 10, 10, 'They shall teach Jacob your ordinances, and Israel your law. They shall put incense before you, and whole burnt offering on your altar.'),
  ('f498675d-0839-5d1d-a74a-e207bf5a5354', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 11, 11, 'Yahweh, bless his substance. Accept the work of his hands. Strike through the hips of those who rise up against him, of those who hate him, that they not rise again."'),
  ('ac4cb790-288e-5e29-a9c0-171b06976756', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 12, 12, 'Of Benjamin he said, "The beloved of Yahweh shall dwell in safety by him. He covers him all the day long. He dwells between his shoulders."'),
  ('3135d5e3-0cef-5c51-a244-af1c54beaaba', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 13, 13, 'Of Joseph he said, "His land is blessed by Yahweh, for the precious things of the heavens, for the dew, for the deep that couches beneath,'),
  ('f7f1fb0d-5db2-5eb4-a286-10767c6adfbd', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 14, 14, 'for the precious things of the fruits of the sun, for the precious things of the growth of the moons,'),
  ('0b67a334-e9e5-5220-a9ce-a21aff7af429', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 15, 15, 'for the chief things of the ancient mountains, for the precious things of the everlasting hills,'),
  ('8ad1b52c-cbeb-5c5f-a00b-8c5c093bea4b', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 16, 16, 'for the precious things of the earth and its fullness, the good will of him who lived in the bush. Let [the blessing] come on the head of Joseph, On the crown of the head of him who was separate from his brothers.'),
  ('db483c65-7d01-551e-a85a-30cb1a5c61c8', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 17, 17, 'The firstborn of his herd, majesty is his. His horns are the horns of the wild ox. With them he shall push the peoples all of them, [even] the ends of the earth: They are the ten thousands of Ephraim. They are the thousands of Manasseh."'),
  ('7c21c5f5-3f38-5c87-a725-ef568e68a637', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 18, 18, 'Of Zebulun he said, "Rejoice, Zebulun, in your going out; and Issachar, in your tents.'),
  ('b1f8a589-fd16-5044-aec1-c60a2f72e987', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 19, 19, 'They shall call the peoples to the mountain. There they will offer sacrifices of righteousness, for they shall draw out the abundance of the seas, the hidden treasures of the sand."'),
  ('31e75954-b915-521d-a57a-8e6da9b01238', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 20, 20, 'Of Gad he said, "He who enlarges Gad is blessed. He dwells as a lioness, and tears the arm, yes, the crown of the head.'),
  ('c957ac72-31de-5c76-a4ae-015f79d997ae', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 21, 21, 'He provided the first part for himself, for there was the lawgiver''s portion reserved. He came [with] the heads of the people. He executed the righteousness of Yahweh, His ordinances with Israel."'),
  ('631c7bd4-309c-57be-a428-606fe7c62147', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 22, 22, 'Of Dan he said, "Dan is a lion''s cub that leaps out of Bashan."'),
  ('82d8359e-bb77-52a1-a906-e3d5b48ee381', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 23, 23, 'Of Naphtali he said, "Naphtali, satisfied with favor, full of the blessing of Yahweh, Possess the west and the south."'),
  ('7ebf89d8-60a6-5675-afce-a59265e61f4a', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 24, 24, 'Of Asher he said, "Asher is blessed with children. Let him be acceptable to his brothers. Let him dip his foot in oil.'),
  ('b047ec06-71b9-51d0-a7b0-52b3c2b16c38', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 25, 25, 'Your bars shall be iron and brass. As your days, so your strength will be.'),
  ('f5246b5f-0811-5137-a14f-4e4a662ea7bc', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 26, 26, '"There is none like God, Jeshurun, who rides on the heavens for your help, In his excellency on the skies.'),
  ('2e2b3fdf-cca6-5a95-af7b-7ecf568fe5be', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 27, 27, 'The eternal God is [your] dwelling place. Underneath are the everlasting arms. He thrust out the enemy from before you, and said, ''Destroy!'''),
  ('177e2f2c-f5bc-5941-ae5c-8fe5e2693c50', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 28, 28, 'Israel dwells in safety; the fountain of Jacob alone, In a land of grain and new wine. Yes, his heavens drop down dew.'),
  ('796ff682-c967-5a33-a560-f63311e71893', '9948f761-dbff-5648-ad4e-09b85e3dad38', NULL, 29, 29, 'You are happy, Israel. Who is like you, a people saved by Yahweh, the shield of your help, the sword of your excellency! Your enemies shall submit themselves to you. You shall tread on their high places."'),
  ('684f0c9f-e4b7-5677-a056-1c8b7ea81c2a', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 1, 1, 'Moses went up from the plains of Moab to Mount Nebo, to the top of Pisgah, that is over against Jericho. Yahweh showed him all the land of Gilead, to Dan,'),
  ('a676df1f-6d2e-598d-a474-427866b29e18', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 2, 2, 'and all Naphtali, and the land of Ephraim and Manasseh, and all the land of Judah, to the hinder sea,'),
  ('60b577fc-6290-5347-a35a-f6bc83b10645', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 3, 3, 'and the South, and the Plain of the valley of Jericho the city of palm trees, to Zoar.'),
  ('00e9a87f-0a7f-5f9d-ab85-eeefc6983beb', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 4, 4, 'Yahweh said to him, "This is the land which I swore to Abraham, to Isaac, and to Jacob, saying, ''I will give it to your seed.'' I have caused you to see it with your eyes, but you shall not go over there."'),
  ('46054889-5203-54d8-ab9c-47bac14c62c5', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 5, 5, 'So Moses the servant of Yahweh died there in the land of Moab, according to the word of Yahweh.'),
  ('638d9afc-75fe-527d-aae8-5f9710d87066', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 6, 6, 'He buried him in the valley in the land of Moab over against Beth Peor: but no man knows of his tomb to this day.'),
  ('5a21e660-40cf-5d79-a061-30557a1e2c5c', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 7, 7, 'Moses was one hundred twenty years old when he died: his eye was not dim, nor his natural force abated.'),
  ('8adf0fa6-bd4a-5249-a354-4faeb09b4462', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 8, 8, 'The children of Israel wept for Moses in the plains of Moab thirty days: so the days of weeping in the mourning for Moses were ended.'),
  ('0512ba59-2785-57e1-aad2-72c0728e4705', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 9, 9, 'Joshua the son of Nun was full of the spirit of wisdom; for Moses had laid his hands on him: and the children of Israel listened to him, and did as Yahweh commanded Moses.'),
  ('69801d6b-33f4-541b-a9a6-509cca0c8fc0', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 10, 10, 'There has not arisen a prophet since in Israel like Moses, whom Yahweh knew face to face,'),
  ('6bc588c9-ad94-54cd-a32e-b3f3bb63e92d', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 11, 11, 'in all the signs and the wonders, which Yahweh sent him to do in the land of Egypt, to Pharaoh, and to all his servants, and to all his land,'),
  ('76866bc6-6c3e-5a00-a5cc-6743016c9686', '4998eb44-51ff-5545-a96b-0df62e029974', NULL, 12, 12, 'and in all the mighty hand, and in all the great terror, which Moses worked in the sight of all Israel.'),
  ('44d32081-6a4f-5ef3-a228-1e8c2a40eaac', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 1, 1, 'Now it happened after the death of Moses the servant of Yahweh, that Yahweh spoke to Joshua the son of Nun, Moses'' servant, saying,'),
  ('816823e9-73a4-507e-a2e8-5fe4f3e293c6', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 2, 2, '"Moses my servant is dead; now therefore arise, go over this Jordan, you, and all this people, to the land which I give to them, even to the children of Israel.'),
  ('5adce4b1-c2f0-53ce-a0b7-bc9bb2cacca4', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 3, 3, 'I have given you every place that the sole of your foot will tread on, as I told Moses.'),
  ('8d3bd4cd-699c-51c2-aa9a-41ce2c64964e', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 4, 4, 'From the wilderness, and this Lebanon, even to the great river, the river Euphrates, all the land of the Hittites, and to the great sea toward the going down of the sun, shall be your border.'),
  ('b637e0e6-9998-5841-a513-076d766eb439', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 5, 5, 'No man will be able to stand before you all the days of your life. As I was with Moses, so I will be with you. I will not fail you nor forsake you.'),
  ('5a21f2ad-2885-5c0b-a389-106384acada5', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 6, 6, '"Be strong and courageous; for you shall cause this people to inherit the land which I swore to their fathers to give them.'),
  ('9e5a6599-b74a-578c-ae16-103cee6b7c4b', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 7, 7, 'Only be strong and very courageous, to observe to do according to all the law, which Moses my servant commanded you. Don''t turn from it to the right hand or to the left, that you may have good success wherever you go.'),
  ('2f3fa417-461f-56a1-aca7-f39f199890cc', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 8, 8, 'This book of the law shall not depart out of your mouth, but you shall meditate on it day and night, that you may observe to do according to all that is written therein: for then you shall make your way prosperous, and then you shall have good success.'),
  ('13e4cf22-9ae5-5db9-a24b-0e92acb116cb', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 9, 9, 'Haven''t I commanded you? Be strong and courageous. Don''t be afraid, neither be dismayed: for Yahweh your God is with you wherever you go."')
